body_md:
Throughout this paper, $C>0$ and $c>0$ denote some constants independent of time, and $C_{T}>0$ is a constant which may depend on time $T$. For $p\in[1,\infty]$ and integer $k\geq 0$, the simplified  Lebesgue, Sobolev and H$\rm{\ddot{o}}$lder norms are given as follows:
\begin{equation}\nonumber
\left\{
\begin{split}
&\|\cdot \|_{L^{p}}=:\|\cdot \|_{L^{p}(\Omega )},\quad \|\cdot \|_{H^{k}}=:\|\cdot\|_{H^{k}(\Omega )},\quad\|\cdot \|_{C^{k}}=:\|\cdot\|_{C^{k}(\Omega )},\\
& \|\cdot \|_{\mathcal{L}^p}=:\|\cdot \|_{L^p(\Omega \times\mathbb{R} )},\quad \|\cdot \|_{\mathcal{H}^{k}}=:\|\cdot \|_{H^{k}(\Omega \times\mathbb{R})},\quad \|\cdot \|_{\mathcal{C}^{k}}=:\|\cdot \|_{C^{k}(\Omega \times\mathbb{R})}.
\end{split}
\right .
\end{equation}
Let $n$ and $w$ denote the average local density and velocity of distribution function $f$ to the Vlasov equation $(\ref{m1})_{3}$ respectively as
\begin{align}
n(x,t)=:\int_{\mathbb{R}} f(x,v,t)dv,\quad nw(x,t)=:\int_{\mathbb{R}}vf(x,v,t)dv.\label{nw}
\end{align}

\label{theorem11}
Let $\Omega=\mathbb{T}$. Assume that the initial data $(\rho_{0},u_{0},f_{0})$ satisfies
\begin{equation}\label{a1}
\left\{
\begin{split}
&\inf_{x\in\mathbb{T} }\rho_{0}(x)>0,\quad \rho_{0}\in W^{1,\infty}(\mathbb{T}),\quad u_{0}\in H^1(\mathbb{T} ),\\
 &0\leq f_{0}\in L^{\infty}(\mathbb{T}\times\mathbb{R}),\quad \text{{\rm{Supp}}}_{v}f_{0}(x,\cdot)\subset \{v\in\mathbb{R}~\big{|}~|v|\leq R_{0}\},\quad  x\in\mathbb{T},
\end{split}
\right .
\end{equation}
 where $R_{0}>0$ is a constant. Then the IVP $(\ref{m1})$-$(\ref{kappa})$ admits a unique global weak solution $(\rho,u,f)$ satisfying for any $T>0$ that
\begin{equation}\label{r1}
\left\{
\begin{split}
& \rho\in C([0,T];H^1(\mathbb{T}))\cap L^{\infty}(0,T;W^{1,\infty}(\mathbb{T})),\\
&u\in C([0,T];H^1(\mathbb{T} ))\cap L^2(0,T;H^2(\mathbb{T} )),\quad u_{t}\in L^2(0,T;L^2(\mathbb{T})),\\
 &f\in C([0,T];L^1(\mathbb{T}\times\mathbb{R}))\cap L^{\infty}(0,T;L^{\infty}(\mathbb{T} \times\mathbb{R})),
\end{split}
\right .
\end{equation}
and
\begin{equation}\label{r11}
\left\{
\begin{split}
&0<\rho_{-}\leq \rho\leq \rho_{+},\quad \sup_{t\in [0,T]}\|\rho(t)\|_{H^1}\leq C_{0},\\
&0\leq f\leq e^{\rho_{+}T}\|f_{0}\|_{\mathcal{L}^{\infty}},\\
&\text{{\rm{Supp}}}_{v}f(x,\cdot, t)\subset \{v\in\mathbb{R}~|~|v|\leq R_{1}\},\quad(x,t)\in \mathbb{T}\times[0,T],
\end{split}
\right.
\end{equation}
where $\rho_{-}>0, \rho_{+}>0, C_{0}>0$ and $R_{1}>0$ are constants independent of time $T>0$.

 In addition to $(\ref{a1})$, if it further holds
\begin{align}
&\rho_{0}\in H^2(\mathbb{T} ),\quad u_{0}\in H^2(\mathbb{T} ),\quad f_{0}\in C^{1}(\mathbb{T} \times\mathbb{R}),\label{a11}
\end{align}
then $(\rho, u, f)$ is indeed a global strong solution satisfying for any $T>0$ that
\begin{equation}
\left\{
\begin{split}
&\rho\in C([0,T];H^2(\mathbb{T} )),~~\rho_{t}\in C([0,T];H^1(\mathbb{T} )),\\
&u\in C([0,T];H^2(\mathbb{T} )),\quad t^{\frac{1}{2}}u\in L^{\infty}(0,T;H^3(\mathbb{T} )),\quad t^{\frac{1}{2}}u_{t}\in L^{\infty}(0,T;H^1(\mathbb{T} )),\\
&f\in C([0,T];C^{1}(\mathbb{T} \times\mathbb{R} )),\quad f_{t}\in C([0,T];C^{0}(\mathbb{T} \times\mathbb{R} )).\label{r12}
\end{split}
\right .
\end{equation}

\label{decay}
Let the assumptions of Theorem \ref{theorem11} hold, and $(\rho,u,f)$ be the global solution to the IVP $(\ref{m1})$-$(\ref{kappa})$ given by Theorem \ref{theorem11}. Then it holds
\begin{equation}\label{decay11}
\left\{
\begin{split}
&\|(\rho-\overline{\rho_{0}})(t)\|_{C^{0}}+\|(u-u_{s})(t)\|_{L^{2}}\leq C_{1}e^{-\lambda t},\\
&\|\big{(}\sqrt{f}(v-u_{s})\big{)}(t)\|_{\mathcal{L}^2}+{\rm{W}}_{1}\big{(}f(t),(n\delta(v-u_{s}))(t)\big{)}\leq C_{1}e^{-\lambda t},\\
&\text{{\rm{Supp}}}_{v}f(x,\cdot, t)\subset \{v\in\mathbb{R}~|~|v-u_{s}|\leq C_{1}e^{-\lambda t}\},\quad (x,t)\in \mathbb{T}\times \mathbb{R}_{+},
\end{split}
\right.
\end{equation}
where ${\rm{W}}_{1}(f,g)$ is the Wasserstein distance given by Definition 1.1, $C_{1}>0$ and $\lambda>0$ are two constants independent of time, and $\overline{\rho_{0}}$ and $u_{s}$ are given by
\begin{equation}\label{rhoinfty}
\left\{
\begin{split}
&\overline{\rho_{0}}=:\int_{\mathbb{T}}\rho_{0}(x)dx,\\
& u_{s}=:\frac{\int_{\mathbb{T}}\rho_{0}u_{0}(x)dx+\int_{\mathbb{T}\times\mathbb{R}}vf_{0}(x,v)dvdx} {\int_{\mathbb{T}}\rho_{0}(x)dx+ \int_{\mathbb{T}\times\mathbb{R}}f_{0}(x,v)dvdx}.
\end{split}
\right.
\end{equation}

\label{theorem12}
Let $\Omega=\mathbb{R}$. Assume that the initial data $(\rho_{0},u_{0},f_{0})$ satisfies
 \begin{equation}\label{a2}
 \left\{
 \begin{split}
 &\inf_{x\in\mathbb{R}}\rho_{0}(x)>0,\quad \rho_{0}-\widetilde{\rho}\in H^1\cap W^{1,\infty}(\mathbb{R}),\quad u_{0}\in H^1(\mathbb{R}),\\
 &0\leq f_{0}\in L^1\cap L^{\infty}(\mathbb{R}\times\mathbb{R}), \quad \text{{\rm{Supp}}}_{v}f_{0}(x,\cdot)\subset \{v\in\mathbb{R}~\big{|}~|v|\leq \widetilde{R}_{0}\},\quad x\in\mathbb{R},
\end{split}
\right .
\end{equation}
where $\widetilde{\rho}>0$ and $\widetilde{R}_{0}>0$ are two constants. Then the IVP $(\ref{m1})$-$(\ref{kappa})$ admits a unique global weak solution $(\rho,u,f)$ satisfying for any $T>0$ that
\begin{equation}
\left\{
\begin{split}
&\rho-\widetilde{\rho}\in C([0,T];H^1(\mathbb{R}))\cap L^{\infty}(0,T; W^{1,\infty}(\mathbb{R})),\\
&u\in C([0,T];H^1(\mathbb{R}))\cap L^2(0,T;H^2(\mathbb{R})),\quad u_{t}\in L^2(0,T;L^2(\mathbb{R})),\\
 &f\in C([0,T];L^1(\mathbb{R}\times\mathbb{R}))\cap L^{\infty}(0,T;L^{\infty}(\mathbb{R}\times\mathbb{R})),\label{r2}
\end{split}
\right .
\end{equation}
and
\begin{equation}\label{r21}
\left\{
\begin{split}
&0<\rho_{T}^{-1}\leq\rho\leq \rho_{T},\\
&0\leq f\leq e^{\rho_{T}T}\|f_{0}\|_{\mathcal{L}^{\infty}},\\
&{\rm{Supp}}_{v} f(x,\cdot, t)\subset \{v\in\mathbb{R}~\big{|}~|v|\leq \widetilde{R}_{T}\},\quad (x,t)\in\mathbb{R}\times[0,T],
\end{split}
\right.
\end{equation}
where $\rho_{T}>0$ and $\widetilde{R}_{T}>0$ are constants dependent of time $T>0$.

 In addition to $(\ref{a2})$, if it further holds
\begin{align}
&\rho_{0}-\widetilde{\rho}\in H^2(\mathbb{R}),\quad u_{0}\in H^2(\mathbb{R}),\quad f_{0}\in H^{1}\cap C^{1}(\mathbb{R}\times\mathbb{R}),\label{a22}
\end{align}
then the global weak solution $(\rho, u, f)$ is indeed a strong solution satisfying for any $T>0$ that
\begin{equation}
\left\{
\begin{split}
&\rho-\widetilde{\rho}\in C([0,T];H^2(\mathbb{R})),~~\rho_{t}\in C([0,T];H^1(\mathbb{R})),\\
&u\in C([0,T];H^2(\mathbb{R})),\quad t^{\frac{1}{2}}u\in L^{\infty}(0,T;H^3(\mathbb{R})),\quad t^{\frac{1}{2}}u_{t}\in L^{\infty}(0,T;H^1(\mathbb{R})),\\
&f\in C([0,T];H^1\cap C^{1}(\mathbb{R}\times\mathbb{R} )),\quad f_{t}\in C([0,T];L^2\cap C^{0}(\mathbb{R}\times\mathbb{R} )).\label{r22}
\end{split}
\right .
\end{equation}

\label{lemma21}
Let $T>0$, and $(\rho,u,f)$ be any regular solution to the IVP $(\ref{m1})$-$(\ref{kappa})$ for $t\in (0,T]$. Then, under the assumptions of Theorem \ref{theorem11}, it holds
\begin{equation}
\left\{
\begin{split}
&\rho(x,t)\geq 0,\quad f(x,v,t)\geq0,\quad (x,v,t)\in\mathbb{T}\times\mathbb{R}\times [0,T],\\
&\int_{\mathbb{T}}\rho(x,t) dx=\int_{\mathbb{T}}\rho_{0}(x)dx,\quad t\in[0,T],\\
 &\int_{\mathbb{T}\times\mathbb{R}} f(x,v,t)dvdx=\int_{\mathbb{T}} n(x,t)dx=\int_{\mathbb{T}\times\mathbb{R}}f_{0}(x,v)dx,\quad t\in[0,T],\\
&\sup_{0\leq t\leq T}\bigg{(}\int_{\mathbb{T}}\big{(}\frac{1}{2}\rho|u|^2+\frac{\rho^{\gamma}}{\gamma-1}\big{)}(x,t)dx+\int_{\mathbb{T}\times\mathbb{R}} \frac{1}{2}|v|^2f(x,v,t)dvdx\bigg{)}\\
&\quad\quad+\int_{0}^{T}\int_{\mathbb{T}}(\mu(\rho)|u_{x}|^2)(x,t)dxdt+\int_{0}^{T}\int_{\mathbb{T}\times\mathbb{R}}(\rho|u-v|^2f)(x,v,t)dvdxdt\leq E_{0},\label{basiccnsv}
\end{split}
\right .
\end{equation}
where the initial energy $E_{0}$ is given by
\begin{equation}\label{E0}
\begin{split}
E_{0}=:\int_{\mathbb{T}} \big{(}\frac{1}{2}\rho_{0}|u_{0}|^2+\frac{\rho_{0}^{\gamma}}{\gamma-1}\big{)}(x)dx+\int_{\mathbb{T}\times\mathbb{R}} \frac{1}{2}|v|^2f_{0}(x,v)dvdx.
\end{split}
\end{equation}

Due to the maximum principle for transport equations,  $(\ref{basiccnsv})_{1}$ holds. In addition, $(\ref{basiccnsv})_{2}$-$(\ref{basiccnsv})_{3}$ can be derived after a direct computation. To show $(\ref{basiccnsv})_{4}$, multiplying $(\ref{m1})_{1}$ and $(\ref{m1})_{2}$ by $\frac{\gamma}{\gamma-1}\rho^{\gamma-1}$ and $u$ respectively, and integrating the resulted equations by parts over $\mathbb{T}$, one gets after adding them together that
\begin{equation}
\begin{split}
&\frac{d}{dt}\int_{\mathbb{T}}\big{(}\frac{1}{2}\rho |u|^2+\frac{\rho^{\gamma}}{\gamma-1}\big{)}(x,t)dx+\int_{\mathbb{T}}(\mu(\rho)|u_{x}|^2)(x,t)dx\\
&\quad=-\int_{\mathbb{T}\times\mathbb{R}}\rho(x,t) (u(x,t)-v)u(x,t)f(x,v,t)dvdx.\label{energyfluid}
\end{split}
\end{equation}
Multiplying $(\ref{m1})_{3}$ by $\frac{1}{2}|v|^2$, and integrating the resulted equation by parts over $\mathbb{T}\times\mathbb{R}$, we obtain
\begin{equation}
\begin{split}
\frac{d}{dt}\int_{\mathbb{T}\times\mathbb{R}} \frac{1}{2}|v|^2f(x,v,t)dvdx=\int_{\mathbb{T}\times\mathbb{R}}\rho(x,t) (u(x,t)-v)vf(x,v,t)dvdx.\label{energyparticle}
\end{split}
\end{equation}
 The combination of (\ref{energyfluid})-(\ref{energyparticle}) gives rise to $(\ref{basiccnsv})_{4}$. The proof of Lemma \ref{lemma21} is completed.

\label{lemma22}
Let $T>0$, and $(\rho,u,f)$ be any regular solution to the IVP $(\ref{m1})$-$(\ref{kappa})$ for $t\in(0,T]$. Then, under the assumptions of Theorem \ref{theorem11}, it holds
\begin{equation}
\begin{split}
&0<\frac{1}{C_{T}}\leq\rho(x,t)\leq \rho_{+},\quad (x,t)\in\mathbb{T}\times [0,T],\label{rhocnsv}
\end{split}
\end{equation}
where $\rho_{+}>0$ is a constant independent of time $T>0$, and $C_{T}>0$ is a constant dependent of time $T>0$.

We introduce a new effective velocity
 $$
 u+\mathcal{I}(n),
  $$
  where the operator $\mathcal{I}:L^1(\mathbb{T})\rightarrow L^{\infty}(\mathbb{T})$ is defined by
  \begin{equation}\label{j}
\begin{split}
\mathcal{I}(g)(x)=:\int^{x}_{0}g(y)dy-\int_{0}^{1}\int_{0}^{y}g(z) dzdy,\quad \forall g\in L^1(\mathbb{T}).
\end{split}
\end{equation}
It can be verified verify for $g\in L^1(\mathbb{T})$ that
\begin{equation}
\begin{split}
 \sup_{x\in\mathbb{T}}\mathcal{I}(g)(x)\leq \|g\|_{L^{1}},\quad \big{(}\mathcal{I}(g)(x)\big{)}_{x}=g,\quad \mathcal{I}\big{(}g-\int_{0}^{1}g(y)dy\big{)}(x)\in W^{1,1}(\mathbb{T}),\label{J}
\end{split}
\end{equation}
and for $g\in W^{1,1}(\mathbb{T})$ that
\begin{equation}\label{J1}
\begin{split}
\mathcal{I}(g_{x})(x)=g(x)-\int_{0}^{1}g(y)dy.
\end{split}
\end{equation}
Integrating the equation $(\ref{m1})_{3}$ over $\mathbb{R}$ with respect to velocity variable $v$, we have
\begin{equation}
\begin{split}
n_{t}+(nw)_{x}=0,\label{nj}
\end{split}
\end{equation}
where $n$ and $w$ are defined by $(\ref{nw})$. Applying the operator $\mathcal{I}$ to the equation $(\ref{nj})$, we deduce by (\ref{J1}) that
\begin{equation}\begin{split}\nonumber
(\mathcal{I}(n))_{t}+nw-\int_{0}^{1}nw(y,t)dy=0,
\end{split}\end{equation}
which together with $(\ref{m1})_{1}$, (\ref{nw}) and (\ref{J}) leads to
\begin{equation}\begin{split}\label{drag}
&(\rho\mathcal{I}(n))_{t}+(\rho u\mathcal{I}(n))_{x}=\rho(\mathcal{I}(n))_{t}+\rho u(\mathcal{I}(n))_{x}\\
&\quad\quad\quad\quad\quad\quad\quad\quad\quad=-\rho nw+\rho u n+\rho\int_{0}^{1}nw(y,t)dy\\
&\quad\quad\quad\quad\quad\quad\quad\quad\quad=\int_{\mathbb{R}}\rho(u-v)fdv+\rho\int_{0}^{1}nw(y,t)dy.
\end{split}\end{equation}
 Thus, by virtue of (\ref{drag}), we can re-write the momentum equation $(\ref{m1})_{2}$ as
\begin{equation}\label{newm1}
\begin{split}
&\big{[}\rho (u+\mathcal{I}(n))\big{]}_{t}+\big{[}\rho u(u+\mathcal{I}(n))\big{]}_{x}+(\rho^{\gamma})_{x}=(\mu(\rho)u_{x})_{x}+\rho \int_{0}^{1}nw(y,t)dy.
\end{split}
\end{equation}
It follows from (\ref{j})-(\ref{J1}) and (\ref{newm1}) that
\begin{equation}\nonumber
\begin{split}
&\big{[}\mathcal{I}\big{(}\rho(u+\mathcal{I}(n))\big{)}\big{]}_{t}\\
&\quad=\int_{0}^{x}\big{[}\rho(u+\mathcal{I}(n))\big{]}_{t}(y,t)dy-\int_{0}^{1}\int_{0}^{y}\big{[}\rho u(u+\mathcal{I}(n))\big{]}_{t}(z,t)dzdy\\
&\quad=-\big{[}\rho u(u+\mathcal{I}(n))+\rho^{\gamma}-\mu(\rho)u_{y}\big{]}|^{y=x}_{y=0}+\int_{0}^{1}nw(y,t)dy\int_{0}^{x}\rho(y,t) dy\\
&\quad\quad+\int_{0}^{1}\big{[}\rho u(u+\mathcal{I}(n))+\rho^{\gamma}-\mu(\rho)u_{z}\big{]}|^{z=y}_{z=0}dy-\int_{0}^{1}nw(y,t)dy\int_{0}^{1}\int_{0}^{y}\rho(z,t) dzdy \\
&\quad=-\rho u(u+\mathcal{I}(n))-\rho^{\gamma}+\mu(\rho)u_{x}\\
&\quad\quad+\int_{0}^{1}\big{[}\rho u(u+\mathcal{I}(n))+\rho^{\gamma}-\mu(\rho)u_{y}\big{]}(y,t)dy+\mathcal{I}(\rho)\int_{0}^{1}nw(y,t)dy,
\end{split}
\end{equation}
which gives rise to
\begin{equation}
\begin{split}
&\big{[}\mathcal{I}\big{(}\rho(u+\mathcal{I}(n))\big{)}\big{]}_{t}+ u\big{[}\mathcal{I}\big{(}\rho(u+\mathcal{I}(n))\big{)}\big{]}_{x}+\rho^{\gamma}\\
&\quad=\mu(\rho)u_{x}+\mathcal{I}(\rho)\int_{0}^{1}nw(y,t)dy+ \int_{0}^{1}\big{[}\rho |u|^2+\rho u\mathcal{I}(n)+\rho^{\gamma}-\mu(\rho)u_{y}\big{]}(y,t)dy.\label{newm2}
\end{split}
\end{equation}
Furthermore, due to the equation $(\ref{m1})_{1}$, it holds
\begin{equation}\label{massrhox}
\begin{split}
\frac{d}{dt}\theta(\rho)+u\theta(\rho)_{x}=\mu(\rho)\frac{\rho_{t}+u\rho_{x}}{\rho}=-\mu(\rho)u_{x},
\end{split}
\end{equation}
where the function $\theta(\rho)$ is given by
\begin{eqnarray}
\label{214} \theta(\rho)=:\int_{1}^{\rho}\frac{\mu(s)}{s}ds=
\begin{cases}
2\log{\rho},
& \mbox{if $\beta=0,$ } \\
\log{\rho}+\frac{\rho^{\beta}-1}{\beta},
& \mbox{if $\beta>0.$}
\end{cases}
\end{eqnarray}
Substituting (\ref{massrhox}) into (\ref{newm2}), and re-writing the resulted equation along the particle path $\mathcal{X}^{x,t}(s)$ for any $(x,t)\in \mathbb{T}\times [0,T]$ defined as
\begin{equation}\label{overlinex}
\left\{ \begin{split}
&\frac{d}{ds}\mathcal{X}^{x,t}(s)=u(\mathcal{X}^{x,t}(s),x),\quad s\in [0,t],\\
&\quad \mathcal{X}^{x,t}(t)=x,
\end{split}
\right.
\end{equation}
 we have
 \begin{equation}\label{newm4}
 \begin{split}
&\frac{d}{ds}\Big{(}\theta(\rho)+\mathcal{I}\big{(}\rho u+\rho\mathcal{I}(n)\big{)}\Big{)}(\mathcal{X}^{x,t}(s),s)+\rho^{\gamma}(\mathcal{X}^{x,t}(s),s)\\
&=F(\mathcal{X}^{x,t}(s),s)-\int_{0}^{1}(\mu(\rho)u_{y})(y,s)dy,
\end{split}
\end{equation}
where $F(x,t)$ is given by
$$
F(x,t)=:\mathcal{I}(\rho)(x,t)\int_{0}^{1}nw(y,t)dy+ \int_{0}^{1}\big{[}\rho |u|^2+\rho u\mathcal{I}(n)+\rho^{\gamma}\big{]}(y,t)dy.
$$
It follows from (\ref{nw}), (\ref{basiccnsv}) and (\ref{J}) for any $(x,t)\in\mathbb{T}\times[0,T]$ that
\begin{equation}\label{F}
\left\{
 \begin{split}
 &|\mathcal{I}\big{(}\rho u+\rho\mathcal{I}(n)\big{)}(x,t)|\leq \|\rho(t)\|_{L^1}^{\frac{1}{2}}\|(\sqrt{\rho}u)(t)\|_{L^2}+\|\rho(t)\|_{L^1}\|n(t)\|_{L^1}\leq C_{2},\\
 &|F(x,t)|\leq  \|\rho(t)\|_{L^1}\|f(t)\|_{\mathcal{L}^{1}}^{\frac{1}{2}}\||v|^2f(t)\|_{\mathcal{L}^1}^{\frac{1}{2}}+\|(\sqrt{\rho}u)(t)\|_{L^2}^2\\
 &\quad\quad\quad~\quad+\|n(t)\|_{L^1}\|\rho(t)\|_{L^{1}}^{\frac{1}{2}}\|(\sqrt{\rho}u)(t)\|_{L^2}+\|\rho^{\gamma}(t)\|_{L^{1}}\leq C_{3},
 \end{split}
 \right.
 \end{equation}
 where $C_{2}>0$ and $C_{3}>0$ are two constants given by
 \begin{equation}\nonumber
\left\{
 \begin{split}
 &C_{2}=:\|\rho_{0}\|_{L^1}^{\frac{1}{2}}(2E_{0})^{\frac{1}{2}}+\|\rho_{0}\|_{L^1}\|f_{0}\|_{\mathcal{L}^1},\\
 &C_{3}=:\big{(}\|\rho_{0}\|_{L^1}\|f_{0}\|_{\mathcal{L}^1}^{\frac{1}{2}}+\|\rho_{0}\|_{L^1}^{\frac{1}{2}}\|f_{0}\|_{\mathcal{L}^1}\big{)}(2E_{0})^{\frac{1}{2}}+(\gamma+1) E_{0}.
 \end{split}
\right.
 \end{equation}
  Since it follows
 \begin{equation}\label{mutheta}
 \left\{
 \begin{split}
 &\mu(\rho)\leq 2,\quad\text{if}\quad0\leq \rho\leq 1,\\
 &\mu(\rho)\leq \beta\theta(\rho)+2,\quad\text{if}\quad\rho\geq 1,
 \end{split}
 \right.
 \end{equation}
we get
  \begin{align}
 &\Big{|}\int_{0}^{1}(\mu(\rho)u_{y})(y,t)dy\Big{|}\nonumber\\
 &\quad\leq \Big{(}\int_{0}^{1}\mu(\rho)(y,t)dy\Big{)}^{\frac{1}{2}}\Big{(}\int_{0}^{1}(\mu(\rho)|u_{y}|^2)(y,t)dy\Big{)}^{\frac{1}{2}}\nonumber\\
&\quad=1+\frac{1}{4} \Big{(}\int_{\{y\in(0,1)|\rho(y,t)\leq 1\}}+\int_{\{y\in(0,1)|\rho(y,t)\geq 1\}}\Big{)}\mu(\rho)(y,t)dy\int_{0}^{1}(\mu(\rho)|u_{y}|^2)(y,t)dy\nonumber\\
&\quad\leq 1+\int_{0}^{1}(\mu(\rho)|u_{y}|^2)(y,t)dy+\frac{\beta}{4}\sup_{x\in\{y\in(0,1)|\rho(y,t)\geq 1\}}\theta(\rho)(x,t)\int_{0}^{1}(\mu(\rho)|u_{y}|^2)(y,t)dy.\label{ux11}
  \end{align}


  Then, the upper bound of $\rho$ uniformly in time can be derived by the arguments due to Zlotnik \cite{zlotnik1}. For any $(x,t)\in\mathbb{T}\times[0,T]$, if there is a time $s\in[0,t]$ such that it holds
 $$
\rho(\mathcal{X}^{x,t}(s),s)> C_{4}=:\max\big{\{}(C_{3}+1)^{\frac{1}{\gamma}},~\sup_{x\in\mathbb{T}}\rho_{0}(x)\big{\}}>1,
$$
 then by the continuity of $\rho(\mathcal{X}^{x,t}(s),s)$ with respect to $s$ and the fact $\rho_{0}(\mathcal{X}^{x,t}(0))\leq C_{4}$, we can find a time $s_{*}\in[0,s)$ to have
 \begin{equation}\label{cutcut}
 \left\{
 \begin{split}
 &\rho(\mathcal{X}^{x,t}(s_{*}),s_{*})=C_{4}, \\
 &\rho(\mathcal{X}^{x,t}(\tau),\tau)>C_{4}\geq (C_{3}+1)^{\frac{1}{\gamma}},\quad \forall \tau\in(s_{*},s].
 \end{split}
 \right.
 \end{equation}
Integrating (\ref{newm4}) over $[s_{*},s]$, we obtain by (\ref{F}) and (\ref{ux11})-(\ref{cutcut}) that
\begin{equation}\nonumber
\begin{split}
&\theta(\rho)(\mathcal{X}^{x,t}(s),s)=\theta(\rho)(\mathcal{X}^{x,t}(s_{*}),s_{*})-\mathcal{I}\big{(}\rho u+\rho\mathcal{I}(n)\big{)}(\mathcal{X}^{x,t}(\tau),\tau)|^{\tau=s}_{\tau=s_{*}}\\
&\quad\quad\quad\quad\quad\quad\quad~~-\int_{s_{*}}^{s}\rho^{\gamma}(\mathcal{X}^{x,t}(\tau),\tau)d\tau+\int_{s_{*}}^{s}F(\mathcal{X}^{x,t}(\tau),\tau)d\tau-\int_{s_{*}}^{s}\int_{0}^{1}(\mu(\rho)u_{y})(y,\tau)dyd\tau\\
&\quad\quad\quad\quad\quad\quad~~\leq \theta(C_{4})+2C_{2}+\int_{s_{*}}^{s}\int_{0}^{1}(\mu(\rho)|u_{y}|^2)(y,\tau)dyd\tau\\
&\quad\quad\quad\quad\quad\quad\quad~~+\frac{\beta}{4}\int_{s_{*}}^{s}\sup_{x\in\{y\in(0,1)|\rho(y,t)\geq 1\}}\theta(\rho)(x,\tau)\int_{0}^{1}(\mu(\rho)|u_{y}|^2)(y,\tau)dyd\tau,
\end{split}
\end{equation}
which together with $(\ref{basiccnsv})_{4}$ and the case $1\leq \rho(\mathcal{X}^{x,t}(s),s)\leq C_{4}$ leads to
\begin{equation}\label{pp}
\begin{split}
&\sup_{x\in\{y\in(0,1)|\rho(y,t)\geq 1\}}\theta(\rho)(x,t)\\
&\quad\quad\leq  \theta(C_{4})+2C_{2}+E_{0}\\
&\quad\quad\quad+\frac{\beta}{4}\int_{0}^{T}\sup_{x\in\{y\in(0,1)|\rho(y,t)\geq 1\}}\theta(\rho)(x,\tau)\int_{0}^{1}(\mu(\rho)|u_{y}|^2)(y,\tau)dyd\tau,\quad t\in[0,T].
\end{split}
\end{equation}
By virtue of $(\ref{basiccnsv})_{4}$, (\ref{pp}) and the Gr${\rm{\ddot{o}}}$nwall's inequality, we have
\begin{equation}\label{upperdd}
\begin{split}
\sup_{x\in\{y\in(0,1)|\rho(y,t)\geq 1\}}\theta(\rho)(x,t)\leq e^{\frac{\beta E_{0}}{4}}\big{(}\theta(C_{4})+2C_{2}+E_{0}\big{)}.
\end{split}
\end{equation}
Thus, we show the upper bound of $\rho$ uniformly in time.




Finally, integrating (\ref{newm4}) over $[0,t]$, one deduces by $(\ref{basiccnsv})_{4}$, the upper bound in (\ref{rhocnsv}), (\ref{overlinex}) and (\ref{F}) for any $(x,t)\in\mathbb{T}\times[0,T]$ that
 \begin{equation}\label{the1234}
 \begin{split}
&\theta(\rho)(x,t)\geq \inf_{x\in\mathbb{T}}\theta(\rho_{0})(x)-\big{|}\mathcal{I}\big{(}\rho u+\rho\mathcal{I}(n)\big{)}(\mathcal{X}^{x,t}(\tau),\tau)|^{\tau=t}_{\tau=0}\big{|}-T\rho_{+}^{\gamma}\\
&\quad\quad\quad\quad\quad-T\sup_{(x,t)\in\mathbb{T}\times[0,T]}|F(x,t)|-\int_{0}^{T}\Big{|}\int_{0}^{1}(\mu(\rho)u_{y})(y,\tau)dy\Big{|}d\tau\\
&\quad\quad\quad\quad\geq \inf_{x\in\mathbb{T}}\theta(\rho_{0})(x)-2C_{2}-(\rho_{+}^{\gamma}+C_{3})T-(\mu(\rho_{+})T)^{\frac{1}{2}}\|\sqrt{\mu(\rho)}u_{x}\|_{L^2(0,T;L^2)}\\
&\quad\quad\quad\quad\geq\inf_{x\in\mathbb{T}}\theta(\rho_{0})(x) -2C_{2} -\frac{\mu(\rho_{+})E_{0}}{4}-(\rho_{+}^{\gamma}+C_{3}+1)T,
 \end{split}\end{equation}
 which together with the fact
 \begin{equation}\label{logrho}
 \left\{
 \begin{split}
 &\theta(\rho)=2\log{\rho},\quad \text{if}~\beta=0,\\
 &\theta(\rho)\leq \log{\rho}+\frac{\rho_{+}^{\beta}}{\beta},\quad\text{if}~\beta>0,
 \end{split}
 \right.
 \end{equation}
yields the time-dependent lower bound of $\rho$. The proof of Lemma \ref{lemma22} is completed.

\label{lemma23}
Let $T>0$, and $(\rho,u,f)$ be any regular solution to the IVP $(\ref{m1})$-$(\ref{kappa})$ for $t\in(0,T]$. Then, under the assumptions of Theorem \ref{theorem11}, it holds
\begin{equation}
\left\{
\begin{split}
&\sup_{t\in[0,T]}\|f(t)\|_{\mathcal{L}^{\infty}}\leq e^{\rho_{+}T}\|f_{0}\|_{\mathcal{L}^{\infty}},\\
&~{\rm{Supp}}_{v}f(x,\cdot,t)\subset \{v\in\mathbb{R}~\big{|}~|v|\leq R_{T}\},\quad (x,t)\in \mathbb{T}\times[0,T],\\
&\sup_{t\in[0,T]}\big{(}\|n(t)\|_{L^{\infty}}+\|\rho_{x}(t)\|_{L^{\infty}}+\|u_{x}(t)\|_{L^2}\big{)}+\|(u_{t},u_{xx})\|_{L^2(0,T;L^2)}\leq C_{T},\label{rhouh1cnsv}
\end{split}
\right .
\end{equation}
where the constant $\rho_{+}>0$ is given by $(\ref{rhocnsv})$, and $R_{T}>0$ and $C_{T}>0$ are two constants.

For any $(x,v,t)\in \mathbb{T}\times\mathbb{R}\times[0,T]$, define the bi-characteristic curves $(X^{x,v,t}(s),V^{x,v,t}(s))$ by
\begin{equation}\label{XV}
\left\{
\begin{split}
&\frac{d}{ds}X^{x,v,t}(s)=V^{x,v,t}(s),\quad s\in [0,t],\\
&\quad X^{x,v,t}(t)=x,\\
&\frac{d}{ds}V^{x,v,t}(s)=\rho(X^{x,v,t}(s),s) \big{(}u(X^{x,v,t}(s),s)-V^{x,v,t}(s)\big{)},\quad s\in [0,t],\\
&\quad V^{x,v,t}(t)=v.
\end{split}
\right .
\end{equation}
It holds by $(\ref{m1})_{3}$ that
\begin{equation}\label{m33}
\begin{split}
f_{t}+vf_{x}+\rho(u-v)f_{v}-\rho f=0,
\end{split}
\end{equation}
which can be re-written along the bi-characteristic curves $(X^{x,v,t}(s),V^{x,v,t}(s))$ as
$$
\frac{d}{ds}f(X^{x,v,t}(s),V^{x,v,t}(s),s)-\rho(X^{x,v,t}(s),s)f(X^{x,v,t}(s),V^{x,v,t}(s),s)=0.
$$
Thus, we have
\begin{equation}
\begin{split}
f(x,v,t)=e^{\int_{0}^{t}\rho(X^{x,v,t}(s),s)ds}f_{0}(X^{x,v,t}(0),V^{x,v,t}(0)).\label{fformula}
\end{split}
\end{equation}
By (\ref{rhocnsv}) and (\ref{fformula}), we have $(\ref{rhouh1cnsv})_{1}$. Then we solve the equation $(\ref{XV})_{3}$ over $[0,s]$ to get
\begin{equation}\nonumber
\begin{split}
&V^{x,v,t}(s)=e^{-\int_{0}^{s}\rho(X^{x,v,t}(\tau),\tau)d\tau}V^{x,v,t}(0)+\int_{0}^{s}e^{-\int_{\tau}^{s}\rho(X^{x,v,t}(\omega),\omega)d\omega}\rho u(X^{x,v,t}(\tau),\tau)d\tau,
\end{split}
\end{equation}
which shows for $s=t$ that
\begin{equation}\label{xv1}
\begin{split}
&v=e^{-\int_{0}^{t}\rho(X^{x,v,t}(\tau),\tau)d\tau}V^{x,v,t}(0)+\int_{0}^{t}e^{-\int_{\tau}^{t}\rho(X^{x,v,t}(\omega),\omega)d\omega}\rho u(X^{x,v,t}(\tau),\tau)d\tau.
\end{split}
\end{equation}
For any $(x,t)\in\mathbb{T}\times[0,T]$, defining
\begin{equation}\label{Sigmadef}
\begin{split}
 \Sigma(x,t)=:\{v\in\mathbb{R}~\big{|}~f(x,v,t)\neq 0\},
\end{split}
\end{equation}
 we have
\begin{equation}\label{Sigma}
\begin{split}
{\rm{Supp}}_{v} f(x,\cdot,t)\subset \{v\in\mathbb{R}~|~|v|\leq \sup_{v\in\Sigma(x,t)}|v|\}.
\end{split}
\end{equation}
 Due to (\ref{fformula}), it holds
\begin{equation}\label{Sigma1}
\begin{split}
V^{x,v,t}(0)\notin {\rm{Supp}}_{v}f_{0}(X^{x,v,t}(0),\cdot)\subset \{v\in\mathbb{R}~\big{|}~|v|\leq R_{0}\}\Rightarrow f(x,v,t)=0.
\end{split}
\end{equation}
 Therefore, one deduces by $(\ref{a1})_{2}$, (\ref{basiccnsv}), (\ref{rhocnsv}) and (\ref{Sigma1}) for any $(x,t)\in\mathbb{T}\times[0,T]$ that
\begin{equation}\label{compactv1}
\begin{split}
&\sup_{v\in\Sigma(x,t)}|v|\leq R_{0}+\rho_{+}\int_{0}^{t}|u(x,s)|ds\\
&\quad\quad\quad\quad~\leq R_{T}=:R_{0}+\rho_{+}E_{0}^{\frac{1}{2}}\Big{(}T^{\frac{1}{2}}+\frac{2^{\frac{1}{2}}T}{\|\rho_{0}\|_{L^1}^{\frac{1}{2}}}\Big{)},
\end{split}
\end{equation}
where we have used the fact
\begin{equation}\label{uinfty1}
\begin{split}
&u(x,t)=\frac{\int_{\mathbb{T}}\rho(y,t)\int^{x}_{y}u_{z}(z,t)dzdy+\int_{\mathbb{T}}\rho u(y,t)dy}{\int_{\mathbb{T}}\rho(y,t)dy}\\
&\quad\quad~~\leq\|u_{x}(t)\|_{L^2}+\frac{\|(\sqrt{\rho} u)(t)\|_{L^2}}{\|\rho_{0}\|_{L^1}^{\frac{1}{2}}}.
\end{split}
\end{equation}
 The combination of (\ref{Sigma})-(\ref{compactv1}) gives rise to $(\ref{rhouh1cnsv})_{2}$.















Next, we are going to show $(\ref{rhouh1cnsv})_{3}$. Denote the second effective velocity as
\begin{equation}\label{m}
\begin{split}
U=:u+\mathcal{I}(n)+\rho^{-2}\mu(\rho)\rho_{x}.
\end{split}
\end{equation}
It is easy to verify
\begin{equation}\label{bdx}
\begin{split}
&-(\mu(\rho)u_{x})_{x}=(\rho^{-1}\mu(\rho)\rho_{t})_{x}+(\rho^{-1}\mu(\rho)u \rho_{x})_{x}\\
&\quad\quad\quad\quad\quad~=\rho(\rho^{-2}\mu(\rho)\rho_{x})_{t}+\rho u(\rho^{-2}\mu(\rho)\rho_{x})_{x},
\end{split}
\end{equation}
derived from $(\ref{m1})_{1}$, and
\begin{equation}\nonumber
\begin{split}
(\rho^{\gamma})_{x}=\gamma\rho^{\gamma+1}\mu(\rho)^{-1}U-\gamma\rho^{\gamma+1}\mu(\rho)^{-1}(u+\mathcal{I}(n)),
\end{split}
\end{equation}
so that the equation (\ref{newm1}) can be re-written as
 \begin{equation}
\begin{split}
\rho(U_{t}+uU_{x})+\gamma\rho^{\gamma+1}\mu(\rho)^{-1}U=\gamma\rho^{\gamma+1}\mu(\rho)^{-1}(u+\mathcal{I}(n))+\rho\int_{0}^{1}nw(y,t)dy.\label{bd}
\end{split}
\end{equation}
Multiplying (\ref{bd}) by $p|U|^{p-2}U$ for any $p\in[2,\infty)$, and integrating the resulted equation by parts over $\mathbb{T}$, we obtain by  (\ref{basiccnsv}), (\ref{rhocnsv}) and (\ref{J}) that
\begin{align}
&\frac{d}{dt}\|(\rho^{\frac{1}{p}}U)(t)\|_{L^{p}}^{p}+ p\gamma\int_{\mathbb{T}} (\rho^{\gamma+1}\mu(\rho)^{-1}|U|^{p})(x,t)dx\nonumber\\
&= p\gamma\int_{\mathbb{T}}\big{[} \big{(}\gamma\rho^{\gamma+1}\mu(\rho)^{-1}(u+\mathcal{I}(n))+\rho\int_{\mathbb{T}}nw(y,t)dy\big{)}|U|^{p-2}U\big{]}(x,t) dx\nonumber\\
&\leq p\big{(}\gamma\rho_{+}^{\gamma}\|u(t)\|_{L^{\infty}}+\gamma\rho_{+}^{\gamma}\|n(t)\|_{L^1}+\|f(t)\|_{\mathcal{L}^1}^{\frac{1}{2}}\||v|^2f\|_{\mathcal{L}^1}\big{)}\|\rho(t)\|_{L^{1}}^{\frac{1}{p}}\|(\rho^{\frac{1}{p}}U)(t)\|_{L^{p}}^{p-1}\nonumber\\
&\leq p\big{(}\gamma\rho_{+}^{\gamma}\|u(t)\|_{L^{\infty}}+\gamma\rho_{+}^{\gamma}\|f_{0}\|_{\mathcal{L}^1}+(2\|f_{0}\|_{\mathcal{L}^1}E_{0})^{\frac{1}{2}}\big{)}\big{(}\|\rho_{0}\|_{L^1}+1\big{)}^{\frac{1}{2}}\|(\rho^{\frac{1}{p}}U)(t)\|_{L^{p}}^{p-1}\nonumber\\
&\leq pC\big{(}1+\|u(t)\|_{L^{\infty}}\big{)}\|(\rho^{\frac{1}{p}}U)(t)\|_{L^{p}}^{p-1}.\label{the221}
\end{align}
We deduce after dividing (\ref{the221}) by $\big{(}\|(\rho^{\frac{1}{p}}U)(t)\|_{L^{p}}^{p}+\varepsilon^{p}\big{)}^{\frac{p-1}{p}}$ that
\begin{equation}\label{ddtU1}
\begin{split}
&\frac{d}{dt}\big{(}\|(\rho^{\frac{1}{p}}U)(t)\|_{L^{p}}^{p}+\varepsilon^{p}\big{)}^{\frac{1}{p}}\leq C\big{(}1+\|u(t)\|_{L^{\infty}}\big{)}.
\end{split}
\end{equation}
Integrating (\ref{ddtU1}) over $[0,t]$, making use of (\ref{basiccnsv}), (\ref{rhocnsv}), (\ref{J}) and (\ref{uinfty1}), and then taking the limit $\varepsilon\rightarrow 0$, we get
\begin{equation}
\begin{split}
&\sup_{t\in[0,T]}\|(\rho^{\frac{1}{p}}U)(t)\|_{L^{p}}\\
&\quad\leq \|\rho_{0}^{\frac{1}{p}}\big{(}u_{0}+\mathcal{I}(\int_{\mathbb{R}}f_{0}(\cdot,v)dv)+\rho_{0}^{-2}\mu(\rho_{0})(\rho_{0})_{x}\big{)}\|_{L^{p}}+C\big{(}1+\|u\|_{L^1(0,T;L^{\infty})}\big{)}\\
&\quad\leq \big{(}1+\|\rho_{0}\|_{L^1}\big{)}^{\frac{1}{2}}\big{(}\|u_{0}\|_{L^{\infty}}+\|f_{0}\|_{\mathcal{L}^1}+\|\rho_{0}^{-2}\mu(\rho_{0})(\rho_{0})_{x}\|_{L^{\infty}}\big{)}\\
&\quad\quad+C\big{(}1+T^{\frac{1}{2}}\|u_{x}\|_{L^2(0,T;L^2)}+T\|\sqrt{\rho}u\|_{L^{\infty}(0,T;L^2)}\big{)}\\
&\quad\leq C_{5}(1+T),\label{Ulpf}
\end{split}
\end{equation}
where $C_{5}>0$ is a sufficiently large constant independent of time $T>0$ and $p\in [2,\infty)$.
By (\ref{rhocnsv}) and (\ref{Ulpf}), we have
\begin{equation}\label{Ulp}
\begin{split}
&\sup_{t\in[0,T]}\|U(t)\|_{L^{p}}\leq C_{T}^{\frac{1}{p}}\sup_{t\in[0,T]}\|(\rho^{\frac{1}{p}}U)(t)\|_{L^{p}}\leq (C_{T}+1)^{\frac{1}{2}}C_{5}(1+T).
\end{split}
\end{equation}
Since the constant on the right-hand side of (\ref{Ulp}) is independent of $p\in[2,\infty)$, one can take the limit $p\rightarrow \infty$ in (\ref{Ulp}) to obtain
\begin{equation}
\begin{split}
\sup_{t\in[0,T]}\|U(t)\|_{L^{\infty}}\leq (C_{T}+1)^{\frac{1}{2}}C_{5}(1+T).\label{rhow1p}
\end{split}
\end{equation}
Choosing $p=2$ in (\ref{Ulp}), we deduce by (\ref{basiccnsv}), (\ref{rhocnsv}) and (\ref{m}) that
\begin{equation}\label{rhoh1time}
\begin{split}
&\sup_{t\in[0,T]}\|\rho_{x}(t)\|_{L^2} \leq \rho_{+}^{2}\sup_{t\in[0,T]}\|\big{(}U-u-\mathcal{I}(n)\big{)}(t)\|_{L^2}\\
&\quad\quad\quad\quad\quad\quad\quad\leq \rho_{+}^{2} \sup_{t\in[0,T]}\big{(}\|U(t)\|_{L^2}+\|u(t)\|_{L^2}+\|n(t)\|_{L^1}\big{)}\leq C_{T}.
\end{split}
\end{equation}




Then, we divide the equation $(\ref{m1})_{2}$ by $\rho$ to get
\begin{equation}
\begin{split}
 u_{t}-\mu(\rho)\rho^{-1} u_{xx}=G=:nw-nu-\gamma \rho^{\gamma-2}\rho_{x}-uu_{x}+\beta\rho^{\beta-2}\rho_{x}u_{x}.\label{unorho}
\end{split}
\end{equation}
By $(\ref{nw})$ and $(\ref{rhouh1cnsv})_{1}$-$(\ref{rhouh1cnsv})_{2}$, one has
\begin{equation}\label{nl2}
\begin{split}
&\sup_{t\in[0,T]}\|n(t)\|_{L^{\infty}}\leq 2R_{T}\sup_{t\in[0,T]}\|f(t)\|_{\mathcal{L}^{\infty}}\leq 2R_{T}e^{\rho_{+}T}\|f_{0}\|_{\mathcal{L}^{\infty}}.
\end{split}
\end{equation}
It follows from (\ref{basiccnsv}), (\ref{rhocnsv}), (\ref{rhoh1time}), (\ref{nl2}) and the Gagliardo-Nirenberg's inequality that
\begin{equation}\label{GL2}
\begin{split}
&\|G\|_{L^2(0,T;L^2)}\leq \|n\|_{L^{\infty}(0,T;L^{\infty})}^{\frac{1}{2}}\|\sqrt{f}(u-v)\|_{L^2(0,T;\mathcal{L}^2)}+\gamma\|\rho^{\gamma-2}\rho_{x}\|_{L^{\infty}(0,T;L^{2})}\\
&\quad\quad\quad\quad\quad\quad\quad+\big{(}\|u\|_{L^{\infty}(0,T;L^{2})}+\beta\|\rho^{\beta-2}\rho_{x}\|_{L^{\infty}(0,T;L^{2})}\big{)}\|u_{x}\|_{L^2(0,T;L^{\infty})}\\
&\quad\quad\quad\quad\quad\quad\leq C_{T}\big{(}1+\|u_{x}\|_{L^2(0,T;L^{2})}^{\frac{1}{2}}\|u_{xx}\|_{L^2(0,T;L^{2})}^{\frac{1}{2}}\big{)}\\
&\quad\quad\quad\quad\quad\quad\leq C_{T}(1+\|u_{xx}\|_{L^2(0,T;L^{2})}^{\frac{1}{2}}).
\end{split}
\end{equation}
Multiplying (\ref{unorho}) by $-u_{xx}$, and integrating the resulted equation by parts over $\mathbb{T}\times[0,t]$, one concludes from (\ref{GL2}) and the Young's inequality that
\begin{equation}\nonumber
\begin{split}
&\|u_{x}(t)\|_{L^2}^2+\|u_{xx}\|_{L^2(0,t;L^2)}^2\\
&\quad\leq C\big{(}\|(u_{0})_{x}\|_{L^2}^2+\|u_{xx}\|_{L^2(0,t;L^2)}\|G\|_{L^2(0,t;L^2)}\big{)}\\
&\quad\leq C+C_{T}\big{(}\|u_{xx}\|_{L^2(0,t;L^2)}+\|u_{xx}\|_{L^2(0,t;L^2)}^{\frac{3}{2}}\big{)}\\
&\quad\leq C_{T}+\frac{1}{2}\|u_{xx}\|_{L^2(0,t;L^2)}^2,
\end{split}
\end{equation}
from which we infer
\begin{equation}\label{uh1}
\begin{split}
\sup_{t\in[0,T]}\|u_{x}(t)\|_{L^2}+\|u_{xx}\|_{L^2(0,T;L^2)}\leq C_{T}.
\end{split}
\end{equation}
By (\ref{rhocnsv}) and (\ref{unorho})-(\ref{uh1}), it also holds
\begin{equation}\label{utl2}
\begin{split}
\|u_{t}\|_{L^2(0,T;L^2)}=\|\mu(\rho)\rho^{-1} u_{xx}+G\|_{L^2(0,T;L^2)}\leq C_{T}.
\end{split}
\end{equation}
One may get from $(\ref{basiccnsv})_{3}$, (\ref{J}), (\ref{m}), (\ref{rhow1p}), (\ref{uh1}) and the Sobolev embedding $H^1(\mathbb{T})\hookrightarrow L^{\infty}(\mathbb{T})$ that
\begin{equation}\label{rhow1infty}
\begin{split}
&\sup_{t\in[0,T]}\|\rho_{x}(t)\|_{L^{\infty}}\leq \rho_{+}^{2} \sup_{t\in[0,T]}\|\big{(}U-u-\mathcal{I}(n)\big{)}(t)\|_{L^{\infty}}\\
&\quad\quad\quad\quad\quad\quad\quad~\leq \rho_{+}^{2} \sup_{t\in[0,T]}\big{(}\|U(t)\|_{L^{\infty}}+\|u(t)\|_{L^{\infty}}+\|n(t)\|_{L^1}\big{)}\leq C_{T}.
\end{split}
\end{equation}
The combination of (\ref{nl2}) and (\ref{uh1})-(\ref{rhow1infty}) leads to $(\ref{rhouh1cnsv})_{3}$. The proof of Lemma \ref{lemma23} is completed.

\label{lemma24}
Let $T>0$, and $(\rho,u,f)$ be any regular solution to the IVP $(\ref{m1})$-$(\ref{kappa})$ for $t\in(0,T]$. Then, under the assumptions of Theorem \ref{theorem11}, it holds
\begin{equation}
\begin{split}
&\sup_{t\in[0,T]}\Big{(}\|(\rho_{xx},u_{xx})(t)\|_{L^2}+\|\rho_{t}(t)\|_{H^1}+t^{\frac{1}{2}}\|(u_{xxx},u_{tx})(t)\|_{L^2}\\
&\quad\quad\quad\quad+\|f(t)\|_{\mathcal{C}^{1}}+\|f_{t}(t)\|_{\mathcal{C}^{0}}\Big{)}+\|(u_{xxx},u_{xt})\|_{L^2(0,T;L^2)}\leq C_{T},\label{rhoufh2cnsv}
\end{split}
\end{equation}
where $C_{T}>0$ is a constant.

Differentiating $(\ref{m1})_{3}$ with respect to $x$ and $v$ respectively, we have
\begin{equation}\label{fxfv}
\left\{
\begin{split}
&(f_{v})_{t}+v(f_{v})_{x}+\rho(u-v)(f_{v})_{v}-2\rho f_{v}=-f_{x},\\
&(f_{x})_{t}+v(f_{x})_{x}+\rho(u-v)(f_{x})_{v}-\rho f_{x}=\rho_{x}vf_{v}-(\rho u)_{x}f_{v}+\rho_{x}f.
\end{split}
\right.
\end{equation}
Thus, $f_{x}$ and $f_{v}$ can be re-written along the bi-characteristic curves $(X^{x,v,t}(s),V^{x,v,t}(s))$ defined by (\ref{XV}) for any $(x,v,t)\in\mathbb{T}\times\mathbb{R}\times[0,T]$ as
\begin{equation}\label{fxfv1}
\left\{
\begin{split}
&f_{v}(x,v,t)=e^{2\int_{0}^{t}\rho(X^{x,v,t}(s),s)ds}(f_{0})_{v}(X^{x,v,t}(0),V^{x,v,t}(0))\\
&\quad\quad\quad\quad\quad-\int_{0}^{t}e^{2\int_{s}^{t}\rho(X^{x,v,t}(\tau),\tau)d\tau}f_{x}(X^{x,v,t}(s),V^{x,v,t}(s),s)ds,\\
&f_{x}(x,v,t)=e^{\int_{0}^{t}\rho(X^{x,v,t}(s),s)ds}(f_{0})_{x}(X^{x,v,t}(0),V^{x,v,t}(0))\\
&\quad\quad\quad\quad\quad+\int_{0}^{t}e^{\int_{s}^{t}\rho(X^{x,v,t}(\tau),\tau)d\tau}\big{[}\rho_{x}vf_{v}-(\rho u)_{x}f_{v}+\rho_{x}f\big{]}(X^{x,v,t}(s),V^{x,v,t}(s),s)ds,
\end{split}
\right .
\end{equation}
which together with (\ref{rhocnsv}) and (\ref{rhouh1cnsv}) leads to
\begin{equation}\label{fvinfty}
\begin{split}
&\sup_{t\in[0,T]}\|f_{v}(t)\|_{\mathcal{L}^{\infty}}\leq e^{2\rho_{+}T}\Big{(}\|(f_{0})_{v}\|_{\mathcal{L}^{\infty}}+\int_{0}^{T}\|f_{x}(t)\|_{\mathcal{L}^{\infty}}dt\Big{)},
\end{split}
\end{equation}
and
\begin{equation}\label{fxinfty}
\begin{split}
&\sup_{t\in[0,T]}\|f_{x}(t)\|_{\mathcal{L}^{\infty}}\leq e^{\rho_{+}T}\Big{(}\|(f_{0})_{x}\|_{\mathcal{L}^{\infty}}+\int_{0}^{T}\|\big{[}\rho_{x}vf_{v}-(\rho u)_{x}f_{v}+\rho_{x}f\big{]}(t)\|_{\mathcal{L}^{\infty}}dt\Big{)}\\
&\quad\quad\quad\quad\quad\quad\quad~\leq e^{\rho_{+}T}\Big{(}\|(f_{0})_{x}\|_{\mathcal{L}^{\infty}}+\int_{0}^{T}\big{(}\|\rho_{x}(t)\|_{L^{\infty}}R_{T}\|f_{v}(t)\|_{\mathcal{L}^{\infty}}\\
&\quad\quad\quad\quad\quad\quad\quad\quad~+\|(\rho u)_{x}(t)\|_{L^{\infty}}\|f_{v}(t)\|_{\mathcal{L}^{\infty}}+\|\rho_{x}(t)\|_{L^{\infty}}\|f(t)\|_{\mathcal{L}^{\infty}}\big{)}dt\Big{)}\\
&\quad\quad\quad\quad\quad\quad\quad~\leq C_{T}\Big{(}\|(f_{0})_{x}\|_{\mathcal{L}^{\infty}}+1+\int_{0}^{T}\big{(}1+\|u(t)\|_{H^2}\big{)}\|f_{v}(t)\|_{\mathcal{L}^{\infty}}dt\Big{)},
\end{split}
\end{equation}
where the constants $\rho_{+}>0$ and $R_{T}>0$ are given by (\ref{rhocnsv}) and $(\ref{rhouh1cnsv})_{2}$ respectively. Substituting (\ref{fxinfty}) into (\ref{fvinfty}), and employing a Gr${\rm{\ddot{o}}}$nwall type argument, we obtain
\begin{equation}\label{fw1inftycnsv}
\begin{split}
\sup_{t\in[0,T]}\|(f_{x},f_{v})(t)\|_{\mathcal{L}^{\infty}}\leq C_{T}e^{\|u\|_{L^1(0,T;H^2)}}\big{(}\|[(f_{0})_{x},(f_{0})_{v}]\|_{\mathcal{L}^{\infty}}+1\big{)}\leq C_{T}.
\end{split}
\end{equation}
By (\ref{rhocnsv}), (\ref{rhouh1cnsv}),  $(\ref{m33})$ and (\ref{fw1inftycnsv}), it holds
\begin{equation}
\begin{split}
&\sup_{t\in[0,T]}\|f_{t}(t)\|_{\mathcal{L}^{\infty}}\\
&\quad=\sup_{t\in[0,T]}\|\big{[}vf_{x}+\rho(u-v)f_{v}-\rho f\big{]}(t)\|_{\mathcal{L}^{\infty}}\\
&\quad\leq \sup_{t\in[0,T]}\Big{(}R_{T}\|f_{x}(t)\|_{\mathcal{L}^{\infty}}+\rho_{+}\big{(}\|u(t)\|_{L^{\infty}}+R_{T}\big{)}\|f_{v}(t)\|_{\mathcal{L}^{\infty}}+\rho_{+}\|f(t)\|_{\mathcal{L}^{\infty}}\Big{)}\leq C_{T}.\label{fw1inftycnsv2}
\end{split}
\end{equation}
Then one deduces by (\ref{rhouh1cnsv}) and (\ref{fw1inftycnsv})-(\ref{fw1inftycnsv2}) that
\begin{equation}\label{nxt}
\left\{
\begin{split}
&\sup_{t\in[0,T]}\|(n_{x},n_{t})(t)\|_{L^{\infty}}\leq 2R_{T}\sup_{t\in[0,T]}\|(f_{x},f_{t})(t)\|_{\mathcal{L}^{\infty}}\leq C_{T},\\
&\sup_{t\in[0,T]}\|[(nw)_{x},(nw)_{t}](t)\|_{ L^{\infty}}\leq 2R_{T}^2\sup_{t\in[0,T]}\|(f_{x},f_{t})(t)\|_{\mathcal{L}^{\infty}}\leq C_{T}.
\end{split}
\right.
\end{equation}


We turn to establish the $H^2$-norm estimate of $\rho$. Dividing (\ref{bd}) by $\rho$, and differentiating the resulted equation with respect to $x$, we have
\begin{equation}\label{Ux}
\begin{split}
&\frac{d}{dt}U_{x}+\gamma\rho^{\gamma}\mu(\rho)^{-1}U_{x}=-(uU_{x})_{x}-\gamma(\rho^{\gamma}\mu(\rho)^{-1})_{x}\rho^{-2}\mu(\rho)\rho_{x}+\gamma\rho^{\gamma}\mu(\rho)^{-1}(u_{x}+n).
\end{split}
\end{equation}
Multiplying (\ref{Ux}) by $U_{x}$, and integrating the resulted equation by parts over $\mathbb{T}$, one deduces by (\ref{rhocnsv}) and (\ref{rhouh1cnsv}) that
\begin{equation}\nonumber
\begin{split}
&\frac{1}{2}\frac{d}{dt}\|U_{x}(t)\|_{L^2}^2+\gamma\int_{\mathbb{T}}(\rho^{\gamma}\mu(\rho)^{-1}|U_{x}|^2)(x,t)dx\\
&~~\leq \frac{1}{2}\|u_{x}(t)\|_{L^{\infty}}\|U_{x}(t)\|_{L^2}^2+C_{T}\big{(}\|\rho_{x}(t)\|_{L^2}\|\rho_{x}(t)\|_{L^{\infty}}+\|u_{x}(t)\|_{L^{\infty}}+\|n(t)\|_{L^2}\big{)}\|U_{x}(t)\|_{L^2}\\
&~~\leq C_{T}\big{(}\|u_{x}(t)\|_{H^1}+1\big{)}\|U_{x}(t)\|_{L^2}^2+C_{T}\|u_{x}(t)\|_{H^1}^2+C_{T},
\end{split}
\end{equation}
which implies
\begin{equation}
\begin{split}
&\sup_{t\in[0,T]}\|U_{x}(t)\|_{L^2}^2\leq e^{C_{T}(\|u_{x}\|_{L^1(0,T;H^1)}+1)}\big{(}\|U_{x}(0)\|_{L^2}^2+C_{T}\|u_{x}\|_{L^2(0,T;H^1)}^2+C_{T}\big{)}.\label{rhoh22}
\end{split}
\end{equation}
Thereby, it follows from  (\ref{rhocnsv}), (\ref{rhouh1cnsv}), (\ref{m}) and (\ref{rhoh22}) that
\begin{equation}\label{rhoh2}
\begin{split}
&\sup_{t\in[0,T]}\|\rho_{xx}(t)\|_{L^2}\leq \rho_{+}^2\sup_{t\in[0,T]}\|\big{(}U_{x}-u_{x}-n\big{)}(t)\|_{L^2}\\
&\quad\quad\quad\quad\quad\quad\quad~\leq \rho_{+}^2\sup_{t\in[0,T]}\big{(}\|U_{x}(t)\|_{L^2}+\|u_{x}(t)\|_{L^2}+\|n(t)\|_{L^2}\big{)}\leq C_{T}.
\end{split}
\end{equation}


To establish the $H^2$-estimate of $u$, we differentiate the equation (\ref{unorho}) with respect to variable $x$ to have
\begin{equation}
\begin{split}
u_{xt}-\mu(\rho)\rho^{-1}u_{xxx}=G_{x}+(\mu(\rho)\rho^{-1})_{x}u_{xx}.\label{ux}
\end{split}
\end{equation}
Multiplying (\ref{ux}) by $-u_{xxx}$, integrating the resulted equation by parts over $\mathbb{T}\times[0,t]$, and making use of (\ref{basiccnsv}), (\ref{rhocnsv}), (\ref{rhouh1cnsv}), (\ref{nxt}) and (\ref{rhoh2}), one may get after a complicated computation  that
\begin{equation}\label{rhouh2cnsv}
\begin{split}
&\sup_{t\in[0,T]}\|u_{xx}(t)\|_{L^2}^2+\|u_{xxx}\|_{L^2(0,T;L^2)}^2\\
&\quad\leq C\big{(}\|(u_{0})_{x}\|_{H^1}^2+\|G_{x}+(\mu(\rho)\rho^{-1})_{x}u_{xx}\|_{L^{2}(0,T;L^2)}^2\big{)}\\
&\quad\leq C_{T}\big{(}1+\|(n,nw)\|_{L^{\infty}(0,T;H^1)}^2+\|\rho\|_{L^{\infty}(0,T;H^2)}^2+\|\rho_{x}\|_{L^{\infty}(0,T;L^{\infty})}\|u_{xx}\|_{L^2(0,T;L^2)}\\
&\quad\quad+\|\rho_{xx}\|_{L^{\infty}(0,T;L^2)}\|u_{x}\|_{L^2(0,T;L^{\infty})}\big{)}\leq C_{T}.
\end{split}
\end{equation}
By $(\ref{m1})_{1}$, (\ref{unorho}) and (\ref{rhoh2})-(\ref{rhouh2cnsv}), it also holds
 \begin{equation}\label{rhouh2cnsv1}
 \left\{
 \begin{split}
&\sup_{t\in {0,T}}\|\rho_{t}(t)\|_{H^1}= \sup_{t\in [0,T]}\|(\rho u)_{x}(t)\|_{H^1}\leq C\sup_{t\in [0,T]}\|\rho(t)\|_{H^2}\|u(t)\|_{H^2}\leq C_{T},\\
&~~\|u_{xt}\|_{L^2(0,T;L^2)}=\|\rho^{-1}\mu(\rho)u_{xxx}+G_{x}+(\mu(\rho)\rho^{-1})_{x}u_{xx}\|_{L^2(0,T;L^2)}\leq C_{T}.
\end{split}
\right.
\end{equation}

We are ready to establish the time-weighted estimates of $u$. We differentiate  (\ref{unorho}) with respect to $t$ to get
 \begin{equation}\label{ut}
 \begin{split}
 u_{tt}-\mu(\rho)\rho^{-1}u_{txx}=G_{t}+(\mu(\rho)\rho^{-1})_{t}u_{xx}.
\end{split}
\end{equation}
Multiplying (\ref{ut}) by $-tu_{txx}$, integrating the resulted equation by parts over $\mathbb{T}$, and making use of the estimates (\ref{rhocnsv}), (\ref{nxt}), (\ref{rhoh2}) and (\ref{rhouh2cnsv})-(\ref{rhouh2cnsv1}), we have
 \begin{equation}\label{buxiang}
 \begin{split}
 &\frac{1}{2}\frac{d}{dt}\Big{(}t\|u_{xt}(t)\|_{L^2}^2\Big{)}+\frac{t}{\rho_{+}}\|u_{xxt}(t)\|_{L^2}^2\\
 &~~\leq\frac{1}{2}\|u_{xt}(t)\|_{L^2}^2+t\|u_{xxt}(t)\|_{L^2}\|[G_{t}+(\mu(\rho)\rho^{-1})_{t}u_{xx}](t)\|_{L^2}\\
  &~~\leq \frac{1}{2}\|u_{xt}(t)\|_{L^2}^2+C_{T}t\|u_{xxt}(t)\|_{L^2} \big{(} 1+\|u_{xt}(t)\|_{L^2} \big{)}\\
  &~~\leq\frac{t}{2\rho_{+}}\|u_{xxt}(t)\|_{L^2}^2+ C_{T}t\|u_{xt}(t)\|_{L^2}^2+\frac{1}{2}\|u_{xt}(t)\|_{L^2}^2+C_{T}.
 \end{split}
 \end{equation}
Thus, one deduces by (\ref{rhouh2cnsv1}), (\ref{buxiang}), the Gr$\rm{\ddot{o}}$nwall's inequality and the fact $tu_{xt}|_{t=0}=0$ that
 \begin{equation}\label{tut}
 \begin{split}
 \sup_{t\in[0,T]}t^{\frac{1}{2}}\|u_{xt}(t)\|_{L^2}\leq C_{T}.
 \end{split}
 \end{equation}
By (\ref{rhocnsv}), (\ref{rhoh2})-(\ref{rhouh2cnsv1}) and (\ref{tut}), it also holds
  \begin{equation}\label{tux}
 \begin{split}
 &\sup_{t\in[0,T]}t^{\frac{1}{2}}\|u_{xxx}(t)\|_{L^2}\\
 &\quad\leq \rho_{+} \sup_{t\in[0,T]}t^{\frac{1}{2}}\|\rho^{-1}\mu(\rho)u_{xxx}(t)\|_{L^2}\\
 &\quad= \rho_{+}\sup_{t\in[0,T]}t^{\frac{1}{2}}\|\big{[}u_{xt}-G_{x}-(\mu(\rho)\rho^{-1})_{x}u_{xx}\big{]}(t)\|_{L^2}\leq C_{T}.
 \end{split}
 \end{equation}
 Since it follows by (\ref{rhoh2}) and (\ref{rhouh2cnsv}) that
 $$
 \sup_{t\in[0,T]}\|(\rho,u)(t)\|_{C^{1}}\leq C \sup_{t\in[0,T]}\|(\rho,u)(t)\|_{H^{2}}\leq C_{T},
 $$
 similarly to (\ref{fxfv})-(\ref{fw1inftycnsv2}),  one can show
  \begin{equation}\label{fc1t}
 \begin{split}
 &\sup_{0\leq t\leq T}\big{(}\|f(t)\|_{\mathcal{C}^1}+\|f_{t}(t)\|_{\mathcal{C}^{0}}\big{)}\leq C_{T}.
  \end{split}
 \end{equation}
The combination of (\ref{fw1inftycnsv})-(\ref{fw1inftycnsv2}), (\ref{rhoh2}), (\ref{rhouh2cnsv})-(\ref{rhouh2cnsv1}) and (\ref{tut})-(\ref{fc1t}) gives rise to (\ref{rhoufh2cnsv}). The proof of Lemma \ref{lemma24} is completed.

\label{lemma25}
Let $(\rho,u,f)$ be any regular solution to the IVP $(\ref{m1})$-$(\ref{kappa})$. Then, under the assumptions of Theorem \ref{theorem11}, there is a sufficiently large time $T_{0}>0$ such that it holds
\begin{equation}\begin{split}
& \int_{\mathbb{T}} \rho^{\gamma}(x,t)dx\geq P_{0}>0,\quad t\geq T_{0},\label{pressure}
\end{split}\end{equation}
where $P_{0}>0$ is a constant independent of time $t$.
\begin{proof}
We claim that it holds
\begin{equation}\begin{split}
\lim_{t \to +\infty}\|(\rho-\overline{\rho_{0}})(t)\|_{L^2}=0,\label{rhobehaviorlp}
\end{split}\end{equation}
where the constant $\overline{\rho_{0}}>0$ is given by $(\ref{rhoinfty})_{1}$. By virtue of (\ref{rhobehaviorlp}), one can prove
\begin{equation}\begin{split}\nonumber
&\lim_{t\rightarrow \infty}\Big{|}\int_{\mathbb{T}}\rho^{\gamma}(x,t)dx-\overline{\rho_{0}}^{\gamma}\Big{|}\\
&\quad\leq \lim_{t\rightarrow \infty}\int_{\mathbb{T}}|\rho^{\gamma}(x,t)-\overline{\rho_{0}}^{\gamma}|dx\\
&\quad\leq \gamma(\rho_{+}+\overline{\rho_{0}})^{\gamma-1} \lim_{t\rightarrow \infty}\|(\rho-\overline{\rho_{0}})(t)\|_{L^2}=0,
\end{split}\end{equation}
which gives rise to (\ref{pressure}).





Indeed, the long time behavior (\ref{rhobehaviorlp}) can be shown by Lemmas \ref{lemma21}-\ref{lemma22} and relative entropy estimates for the compressible Navier-Stokes equations $(\ref{m1})_{1}$-$(\ref{m1})_{2}$. Define
\begin{equation}\nonumber
\left\{
\begin{split}
&\mathcal{E}_{NS}^{\eta}(t)=:\int_{\mathbb{T}}\big{(}\frac{1}{2}\rho|u-m_{1}|^2+\Pi_{\gamma}(\rho|\overline{\rho_{0}})\big{)}(x,t)dx-\eta\int_{\mathbb{T}}[\rho(u-m_{1})\mathcal{I}(\rho-\overline{\rho_{0}})](x,t)dx,\\
 &\mathcal{D}_{NS}^{\eta}(t)=:\int_{\mathbb{T}}(\mu(\rho)|u_{x}|^2)(x,t)dx+\eta\int_{\mathbb{T}}[(\rho^{\gamma}-\overline{\rho_{0}}^{\gamma})(\rho-\overline{\rho_{0}})](x,t)dx\\
&\quad\quad\quad\quad-\eta\int_{\mathbb{T}}\big{[}\overline{\rho_{0}}\rho|u-m_{1}|^2+\mu(\rho)u_{x}(\rho-\overline{\rho_{0}})\big{]}(x,t)dx\\
&\quad\quad\quad\quad+\eta\int_{\mathbb{T}}\big{[}\mathcal{I}(\rho-\overline{\rho_{0}})\big{(}-\rho n(u-w)+\frac{\rho}{\overline{\rho_{0}}}\int_{\mathbb{T}} [\rho n (u-w)](y,t)dy\big{)}\big{]}(x,t)dx,
\end{split}
\right.
\end{equation}
where the operator $\mathcal{I}$ is denoted as (\ref{j}), and $m_{1}(t)$ and $\Pi_{\gamma}(\rho|\overline{\rho_{0}})$ are given by
\begin{equation}\label{m1m2}
\left\{
\begin{split}
&m_{1}(t)=:\frac{\int_{\mathbb{T}}\rho u(x,t)dx}{\int_{\mathbb{T}}\rho_{0}(x)dx},\\
&\Pi_{\gamma}(\rho|\overline{\rho_{0}})=:\frac{\rho^{\gamma}}{\gamma-1}-\frac{\overline{\rho_{0}}^{\gamma}}{\gamma-1}-\frac{\gamma\overline{\rho_{0}}^{\gamma-1}}{\gamma-1}(\rho-\overline{\rho_{0}}).
\end{split}
\right.
\end{equation}
It is easy to verify
\begin{equation}\label{entropyfluid22}
\begin{split}
&\frac{d}{dt}\mathcal{E}_{NS}^{\eta}(t)+\mathcal{D}_{NS}^{\eta}(t)=-\int_{\mathbb{T}}[\rho n(u-w)(u-m_{1})](x,t)dx.
\end{split}
\end{equation}
One can choose a suitably small constant $\eta>0$ to have
\begin{equation}\label{ENSsim}
\left\{
\begin{split}
&\mathcal{E}_{NS}^{\eta}(t)\leq C_{6}(\|(\rho-\overline{\rho_{0}})(t)\|_{L^2}^2+\|\big{(}\sqrt{\rho}(u-m_{1})\big{)}(t)\|_{L^2}^2),\\
&\mathcal{E}_{NS}^{\eta}(t)\geq \frac{1}{C_{6}}(\|(\rho-\overline{\rho_{0}})(t)\|_{L^2}^2+\|\big{(}\sqrt{\rho}(u-m_{1})\big{)}(t)\|_{L^2}^2),\\
&\mathcal{D}^{\eta}_{NS}(t) \geq \frac{1}{2}\|u_{x}(t)\|_{L^2}^2+ C_{7}\mathcal{E}_{NS}^{\eta}(t)-C_{8}\|\big{(}\sqrt{\rho f}(u-v)\big{)}(t)\|_{\mathcal{L}^2}^2,
\end{split}
\right.
\end{equation}
where $C_{6}>1$, $C_{i}>0, i=7,8,$ are constants independent of time $t$, the interested reader can refer to \cite{lhl1} for the details.

In addition, one can show
\begin{equation}\label{pp3}
\begin{split}
&\Big{|}\int_{\mathbb{T}}[\rho n(u-w)(u-m_{1})](x,t)dx\Big{|}\\
&\quad\leq \rho_{+}^{\frac{1}{2}}\|(u-m_{1})(t)\|_{L^{\infty}}\|f(t)\|_{\mathcal{L}^1}^{\frac{1}{2}}\|\big{(}\sqrt{\rho f}(u-v)\big{)}(t)\|_{\mathcal{L}^2}\\
&\quad\leq\frac{1}{2}\|u_{x}(t)\|_{L^2}^2+\frac{\rho_{+}\|f_{0}\|_{\mathcal{L}^1}}{2}\|\big{(}\sqrt{\rho f}(u-v)\big{)}(t)\|_{\mathcal{L}^2}^2,
\end{split}
\end{equation}
where we have used $(\ref{basiccnsv})_{2}$, (\ref{rhocnsv}) and the fact
\begin{equation}\label{um1infty}
\begin{split}
&(u-m_{1})(x,t)=\frac{\int_{\mathbb{T}} \rho(y,t)\int^{x}_{y}u_{z}(z,t)dzdy}{\int_{\mathbb{T}} \rho(y,t)dy}\leq \|u_{x}(t)\|_{L^2},\quad x\in\mathbb{T},\quad t>0.
\end{split}
\end{equation}
Thus, it follows from (\ref{entropyfluid22})-(\ref{pp3}) that
\begin{equation}\label{ddtens}
\begin{split}
&\frac{d}{dt}\mathcal{E}_{NS}^{\eta}(t)+C_{7}\mathcal{E}_{NS}^{\eta}(t)\leq C_{9}\|\big{(}\sqrt{\rho f}(u-v)\big{)}(t)\|_{\mathcal{L}^2}^2,\quad C_{9}=: \frac{\rho_{+}\|f_{0}\|_{\mathcal{L}^1}+2C_{8}}{2}.
\end{split}
\end{equation}
Applying the the Gr${\rm{\ddot{o}}}$nwall's inequality to (\ref{ddtens}), we get
\begin{equation}\label{entropyfluid222}
\begin{split}
&\mathcal{E}_{NS}^{\eta}(t)\leq e^{-C_{7} t}\mathcal{E}_{NS}^{\eta}(0)+C_{9}e^{-\frac{C_{7}t}{2}}\int_{0}^{\frac{t}{2}}\|\big{(}\sqrt{\rho f}(u-v)\big{)}(s)\|_{\mathcal{L}^2}^2ds\\
&\quad\quad\quad\quad+C_{9}\int_{\frac{t}{2}}^{t}\|\big{(}\sqrt{\rho f}(u-v)\big{)}(s)\|_{\mathcal{L}^2}^2ds.
\end{split}
\end{equation}
Since it follows $\|\big{(}\sqrt{\rho f}(u-v)\big{)}(s)\|_{\mathcal{L}^2}^2\in L^1(\mathbb{R}_{+})$ by $(\ref{basiccnsv})_{4}$, the each term on the right-hand side of (\ref{entropyfluid222}) tends to $0$ as $t\rightarrow \infty$, and therefore it holds
\begin{equation}\nonumber
\begin{split}
\lim_{t\rightarrow\infty}\mathcal{E}_{NS}^{\eta}(t)=0,
\end{split}
\end{equation}
which together with $(\ref{ENSsim})_{2}$ leads to  (\ref{rhobehaviorlp}).
\end{proof}

