\label{lemma26}
Let $T>0$, and $(\rho,u,f)$ be any regular solution to the IVP $(\ref{m1})$-$(\ref{kappa})$ for $t\in(0,T]$. Then, under the assumptions of Theorem \ref{theorem11}, it holds
\begin{align}
&\rho(x,t)\geq \rho_{-}>0,\quad (x,t)\in \mathbb{T}\times[0,T],\label{lowerboundrho}
\end{align}
where $\rho_{-}>0$ is a constant independent of time $T>0$.

By (\ref{rhocnsv}), we have
\begin{equation}\label{shorttime1}
\begin{split}
\rho(x,t)\geq \frac{1}{C_{T_{0}}}>0,\quad (x,t)\in \mathbb{T}\times [0,T_{0}],
\end{split}
\end{equation}
where the time $T_{0}>0$ is given by Lemma \ref{lemma25}. 

We prove that the fluid density $\rho$ is uniformly bounded from below for $t\in(T_{0},T]$ in the case $\beta=0$, since the case $\beta>0$ can be dealt with in a similar way. It is easy to show
\begin{equation}\label{momentumfluid}
\begin{split}
&\frac{d}{dt}m_{1}(t)=\frac{1}{\|\rho_{0}\|_{L^1}}\frac{d}{dt}\int_{\mathbb{T}}\rho u(x,t) dx\\
&\quad\quad\quad~~=-\frac{1}{\|\rho_{0}\|_{L^1}}\int_{\mathbb{T}}[\rho n(u-w)](x,t)dx,
\end{split}
\end{equation}
where $m_{1}(t)$ is given by $(\ref{m1m2})_{1}$. By $(\ref{nw})$ and (\ref{momentumfluid}), the equation $(\ref{m1})_{2}$ for $\beta=0$ can be re-written as
\begin{equation}
\begin{split}
&(\rho(u-m_{1}))_{t}+(\rho u(u-m_{1}))_{x}+(\rho^{\gamma})_{x}\\
&\quad=2u_{xx}-\rho n(u-w)+\frac{\rho}{\|\rho_{0}\|_{L^1}}\int_{\mathbb{T}}[\rho n (u-w)](y,t)dy.\label{m21111}
\end{split}
\end{equation}
 Applying the operator $\mathcal{I}$ defined by (\ref{j}) to (\ref{m21111}), and re-writing the resulted equation along the particle path $\mathcal{X}^{x,t}(s)$ given by (\ref{overlinex}) for any $(x,t)\in\mathbb{T}\times[T_{0},T]$ and $s\in[T_{0},t]$, we obtain by (\ref{J})-(\ref{J1}) and (\ref{massrhox}) that
\begin{equation}\label{aaaaa}
\begin{split}
&\frac{d}{ds}\Big{(}\big{[}2\log{\rho}+\mathcal{I}(\rho(u-m_{1}))\big{]}(\mathcal{X}^{x,t}(s),s)+\int_{T_{0}}^{s} A(\mathcal{X}^{x,t}(\tau),\tau)d\tau\Big{)}\\
&\quad=-\rho^{\gamma}(\mathcal{X}^{x,t}(s),s),
\end{split}
\end{equation}
where $A(x,t)$ is given by
 \begin{equation}\label{a}
\begin{split}
 &A(x,t)=:-\int_{0}^{1}\big{[}\rho^{\gamma}+\rho u(u-m_{1})-\mu(\rho)u_{y}\big{]}(y,t)dy\\
 &\quad\quad\quad\quad~+\mathcal{I}\big{(}\rho n(u-w)\big{)}(x,t)-\frac{\mathcal{I}(\rho)(x,t)}{\|\rho_{0}\|_{L^1}}\int_{\mathbb{T}}[\rho n(u-w)](y,t)dy.
\end{split}
\end{equation}
Due to (\ref{basiccnsv}), (\ref{rhocnsv}), (\ref{J}) and (\ref{m1m2}), for any $(x,t)\in\mathbb{T}\times[T_{0},T]$, it holds
\begin{equation}\label{um1}
\begin{split}
&|\mathcal{I}(\rho(u-m_{1}))(x,t)|\\
&\quad\leq \sup_{t\in[0,T]}\|\big{(}\rho (u-m_{1})\big{)}(t)\|_{L^1}\\
&\quad\leq\sup_{t\in[0,T]}\big{(}\|\rho(t)\|_{L^1}^{\frac{1}{2}}\|(\sqrt{\rho}u)(t)\|_{L^2}+\frac{1}{\|\rho_{0}\|_{L^1}}\|\rho(t)\|_{L^1}^{\frac{3}{2}}\|(\sqrt{\rho}u)(t)\|_{L^2}\big{)}\\
&\quad\leq C_{10}=:2(2\|\rho_{0}\|_{L^1}E_{0})^{\frac{1}{2}}.
\end{split}
\end{equation}
By (\ref{basiccnsv}), (\ref{rhocnsv}), (\ref{J}),  (\ref{pressure}), (\ref{um1infty}) and (\ref{a}), for any $t\in[T_{0},T]$ and $s\in [T_{0},t]$, we have
\begin{align}
&\int_{s}^{t}A(\mathcal{X}^{x,t}(\tau),\tau)d\tau\nonumber\\
&\quad\leq -\int_{s}^{t}\int_{\mathbb{T}} \rho^{\gamma}(y,\tau)dyd\tau+\int_{s}^{t}\int_{\mathbb{T}}(\rho |u||u-m_{1}|+\mu(\rho)|u_{y}|)(y,\tau)dyd\tau\nonumber\\
&\quad\quad+2\int_{s}^{t}\int_{\mathbb{T}\times\mathbb{R}}(\rho|u-v|f)(y,v,\tau)dvdyd\tau\nonumber\\
&\quad\leq-P_{0}(t-s)+(t-s)^{\frac{1}{2}}\Big{(}\sup_{\tau\in [T_{0},T]}\big{(} \|\rho(\tau)\|_{L^1}^{\frac{1}{2}}\|(\sqrt{\rho} u)(\tau)\|_{L^2}\big{)}\|u-m_{1}\|_{L^2(T_{0},T;L^{\infty})}\nonumber\\
&\quad\quad+(\mu(\rho_{+}))^{\frac{1}{2}}\|\sqrt{\mu(\rho)}u_{x}\|_{L^2(T_{0},T;L^{2})}+2\rho_{+}^{\frac{1}{2}}\sup_{\tau\in [T_{0},T]}\|f(\tau)\|_{\mathcal{L}^1}^{\frac{1}{2}}\|\sqrt{\rho f}(u-v)\|_{L^2(T_{0},T;\mathcal{L}^2)}\Big{)}\nonumber\\
&\quad\leq -P_{0}(t-s)+(t-s)^{\frac{1}{2}}E_{0}^{\frac{1}{2}}\Big{(}(2\|\rho_{0}\|_{L^1}E_{0})^{\frac{1}{2}}+(\mu(\rho_{+}))^{\frac{1}{2}}+2(\rho_{+}\|f_{0}\|_{\mathcal{L}^1})^{\frac{1}{2}}\Big{)}\nonumber\\
&\quad\leq -\frac{P_{0}}{2}(t-s)+C_{11},\label{aa}
\end{align}
where the constant $C_{11}>0$ is given by
$$
C_{11}=:\frac{E_{0}}{2P_{0}}\Big{(}(2\|\rho_{0}\|_{L^1}E_{0})^{\frac{1}{2}}+(\mu(\rho_{+}))^{\frac{1}{2}}+2(\rho_{+}\|f_{0}\|_{\mathcal{L}^1})^{\frac{1}{2}}\Big{)}^2.
$$
Multiplying (\ref{aaaaa}) by
 $$
-\frac{1}{2}e^{-\frac{1}{2}[2\log{\rho}+\mathcal{I}(\rho(u-m_{1}))](\mathcal{X}^{x,t}(s),s)-\frac{1}{2}\int_{T_{0}}^{s}A(\mathcal{X}^{x,t}(\tau),\tau)d\tau},
$$
we obtain
\begin{equation}\begin{split}\nonumber
&\frac{d}{ds}\Big{(}\rho^{-1}(\mathcal{X}^{x,t}(s),s) e^{-\frac{1}{2}\mathcal{I}(\rho(u-m_{1}))(\mathcal{X}^{x,t}(s),s)-\frac{1}{2}\int_{T_{0}}^{s}A(\mathcal{X}^{x,t}(\tau),\tau)d\tau}\Big{)}\\
&=\frac{1}{2}\rho^{\gamma-1}(\mathcal{X}^{x,t}(s),s)e^{-\frac{1}{2}\mathcal{I}(\rho(u-m_{1}))(\mathcal{X}^{x,t}(s),s)-\frac{1}{2}\int_{T_{0}}^{s}A(\mathcal{X}^{x,t}(\tau),\tau)d\tau},
\end{split}\end{equation}
which together with (\ref{overlinex}) and (\ref{um1})-(\ref{aa}) implies for any $(x,t)\in\mathbb{T}\times [T_{0},T]$ that
\begin{equation}\begin{split}
&\rho^{-1}(x,t)\\
&\quad=\rho^{-1}(\mathcal{X}^{x,t}(T_{0}),T_{0})e^{\frac{1}{2}\mathcal{I}(\rho(u-m_{1}))(x,t)-\frac{1}{2}\mathcal{I}(\rho(u-m_{1}))(\mathcal{X}^{x,t}(T_{0}),T_{0})+\frac{1}{2}\int_{T_{0}}^{t}A(\mathcal{X}^{x,t}(\tau),\tau)d\tau} \\
&\quad\quad+\frac{1}{2}\int_{T_{0}}^{t}\rho^{\gamma-1}(\mathcal{X}^{x,t}(s),s)e^{\frac{1}{2}\mathcal{I}(\rho(u-m_{1}))(x,t)-\frac{1}{2}\mathcal{I}(\rho(u-m_{1}))(\mathcal{X}^{x,t}(s),s)+\frac{1}{2}\int_{s}^{t}A(\mathcal{X}^{x,t}(\tau),\tau)d\tau}ds\\
&\quad\leq \frac{1}{C_{T_{0}}}e^{C_{12}-\frac{P_{0}}{4}(t-T_{0})}+\frac{1}{2}\rho_{+}^{\gamma-1}e^{C_{12}}\int_{T_{0}}^{t}e^{-\frac{P_{0}}{4}(t-s)}ds,\quad C_{12}=:C_{10}+\frac{C_{11}}{2}. \label{longtime}
\end{split}\end{equation}
The combination of (\ref{shorttime1}) and (\ref{longtime}) leads to (\ref{lowerboundrho}). The proof of Lemma \ref{lemma26} is completed.

\label{lemma27}
Let $T>0$, and $(\rho,u,f)$ be any regular solution to the IVP $(\ref{m1})$-$(\ref{kappa})$ for $t\in(0,T]$. Then, under the assumptions of Theorem \ref{theorem11}, it holds
\begin{equation}
\left\{
\begin{split}
&\sup_{t\in[0,T]}\|\rho_{x}(t)\|_{L^2}\leq C_{13},\\
&~{\rm{Supp}}_{v}f(x,\cdot,t)\subset \{v\in\mathbb{R}~\big{|}~|v|\leq R_{1}\},\quad (x,t)\in \mathbb{T}\times[0,T],\label{rhoh1uniform}
\end{split}
\right.
\end{equation}
where $C_{13}>0$ is a constant independent of time $T>0$, and the constant $R_{1}>0$ is denoted by
\begin{equation}\label{Rt}
\begin{split}
R_{1}=:R_{0}+\rho_{+}E_{0}^{\frac{1}{2}}\Big{(}\frac{1}{(2\rho_{-})^{\frac{1}{2}}}+\frac{2^{\frac{1}{2}}}{\rho_{-}\|\rho_{0}\|_{L^1}^{\frac{1}{2}}}\Big{)}.
\end{split}
\end{equation}

Multiplying (\ref{bd}) by $U$ given by (\ref{m}), integrating the resulted equation by parts over $\mathbb{T}$, and using (\ref{basiccnsv}), (\ref{rhocnsv}) and (\ref{lowerboundrho}), we have
\begin{equation}\label{the22}
\begin{split}
&\frac{1}{2}\frac{d}{dt}\|(\sqrt{\rho}U)(t)\|_{L^2}^2+\gamma \rho_{-}^{\gamma}\mu^{-1}(\rho_{+})\|(\sqrt{\rho}U)(t)\|_{L^2}^2\\
&~~\leq\big{(}\gamma\|\rho(t)\|_{L^{\infty}}^{\gamma}\|(\sqrt{\rho}u)(t)\|_{L^2}+\gamma\|\rho(t)\|_{L^{\infty}}^{\gamma}\|\rho(t)\|_{L^1}^{\frac{1}{2}}\|n(t)\|_{L^1}\\
&\quad~~+\|\rho(t)\|_{L^1}^{\frac{1}{2}}\|f(t)\|_{\mathcal{L}^1}^{\frac{1}{2}}\||v|^2f(t)\|_{\mathcal{L}^1}^{\frac{1}{2}}\big{)}\|(\sqrt{\rho}U)(t)\|_{L^2}\\
&~~\leq C_{14}\|(\sqrt{\rho}U)(t)\|_{L^2},
\end{split}
\end{equation}
where the constant $C_{14}>0$ is given by
$$
C_{14}=:\gamma\rho_{+}^{\gamma}(2E_{0})^{\frac{1}{2}}+\gamma\rho_{+}^{\gamma}\|\rho_{0}\|_{L^1}^{\frac{1}{2}}\|f_{0}\|_{\mathcal{L}^1}+(2\|\rho_{0}\|_{L^1}\|f_{0}\|_{\mathcal{L}^1}E_{0})^{\frac{1}{2}}.
$$
We divide (\ref{the22}) by $(\|(\sqrt{\rho}U)(t)\|_{L^2}^2+\varepsilon^2)^{\frac{1}{2}}$ for $\varepsilon>0$, employ the Gr$\rm{\ddot{o}}$nwall's inequality and then take the limit $\varepsilon\rightarrow 0$ to obtain
\begin{equation}\label{U2unifrom}
\begin{split}
&\sup_{t\in[0,T]}\|(\sqrt{\rho}U)(t)\|_{L^2}\leq e^{-\gamma \rho_{-}^{\gamma}\mu^{-1}(\rho_{+})t}\|(\sqrt{\rho}U)(0)\|_{L^2}+C_{14}\int_{0}^{T}e^{-\gamma \rho_{-}^{\gamma}\mu^{-1}(\rho_{+})s}ds.
\end{split}
\end{equation}
Due to (\ref{basiccnsv}), (\ref{rhocnsv}) and (\ref{m}), it holds
\begin{equation}\label{rhoxuniform}
\begin{split}
&\sup_{t\in[0,T]}\|\rho_{x}(t)\|_{L^2} \leq \rho_{+}^{\frac{3}{2}} \sup_{t\in[0,T]} \|\big{(}\sqrt{\rho}(U-u-\mathcal{I}(n))\big{)}(t)\|_{L^2}\\
&\quad\quad\quad\quad\quad\quad~~\leq \rho_{+}^{\frac{3}{2}} \sup_{t\in[0,T]}\big{(}\|(\sqrt{\rho}U)(t)\|_{L^2}+\|(\sqrt{\rho}u)(t)\|_{L^2}+\|\rho(t)\|_{L^1}^{\frac{1}{2}}\|n(t)\|_{L^1}\big{)}.
\end{split}
\end{equation}
By (\ref{basiccnsv}) and (\ref{U2unifrom})-(\ref{rhoxuniform}), we prove $(\ref{rhoh1uniform})_{1}$.




Moreover, one deduces by $(\ref{a1})_{2}$, (\ref{basiccnsv}), (\ref{rhocnsv}), (\ref{Sigma1}), (\ref{uinfty1}) and (\ref{lowerboundrho}) that
\begin{equation}
\begin{split}
&\sup_{v\in\Sigma(x,t)}|v|\leq e^{-\rho_{-}t}R_{0}+\rho_{+}\int_{0}^{t}e^{-\rho_{-}s}|u(x,s)|ds\\
&\quad\quad\quad\quad~\leq R_{0}+\rho_{+}\|u_{x}\|_{L^2(0,t;L^2)}\Big{(}\int_{0}^{t}e^{-2\rho_{-}s}ds\Big{)}^{\frac{1}{2}}\\
&\quad\quad\quad\quad~\quad+\frac{\rho_{+}}{\|\rho_{0}\|_{L^1}^{\frac{1}{2}}}\sup_{s\in[0,t]}\|(\sqrt{\rho}u)(s)\|_{L^2}\int_{0}^{t}e^{-\rho_{-}s}ds\\
&\quad\quad\quad\quad~\leq R_{1}=:R_{0}+\rho_{+}E_{0}^{\frac{1}{2}}\Big{(}\frac{1}{(2\rho_{-})^{\frac{1}{2}}}+\frac{2^{\frac{1}{2}}}{\rho_{-}\|\rho_{0}\|_{L^1}^{\frac{1}{2}}}\Big{)},\quad (x,t)\in\mathbb{T}\times[0,T],\label{compactv}
\end{split}
\end{equation}
where the initial energy $E_{0}$ is given by (\ref{E0}). By (\ref{Sigma}) and (\ref{compactv}), $(\ref{rhoh1uniform})_{2}$ holds. The proof of Lemma \ref{lemma27} is completed.

\emph{Step 1: Construction of global strong solution.} Let the initial data $(\rho_{0},u_{0},f_{0})$ satisfy $(\ref{a1})$ and (\ref{a11}). By Lemma \ref{lemma41} in Appendix, we can obtain the local existence of a unique strong solution to the IVP $(\ref{m1})$-$(\ref{kappa})$.

In the terms of Lemmas \ref{lemma21}-\ref{lemma24} about the uniformly a-priori estimates, we can extend the local solution globally in time and prove that this solution satisfies $(\ref{r1})$-(\ref{r11}) and (\ref{r12}).


\emph{Step 2: Global existence of weak solution.} Assume that the initial data $(\rho_{0},u_{0},f_{0})$ satisfies $(\ref{a1})$. One can regularize the initial data as follows:
\begin{equation}\label{appd}
\begin{split}
(\rho_{0}^{\varepsilon}(x),u_{0}^{\varepsilon}(x),f_{0}^{\varepsilon}(x,v))=( J_{1}^{\varepsilon}\ast\rho_{0}(x),J_{1}^{\varepsilon}\ast u_{0}(x) ,J_{1}^{\varepsilon}\ast J_{2}^{\varepsilon}\ast f_{0}(x,v)),\quad \varepsilon\in(0,1),
\end{split}
\end{equation}
where $J_{1}^{\varepsilon}(x)$ and $J_{2}^{\varepsilon}(v)$ are the Friedrich's mollifiers with respect to variables $x$ and $v$ respectively. Then it is easy to verify
\begin{equation}\label{initialt1}
\left\{
\begin{split}
&\inf_{x\in\mathbb{T}}\rho_{0}^{\varepsilon}(x)\geq \inf_{x\in\mathbb{T}}\rho(x)>0,\quad \|\rho_{0}^{\varepsilon}\|_{W^{1,\infty}}\leq \|\rho_{0}\|_{W^{1,\infty}}, \quad \|u_{0}^{\varepsilon}\|_{H^1}\leq \|u_{0}\|_{H^1},\\
&f_{0}^{\varepsilon}\geq 0,\quad \|f_{0}^{\varepsilon}\|_{\mathcal{L}^{\infty}}\leq \|f_{0}\|_{\mathcal{L}^{\infty}},\quad\text{{\rm{Supp}}}_{v}f^{\varepsilon}_{0}(x,\cdot)\subset \{v\in\mathbb{R}~\big{|}~|v|\leq R_{0}+1\},~  x\in\mathbb{T}.
\end{split}
\right.
\end{equation}
In addition, as $\varepsilon\rightarrow 0$, it holds up to a subsequence (still denoted by $(\rho_{0}^{\varepsilon},u_{0}^{\varepsilon},f_{0}^{\varepsilon})$) that 
\begin{equation}\label{initialt}
\left\{
\begin{split}
&(\rho_{0}^{\varepsilon}, u_{0}^{\varepsilon}, f_{0}^{\varepsilon})\rightarrow (\rho_{0},u_{0},f_{0})\quad \text{in}\quad W^{1,p}(\mathbb{T})\times H^1(\mathbb{T})\times L^{p}(\mathbb{T}\times\mathbb{R}), \quad p\in[1,\infty),\\
&(\rho_{0}^{\varepsilon},f_{0}^{\varepsilon}) \overset{\ast}{\rightharpoonup} (\rho_{0},f_{0})\quad \text{in}\quad W^{1,\infty}(\mathbb{T})\times L^{\infty}(\mathbb{T}\times\mathbb{R}).
\end{split}
\right.
\end{equation}



Let $T>0$ be any given time. It follows from Step 1 that for the initial data $(\rho^{\varepsilon}_{0},u^{\varepsilon}_{0},f^{\varepsilon}_{0})$, the IVP (\ref{m1})-(\ref{kappa}) admits a unique strong solution $(\rho^{\varepsilon},u^{\varepsilon},f^{\varepsilon})$ on $\mathbb{T} \times\mathbb{R}\times[0,T]$.

 Then, by the a-priori estimates established in Lemmas \ref{lemma21}-\ref{lemma23} uniformly with respect to $\varepsilon\in(0,1)$ and the Aubin-Lions's lemma, there is a limit $(\rho,u,f)$ so that as $\varepsilon\rightarrow 0$, it holds up to a subsequence (still denoted by $(\rho^{\varepsilon},u^{\varepsilon}, f^{\varepsilon})$) that
\begin{equation}\label{weakc}
\left\{
\begin{split}
&(\rho^{\varepsilon}, f^{\varepsilon})\overset{\ast}{\rightharpoonup}(\rho,f) \quad\text{in}\quad L^{\infty}(0,T;W^{1,\infty}(\mathbb{T}))\times L^{\infty}(0,T; L^{\infty}(\mathbb{T}\times\mathbb{R})),\\
&u^{\varepsilon}\rightharpoonup u\quad\text{in}\quad L^2(0,T;H^2(\mathbb{T}))\cap H^1(0,T;L^2(\mathbb{T})),\\
&(\rho^{\varepsilon},u^{\varepsilon})\rightarrow (\rho,u)\quad\text{in}~C([0,T];C^{0}(\mathbb{T}))\times C([0,T];C^{0}(\mathbb{T})).
\end{split}
\right .
\end{equation}
By $(\ref{rhouh1cnsv})_{2}$, we have ${\rm{Supp}}_{v}f^{\varepsilon}(x,\cdot,t)\subset \{v\in\mathbb{R}~\big{|}~|v|\leq R_{T}+1\}$  for $(x,t)\in \mathbb{T}\times[0,T]$, and similarly to (\ref{fformula})-(\ref{compactv1}), one can show ${\rm{Supp}}_{v}f(x,\cdot,t)\subset \{v\in\mathbb{R}~\big{|}~|v|\leq R_{T}\}$ for $(x,t)\in \mathbb{T}\times[0,T]$. Therefore, it follows by $(\ref{weakc})_{1}$ that
\begin{equation}\label{weakcc}
\begin{split}
&\lim_{\varepsilon\rightarrow 0}\int_{0}^{T}\int_{\mathbb{T}}\varphi(x,t)\Big{(}\int_{\mathbb{R}} \phi(v) f^{\varepsilon}(x,v,t)dv-\int_{\mathbb{R}} \phi(v)f(x,v,t)dv\Big{)}dxdt\\
&\quad =\lim_{\varepsilon\rightarrow 0}\int_{0}^{T}\int_{\mathbb{T}\times\mathbb{R}} \varphi(x,t)\phi(v)\chi (v)(f^{\varepsilon}-f)(x,v,t)dvdxdt\\
&\quad=0,\quad\quad  \forall \varphi\in C^{\infty}_{0}(\mathbb{T}\times(0,T)),\quad\phi(v)=1, v,
\end{split}
\end{equation}
where $\chi(v)\in C_{0}^{\infty}(\mathbb{R})$ satisfies $\chi(v)=1$ for $|v|\leq R_{T}+1$ and $\chi(v)=0$ for $|v|>R_{T}+2$.

 Since both $\int_{\mathbb{R}} f^{\varepsilon}dv$ and $\int_{\mathbb{R}} vf^{\varepsilon}dv$ are uniformly bounded in $L^{\infty}(0,T;L^{\infty}(\mathbb{T}))$, as $\varepsilon\rightarrow 0$, it holds by (\ref{weakcc}) that
 \begin{equation}\label{ne}
 \left\{
 \begin{split}
& \int_{\mathbb{R}} f^{\varepsilon}dv\overset{\ast}{\rightharpoonup} n=:\int_{\mathbb{R}} fdv \quad\text{in}~L^{\infty}(0,T;L^{\infty}(\mathbb{T})),\\
 &\int_{\mathbb{R}} vf^{\varepsilon}dv\overset{\ast}{\rightharpoonup} nw=:\int_{\mathbb{R}} vfdv \quad\text{in}~L^{\infty}(0,T;L^{\infty}(\mathbb{T})).
 \end{split}
 \right.
 \end{equation}
In addition, it can be verified by (\ref{weakc}) and (\ref{ne}) that $(\rho,u,f)$ solves the equations $(\ref{m1})$ in the sense of distributions. Due to the Sobolev embedding $
L^2(0,T;H^2(\mathbb{T}))\cap H^1(0,T;L^2(\mathbb{T}))\hookrightarrow C([0,T];H^1(\mathbb{T}))$,
it holds
\begin{equation}\label{ch1}
\begin{split}
u\in C([0,T];H^1(\mathbb{T})).
\end{split}
\end{equation}
Employing the theory of renormalized solutions in \cite{diperna1}, we get
\begin{equation}\label{ch2}
\begin{split}
\rho\in C([0,T];H^1(\mathbb{T})),\quad f\in C([0,T];L^1(\mathbb{T}\times\mathbb{R})).
\end{split}
\end{equation}
Finally, it follows from Lemmas \ref{lemma21}-\ref{lemma23} and (\ref{initialt})-(\ref{ch2}) that the weak solution $(\rho,u,f)$ satisfies (\ref{basiccnsv}) and (\ref{rhocnsv}). Then repeating the same arguments as in Lemmas \ref{lemma25}-\ref{lemma27}, we can prove that the expected properties (\ref{r11}) hold for $(\rho,u,f)$.

\label{lemma28}
Let $T>0$, and $(\rho,u,f)$ be any regular solution to the IVP $(\ref{m1})$-$(\ref{kappa})$ for $t\in(0,T]$. Then, under the assumptions of Theorem \ref{theorem12}, it holds
\begin{equation}\label{basicR}
\left\{
\begin{split}
&\rho(x,t)\geq 0,\quad f(x,v,t)\geq 0, \quad (x,v,t)\in\mathbb{R}\times\mathbb{R}\times [0,T],\\
&\int_{\mathbb{R}\times\mathbb{R}} f(x,v,t)dvdx=\int_{\mathbb{R}} n(x,t) dx=\int_{\mathbb{R}\times\mathbb{R}}f_{0}(x,v)dvdx,\quad t\in[0,T],\\
&\sup_{t\in[0,T]}\Big{(}\int_{\mathbb{R}}\big{(}\frac{1}{2}\rho |u|^2+\Pi_{\gamma}(\rho|\widetilde{\rho})\big{)}(x,t)dx+\int_{\mathbb{R}\times\mathbb{R}}\frac{1}{2}|v|^2f(x,v,t)dvdx\Big{)}\\
&\quad+\int_{0}^{T}\int_{\mathbb{R}}(\mu(\rho)|u_{x}|^2)(x,t)dxdt+\int_{0}^{T}\int_{\mathbb{R}\times\mathbb{R}} (\rho|u-v|^2f)(x,v,t)dvdxdt\leq \widetilde{E}_{0},\\
&\|u\|_{L^1(0,T;L^{p})}\leq C_{15}(T+T^{\frac{1}{2}}),\quad p\in[2,\infty],
\end{split}
\right .
\end{equation}
where $\Pi_{\gamma}(\rho|\widetilde{\rho})$ is defined by $(\ref{Pi})$, the initial energy $\widetilde{E}_{0}$ is given by
$$
\widetilde{E}_{0}=:\int_{\mathbb{R}}\big{(}\frac{1}{2}\rho_{0} |u_{0}|^2+\Pi_{\gamma}(\rho_{0}|\widetilde{\rho})\big{)}(x)dx+\int_{\mathbb{R}\times\mathbb{R}}\frac{1}{2} |v|^2f_{0}(x,v)dvdx,
$$
and $C_{15}>0$ is a constant independent of $p$ and $T$.

$(\ref{basicR})_{1}$-$(\ref{basicR})_{2}$ can be derived directly by $(\ref{m1})_{1}$ and $(\ref{m1})_{3}$. Similarly to (\ref{energyfluid})-(\ref{energyparticle}), we can obtain $(\ref{basicR})_{3}$. Then it is easy to verify
 \begin{equation}\label{411}
\begin{split}
&\widetilde{\rho}\int_{\mathbb{R}} |u(x,t)|^2dx\\
&\quad= \int_{\{\rho\leq \widetilde{\rho}\}}[(\widetilde{\rho}-\rho)|u|^2](x,t)dx+\int_{\{\rho\geq \widetilde{\rho}\}}[(\widetilde{\rho}-\rho)|u|^2](x,t)dx+\int_{\mathbb{R}} (\rho |u|^2)(x,t)dx.
\end{split}
\end{equation}
One deduces by (\ref{rho2}), the Gagliardo-Nirenberg's and Young's inequalities that
\begin{equation}\label{412}
\begin{split}
&\int_{\{\rho\leq \widetilde{\rho}\}}\big{[}(\widetilde{\rho}-\rho)|u|^2\big{]}(x,t)dx\\
&\quad\leq \Big{(}\int_{\{\rho\leq \widetilde{\rho}\}}|(\widetilde{\rho}-\rho)(x,t)|^2dx\Big{)}^{\frac{1}{2}}\|u(t)\|_{L^{4}}^2\\
&\quad\leq C\Big{(}\int_{\mathbb{R}} \Pi_{\gamma}(\rho|\widetilde{\rho})(x,t)dx\Big{)}^{\frac{1}{2}}\|u(t)\|_{L^2}^{\frac{3}{2}}\|u_{x}(t)\|_{L^2}^{\frac{1}{2}}\\
&\quad\leq \frac{\widetilde{\rho}}{2}\int_{\mathbb{R}}|u(x,t)|^2dx+C\Big{(}\int_{\mathbb{R}} \Pi_{\gamma}(\rho|\widetilde{\rho})(x,t)dx\Big{)}^{2}\int_{\mathbb{R}}|u_{x}(x,t)|^2dx.
\end{split}
\end{equation}
For the second term on the right-hand side of (\ref{411}), it holds
\begin{equation}\label{413}
\begin{split}
&\int_{\{\rho\geq \widetilde{\rho}\}}[(\widetilde{\rho}-\rho)|u|^2](x,t)dx\leq \int_{\{\rho\geq \widetilde{\rho}\}}(\widetilde{\rho}|u|^2)(x,t)dx\leq \int_{\mathbb{R}} (\rho|u|^2)(x,t)dx.
\end{split}
\end{equation}
Substituting (\ref{412})-(\ref{413}) into (\ref{411}), we obtain
$$
\|u(t)\|_{L^2}\leq C\big{(}\|\Pi_{\gamma}(\rho|\widetilde{\rho})(t)\|_{L^1}\|u_{x}(t)\|_{L^2}+\|(\sqrt{\rho}u)(t)\|_{L^2}\big{)},
$$
which together with $(\ref{basicR})_{3}$ and the fact
\begin{equation}\nonumber
\begin{split}
&\|u(t)\|_{L^{p}}\leq C\big{(}\|u(t)\|_{L^2}+\|u_{x}(t)\|_{L^2}\big{)},\quad p\in[2,\infty],
\end{split}
\end{equation}
 gives rise to $(\ref{basicR})_{4}$. The proof of Lemma \ref{lemma28} is completed.

\label{lemma29}
Let $T>0$, and $(\rho,u,f)$ be any regular solution to the IVP $(\ref{m1})$-$(\ref{kappa})$ for $t\in(0,T]$. Then, under the assumptions of Theorem \ref{theorem12}, it holds
\begin{equation}\label{upper1}
\left\{
\begin{split}
&\quad 0<\rho_{T}^{-1}\leq \rho(x,t)\leq \rho_{T},\quad (x,t)\in\mathbb{R}\times [0,T],\\
&\sup_{t\in[0,T]}\|(\rho-\overline{\rho})(t)\|_{L^2}\leq C_{T},
\end{split}
\right.
\end{equation}
where $\rho_{T}>0$ and $C_{T}>0$ are two constants dependent of time $T>0$.

For any $x_{0}\in \mathbb{R}$, we claim that it holds
\begin{equation}
\begin{split}
\rho(x,t)\leq \rho_{T},\quad (x,t)\in  (x_{0},x_{0}+1)\times[0,T],\label{claimrho}
\end{split}
\end{equation}
where $\rho_{T}>0$ is a constant independent of the choice of $x_{0}$, so the upper bound in $(\ref{upper1})_{1}$ for any $(x,t)\in \mathbb{R}\times [0,T]$ can be obtained immediately. Indeed, integrating the equation $(\ref{m1})_{3}$ over $(-\infty, x]\times\mathbb{R}$ for any $x\in \mathbb{R}$, we have
\begin{equation}\nonumber
\begin{split}
(\int_{-\infty}^{x}n(y,t)dy)_{t}+nw=0,
\end{split}
\end{equation}
which together with $(\ref{m1})_{1}$ leads to
\begin{equation}\label{m111}
\begin{split}
&(\rho\int_{-\infty}^{x}n(y,t)dy)_{t}+(\rho u\int_{-\infty}^{x}n(y,t)dy)_{x}\\
&\quad=\rho(\int_{-\infty}^{x}n(y,t)dy)_{t}+\rho u (\int_{-\infty}^{x}n(y,t)dy)_{x}\\
&\quad=-\rho nw+\rho u n.
\end{split}
\end{equation}
Substituting (\ref{m111}) into momentum equation $(\ref{m1})_{2}$,  we get
\begin{equation}
\begin{split}
&\big{(}\rho( u+\int_{-\infty}^{x}n(y,t)dy)\big{)}_{t}+\big{(}\rho u( u+\int_{-\infty}^{x}n(y,t)dy)\big{)}_{x}+(\rho^{\gamma})_{x}=(\mu(\rho)u_{x})_{x}.\label{wholem}
\end{split}
\end{equation}
 Similarly to (\ref{j})-(\ref{newm4}), introduce the operator $\mathcal{I}_{x_{0}}: L^{1}(x_{0},x_{0}+1)\rightarrow W^{1,1}(x_{0},x_{0}+1)$ as
\begin{equation}\nonumber
\begin{split}
\mathcal{I}_{x_{0}}: \mathcal{I}_{x_{0}}(g)(x)=\int^{x}_{x_{0}}g(y)dy-\int_{x_{0}}^{x_{0}+1}\int_{x_{0}}^{y}g(z)dzdy,\quad\forall g\in L^1(x_{0},x_{0}+1),
\end{split}
\end{equation}
which satisfies for $g\in L^1(x_{0},x_{0}+1)$ that
\begin{align}
\sup_{x\in (x_{0},x_{0}+1)}\mathcal{I}_{x_{0}}(g)(x)\leq \|g\|_{L^1(x_{0},x_{0}+1)},\quad (\mathcal{I}_{x_{0}}(g)(x))_{x}=g(x),\label{Jx0}
\end{align}
and for $g\in W^{1,1}(x_{0},x_{0}+1)$ that
\begin{align}
\mathcal{I}_{x_{0}}(g_{x})(x)=g(x)-\int_{x_{0}}^{x_{0}+1}g(y)dy.\label{Jx01}
\end{align}
Applying $\mathcal{I}_{x_{0}}$ to the equation (\ref{wholem}), one can show by (\ref{Jx0})-(\ref{Jx01}) that
\begin{equation}\label{pppp}
\begin{split}
&\frac{d}{ds}\theta(\rho)(\mathcal{X}^{x,t}(s),s)+\rho^{\gamma}(\mathcal{X}^{x,t}(s),s)\\
&=-\frac{d}{ds}\mathcal{I}_{x_{0}}\big{(}\rho u+\rho\int_{-\infty}^{x}n(y,t)dy\big{)}(\mathcal{X}^{x,t}(s),s)+H(s)-\int_{x_{0}}^{x_{0}+1}(\mu(\rho)u_{y})(y,s)dx,
\end{split}
\end{equation}
where $\theta(\rho)$ and $\mathcal{X}^{x,t}(s)$ for any $(x,t)\in (x_{0},x_{0}+1)\times[0,T]$ are defined by (\ref{214}) and (\ref{overlinex}) respectively, and $H(s)$ is given by
$$
H(s)=:\int_{x_{0}}^{x_{0}+1}\Big{(}(\rho |u|^2)(y,s)+\rho(y,s)\int_{-\infty}^{y}n(z,s)dz+\rho^{\gamma}(y,s)\Big{)}dy.
$$
For $(x,t)\in (x_{0},x_{0}+1)\times[0,T]$ and $s\in[0,t]$, by virtue of (\ref{overlinex}) and $(\ref{basicR})_{4}$, we have
\begin{align}
&|\mathcal{X}^{x,t}(s)-x|\leq \int_{s}^{t}\|u(\tau)\|_{L^{\infty}}d\tau\leq C_{15}(T+T^{\frac{1}{2}}),\nonumber
\end{align}
which leads to
 \begin{align}
 &|\mathcal{X}^{x,t}(s)-x_{0}|\leq |\mathcal{X}^{x,t}(s)-x|+|x-x_{0}|\leq C_{15}(T+T^{\frac{1}{2}})+1.\label{Xx}
 \end{align}
In addition, it is easy to verify
  \begin{align}
\rho^{\gamma}+\rho\leq C_{16}\big{(}\Pi_{\gamma}(\rho|\widetilde{\rho})+1\big{)},\label{factx}
 \end{align}
 where $C_{16}>0$ is a constant depending only on $\gamma$ and $\widetilde{\rho}$. With the help of (\ref{basicR}), (\ref{Jx0}) and (\ref{Xx})-(\ref{factx}), we derive for any $s\in [0,t]$ that
  \begin{align}
 &\big{|}\mathcal{I}_{x_{0}}\big{(}\rho u+\rho \int_{-\infty}^{x}n(y,t)dy\big{)}(\mathcal{X}^{x,t}(s),s)\big{|}\nonumber\\
 &\quad\leq \Big{(}\int_{x_{0}}^{\mathcal{X}^{x,t}(s)}\rho(y,s)dy\Big{)}^{\frac{1}{2}}\Big{(}\int_{\mathbb{R}}(\rho |u|^2)(y,s)dy\Big{)}^{\frac{1}{2}}+\int_{x_{0}}^{\mathcal{X}^{x,t}(s)}\rho(y,s)dy\int_{\mathbb{R}} n(y,s)dy\nonumber\\
 &\quad\leq (2C_{16}E_{0})^{\frac{1}{2}}\Big{(}\int_{\mathbb{R}}\Pi(\rho|\widetilde{\rho})(y,s)dy+|\mathcal{X}^{x,t}(s)-X_{0}|\Big{)}^{\frac{1}{2}}\nonumber\\
 &\quad\quad+C_{16}\|f_{0}\|_{\mathcal{L}^1}\Big{(} \int_{\mathbb{R}}\Pi(\rho|\widetilde{\rho})(y,s)dy+|\mathcal{X}^{x,t}(s)-X_{0}| \Big{)}\nonumber\\
 &\quad\leq C_{17}(1+T),\label{Jx011}
\end{align}
and
  \begin{equation}\label{H}
 \begin{split}
 &|H(s)|\leq \int_{\mathbb{R}} (\rho |u|^2)(y,s)dy+C_{16}\big{(}\|n(s)\|_{L^1}+1\big{)}\Big{(}\int_{\mathbb{R}} \Pi_{\gamma}(\rho|\widetilde{\rho})(y,s)ds+1\Big{)}\leq C_{18},
\end{split}
\end{equation}
where $C_{17}>0$ and $C_{18}>0$ are two constants independent of time $T>0$. By (\ref{mutheta}), one has
\begin{align}
 &\Big{|}\int_{x_{0}}^{x_{0}+1}(\mu(\rho)u_{y})(y,t)dy\Big{|}\nonumber\\
&\quad\leq 1+ \frac{1}{4}\Big{(}{\footnotesize{\int_{\{y\in (x_{0},x_{0}+1)|\rho\leq 1\}}+\int_{\{y\in (x_{0},x_{0}+1)|\rho\geq 1\}}}}\Big{)}\mu(\rho)(y,s)dy\int_{\mathbb{R}}(\mu(\rho)|u_{y}|^2)(y,t)dy\nonumber\\
&\quad\leq 1+\int_{\mathbb{R}}(\mu(\rho)|u_{y}|^2)(y,t)dy+\frac{\beta}{4}{\footnotesize{\sup_{x\in\{y\in (x_{0},x_{0}+1)|\rho\geq 1\}}\theta(\rho)(x,t)\int_{\mathbb{R}}(\mu(\rho)|u_{y}|^2)(y,t)dy}}.\label{ux1}
\end{align}

Then, integrating the equality (\ref{pppp}) over $[0,t]$, we obtain by (\ref{basicR}) and (\ref{Jx011})-(\ref{ux1}) for any $(x,t)\in(x_{0},x_{0}+1)\times[0,T]$ that
\begin{equation}\nonumber
\begin{split}
&\theta(\rho)(x,t)\leq \theta(\rho_{0})(\mathcal{X}^{x,t}(0))+\big{|} \mathcal{I}_{x_{0}}\big{(}\rho u+\rho\int_{-\infty}^{x}n(y,t)dy\big{)}(\mathcal{X}^{x,t}(s),s)|^{s=t}_{s=0}\big{|}\\
&\quad\quad\quad\quad\quad+\int_{0}^{t}|H(s)|ds+\Big{|}\int_{0}^{t}\int_{x_{0}}^{x_{0}+1}(\mu(\rho)u_{y})(y,s)dyds\Big{|}\\
&\quad\quad\quad\quad\leq \sup_{x\in \mathbb{R}}\theta(\rho_{0})(x)+2C_{17}(1+T)+C_{18}T+T+\widetilde{E}_{0}\\
&\quad\quad\quad\quad\quad+\frac{\beta}{4}\int_{0}^{T}\sup_{x\in\{y\in (x_{0},x_{0}+1)|\rho\geq 1\}}\theta(\rho)(x,s)\int_{\mathbb{R}}(\mu(\rho)|u_{y}|^2)(y,s)dyds,
\end{split}
\end{equation}
which together with $(\ref{basicR})_{3}$ and the Gr${\rm{\ddot{o}}}$nwall's inequality yields (\ref{claimrho}). By (\ref{rho2}), $(\ref{basicR})_{3}$ and (\ref{claimrho}), we have
$$
\sup_{t\in[0,T]}\int_{\mathbb{R}} |\rho-\widetilde{\rho}|^2(x,t)dx\leq C_{T}\sup_{t\in[0,T]}\int_{\mathbb{R}} \Pi_{\gamma}(\rho|\widetilde{\rho})(x,t)dx\leq C_{T}.
$$














Similarly, integrating (\ref{pppp}) over $[0,t]$, one deduce by (\ref{basicR}), (\ref{claimrho}) and (\ref{Jx011})-(\ref{ux1}) for any $(x,t)\in (x_{0},x_{0}+1)\times[0,T]$ that
\begin{equation}
\begin{split}
&\theta(\rho)(x,t)\geq  \inf_{x\in\mathbb{R}}\theta(\rho_{0})(x)-T\rho_{T}^{\gamma}-\big{|} \big{(}\mathcal{I}_{x_{0}}\big{(}\rho u+\rho\int_{-\infty}^{x}n(y,t)dy\big{)}\big{)}(\mathcal{X}^{x,t}(s),s)|^{s=t}_{s=0} \big{|}\\
&\quad\quad\quad\quad\quad-\int_{0}^{T}|H(s)|ds-(\mu(\rho_{T})T)^{\frac{1}{2}}\|\sqrt{\mu(\rho)}u_{x}\|_{L^2(0,T;L^2)} \\
&\quad\quad\quad\quad\geq \inf_{x\in \mathbb{R}}\theta(\rho_{0})(x)-T\rho_{T}^{\gamma}-2C_{17}(1+T)-C_{18}T-(\mu(\rho_{T})T\widetilde{E}_{0})^{\frac{1}{2}}.\label{lowppp}
\end{split}
\end{equation}
  The combination of (\ref{logrho}) and (\ref{lowppp}) shows the lower bound of $\rho$. The proof of Lemma \ref{lemma29} is completed.

\label{lemma210}
Let $T>0$, and $(\rho,u,f)$ be any regular solution to the IVP $(\ref{m1})$-$(\ref{kappa})$ for $t\in(0,T]$. Then, under the assumptions of Theorem \ref{theorem12}, it holds
\begin{equation}\label{H1R}
\left\{
\begin{split}
&\sup_{t\in[0,T]}\|f(t)\|_{\mathcal{L}^{\infty}}\leq e^{\rho_{T}T}\|f_{0}\|_{\mathcal{L}^{\infty}},\\
&~{\rm{Supp}}_{v}f(x,\cdot,t)\subset \{v\in\mathbb{R}~\big{|}~|v|\leq \widetilde{R}_{T}\},\\
&\sup_{t\in[0,T]}\big{(}\|n(t)\|_{L^{\infty}\cap L^2}+\|\rho_{x}(t)\|_{L^2\cap L^{\infty}}+\|u_{x}(t)\|_{L^2}\big{)}+\|(u_{xx},u_{t})\|_{L^2(0,T;L^2)}\leq C_{T},
\end{split}
\right .
\end{equation}
where the constant $\rho_{T}>0$ is given by $(\ref{upper1})_{1}$, and $\widetilde{R}_{T}>0$ and $C_{T}>0$ are two constants.

In accordance to (\ref{fformula}) and  $(\ref{upper1})_{1}$, $(\ref{H1R})_{1}$ holds. Let $\Sigma(x,t)$ be given by $(\ref{Sigmadef})$ for $(x,t)\in\mathbb{R}\times[0,T]$. Similarly to the proof of Lemma \ref{lemma23}, one deduces by $(\ref{a2})_{2}$, (\ref{fformula}), $(\ref{basicR})_{4}$ and $ (\ref{upper1})_{1}$ that
\begin{equation}\nonumber
\begin{split}
&\sup_{v\in\Sigma(x,t)}|v|\leq \widetilde{R}_{0}+\rho_{T}\int_{0}^{t}\|u(s)\|_{L^{\infty}}ds\\
&\quad\quad\quad\quad~\leq \widetilde{R}_{T}=:\widetilde{R}_{0}+C_{15}\rho_{T}(T+T^{\frac{1}{2}}),
\end{split}
\end{equation}
which implies $(\ref{H1R})_{2}$. By (\ref{nw}) and $(\ref{H1R})_{1}$-$(\ref{H1R})_{2}$, we have
\begin{equation}\label{H1R21}
\left\{
\begin{split}
&\sup_{t\in[0,T]}\|n(t)\|_{L^{\infty}}\leq 2\widetilde{R}_{T} \|f(t)\|_{\mathcal{L}^{\infty}}\leq 2\widetilde{R}_{T}e^{\rho_{T}T}\|f_{0}\|_{\mathcal{L}^{\infty}},\\
&\sup_{t\in[0,T]}\|nw(t)\|_{L^{\infty}}\leq 2\widetilde{R}^2_{T} \|f(t)\|_{\mathcal{L}^{\infty}}\leq 2\widetilde{R}_{T}^2e^{\rho_{T}T}\|f_{0}\|_{\mathcal{L}^{\infty}}.
\end{split}
\right.
\end{equation}
In addition, it follows from (\ref{basicR}), (\ref{H1R21}) and the Young's inequality for any $p\in (1,\infty)$ that
\begin{equation}\label{H1R2}
\begin{split}
&\sup_{t\in[0,T]}\|n(t)\|_{L^{p}}\leq  \sup_{t\in[0,T]}\big{(}\|n(t)\|_{L^{1}}+\|n(t)\|_{L^{\infty}}\big{)}\\
&\quad\quad\quad\quad\quad~~~~\leq\|f_{0}\|_{\mathcal{L}^1}+2\widetilde{R}_{T}e^{\rho_{T}T}\|f_{0}\|_{\mathcal{L}^{\infty}},
\end{split}
\end{equation}
and similarly,
\begin{equation}\label{H1R211}
\begin{split}
&\sup_{t\in[0,T]}\|nw(t)\|_{L^{p}}\leq \sup_{t\in[0,T]}\big{(}\|f(t)\|_{\mathcal{L}^{1}}^{\frac{1}{2}}\||v|^2f(t)\|_{\mathcal{L}^1}+\|nw(t)\|_{L^{\infty}}\big{)}\\
&\quad\quad\quad\quad\quad\quad\quad\leq \|f_{0}\|_{\mathcal{L}^1}^{\frac{1}{2}}(2\widetilde{E}_{0})^{\frac{1}{2}}+2\widetilde{R}_{T}e^{\rho_{T}T}\|f_{0}\|_{\mathcal{L}^{\infty}}.
\end{split}
\end{equation}

Then, we turn to show $(\ref{H1R})_{3}$. Define the following effective velocity of Bresch-Desjardins type \cite{bresch1,bresch2,haspot1}:
\begin{align}
&W=:u+\rho^{-2}\mu(\rho)\rho_{x}.\label{WBD}
 \end{align}
 Making use of (\ref{bdx}) and (\ref{WBD}), we can re-write the equation $(\ref{m1})_{2}$ as
\begin{equation}\label{M}
\begin{split}
&\rho (W_{t}+ uW_{x})+\gamma\rho^{\gamma+1}\mu(\rho)^{-1}W=\gamma\rho^{\gamma+1}\mu(\rho)^{-1}u+\rho(nw-nu).
\end{split}
\end{equation}
Multiplying (\ref{M}) by $p|W|^{p-2}W$ for any $p\in[2,\infty)$, and integrating the resulted equation by parts over $\mathbb{R}$, we derive by $(\ref{upper1})_{1}$ and (\ref{H1R2})-(\ref{H1R211}) that
\begin{align}
&\frac{d}{dt}\|(\rho^{\frac{1}{p}} W)(t)\|_{L^{p}}^{p}+p\gamma\int_{\mathbb{R}}\big{(}\rho^{\gamma+1}\mu(\rho)^{-1}|W|^{p}\big{)}(x,t)dx\nonumber\\
&=p\int_{\mathbb{R}} \big{[}\big{(}\gamma\rho^{\gamma+1}\mu(\rho)^{-1}u+\rho(nw-nu)\big{)}|W|^{p-2}W\big{]}(x,t)dx\nonumber\\
&\leq p\rho_{T}^{\frac{1}{p}}\big{(}\gamma\rho_{T}^{\gamma}\|u(t)\|_{L^{p}}+\|nw(t)\|_{L^{p}}+\|n(t)\|_{L^{p}}\|u(t)\|_{L^{\infty}}\big{)}\|(\rho^{\frac{1}{p}} W)(t)\|_{L^{p}}^{p-1}\nonumber\\
&\leq pC_{T}(1+\|u(t)\|_{L^{\infty}\cap L^{p}})\|(\rho^{\frac{1}{p}} W)(t)\|_{L^{p}}^{p-1},\label{www}
\end{align}
where $C_{T}>0$ is a constant independent of $p\in[2,\infty)$. Dividing (\ref{www}) by $(\|(\rho^{\frac{1}{p}}W)(t)\|_{L^{p}}^{p}+\varepsilon^{p})^{\frac{p-1}{p}}$, integrating the resulted inequality over $[0,t]$, and then taking the limit $\varepsilon\rightarrow0$, we have
\begin{equation}\label{Mlp}
\begin{split}
&\sup_{t\in[0,T]}\|(\rho^{\frac{1}{p}}W)(t)\|_{L^{p}}\\
&\quad\leq\|\rho_{0}^{\frac{1}{p}}(u_{0}+\rho_{0}^{-2}\mu(\rho_{0})(\rho_{0})_{x})\|_{L^{p}}+ C_{T}+C_{T}\int_{0}^{T}\|u(t)\|_{L^{\infty}\cap L^{p}}dt.
\end{split}
\end{equation}
Due to $(\ref{basicR})_{4}$, $(\ref{upper1})_{1}$, (\ref{Mlp}) and the fact
\begin{equation}\nonumber
\begin{split}
&\|\rho_{0}^{\frac{1}{p}}(u_{0}+\rho_{0}^{-2}\mu(\rho_{0})(\rho_{0})_{x})\|_{L^{p}}\\
&\quad\leq \|\rho_{0}\|_{L^{\infty}}^{\frac{1}{p}}\big{(}\|u_{0}\|_{L^2}^{\frac{2}{p}}\|u_{0}\|_{L^{\infty}}^{1-\frac{2}{p}}+\|\rho_{0}^{-2}\mu(\rho_{0})(\rho_{0})_{x}\|_{L^2}^{\frac{2}{p}}\|\rho_{0}^{-2}\mu(\rho_{0})(\rho_{0})_{x}\|_{L^{\infty}}^{1-\frac{2}{p}}\big{)}\\
&\quad\leq \big{(}\|\rho_{0}\|_{L^{\infty}}+1\big{)}^{\frac{1}{2}}\big{(}\|u_{0}\|_{L^2}+\|u_{0}\|_{L^{\infty}}+\|\rho_{0}^{-2}\mu(\rho_{0})(\rho_{0})_{x}\|_{L^2}+\|\rho_{0}^{-2}\mu(\rho_{0})(\rho_{0})_{x}\|_{L^{\infty}}\big{)},
\end{split}
\end{equation}
it follows
\begin{equation}\label{Mlp1}
\begin{split}
&\sup_{t\in[0,T]}\|W(t)\|_{L^{p}}\leq \widetilde{C}_{T},
\end{split}
\end{equation}
where $\widetilde{C}_{T}>0$ is a sufficiently large constant independent of $p\in[2,\infty)$. One gets after taking the limit $p\rightarrow\infty$ in (\ref{Mlp1}) that
\begin{equation}\label{Mlinfty}
\begin{split}
&\sup_{t\in[0,T]}\|W(t)\|_{L^{\infty}}\leq \widetilde{C}_{T}.
\end{split}
\end{equation}
Choosing $p=2$ in (\ref{Mlp1}), we have by $(\ref{upper1})_{1}$ and (\ref{WBD}) that
\begin{equation}\nonumber
\begin{split}
&\sup_{t\in[0,T]}\|\rho_{x}(t)\|_{L^{2}}\leq \rho_{T}^{2}\sup_{t\in[0,T]}\|(W-u)(t)\|_{L^{2}}\\
&\quad\quad\quad\quad\quad\quad~~\leq \rho_{T}^{2}\sup_{t\in[0,T]}\big{(}\|W(t)\|_{L^2}+\|u(t)\|_{L^2}\big{)}\leq C_{T}.
\end{split}
\end{equation}
Similarly to (\ref{uh1})-(\ref{utl2}), one can obtain
 \begin{equation}\nonumber
 \begin{split}
 \sup_{t\in[0,T]}\|u_{x}(t)\|_{L^2}+\|(u_{xx},u_{t})\|_{L^2(0,T;L^2)}\leq C_{T},
 \end{split}
 \end{equation}
 which together with $(\ref{upper1})_{1}$, (\ref{WBD}) and (\ref{Mlinfty}) leads to
  \begin{equation}\nonumber
 \begin{split}
 &\sup_{t\in[0,T]}\|\rho_{x}(t)\|_{L^{\infty}}\leq \rho_{T}^2 \sup_{t\in[0,T]}\|(W-u)(t)\|_{L^{\infty}}\\
 &\quad\quad\quad\quad\quad\quad\quad\leq \rho_{T}^2 \sup_{t\in[0,T]}\big{(}\|W(t)\|_{L^{\infty}}+\|u(t)\|_{L^{\infty}}\big{)}\leq C_{T}.
 \end{split}
 \end{equation}
 The proof of Lemma \ref{lemma210} is completed.

\label{lemma211}
Let $T>0$, and $(\rho,u,f)$ be any regular solution to the IVP $(\ref{m1})$-$(\ref{kappa})$ for $t\in(0,T]$. Then, under the assumptions of Theorem \ref{theorem12}, it holds
\begin{equation}\label{H2R}
\begin{split}
&\sup_{t\in[0,T]}\Big{(}\|(\rho_{xx},u_{xx})(t)\|_{L^2}+\|\rho_{t}(t)\|_{H^1}+t^{\frac{1}{2}}\|(u_{xxx},u_{tx})(t)\|_{L^2}\\
&\quad\quad\quad\quad+\|f(t)\|_{\mathcal{C}^{1}\cap \mathcal{H}^{1}}+\|f_{t}(t)\|_{\mathcal{C}^{0}\cap\mathcal{L}^{2}}\Big{)}+\|(u_{xxx},u_{xt})\|_{L^2(0,T;L^2)}\leq C_{T},
\end{split}
\end{equation}
where $C_{T}>0$ is a constant.

We establish the $\mathcal{H}^1$-estimate of $f$ so as to obtain the $H^1$-estimate of the term $ nw-un$ on the right-hand side of the equation (\ref{unorho}). Since the rest of the proof follows similarly to $(\ref{fxfv})$-(\ref{fc1t}) in Lemma \ref{lemma24}, we omit the details here. Multiplying $(\ref{fxfv})_{1}$ by $f_{x}$, and integrating the resulted equation by parts over $\mathbb{R}\times\mathbb{R}$, one deduces by $(\ref{upper1})_{1}$ and (\ref{H1R}) that
\begin{equation}\label{fxddt}
\begin{split}
&\frac{1}{2}\frac{d}{dt}\|f_{x}(t)\|_{\mathcal{L}^2}^2\leq \frac{1}{2}\rho_{T}\|f_{x}(t)\|_{\mathcal{L}^2}^2+\|\rho_{x}(t)\|_{L^{\infty}}\int_{\mathbb{R}\times\mathbb{R}} (f|f_{x}|)(x,v,t)dvdx\\
&\quad\quad\quad\quad\quad\quad\quad+\big{(}\|\rho_{x}(t)\|_{L^{\infty}}\widetilde{R}_{T}+\|(\rho u)_{x}(t)\|_{L^{\infty}}\big{)}\int_{\mathbb{R}\times\mathbb{R}}(|f_{v}||f_{x}|)(x,v,t)dvdx\\
&\quad\quad\quad\quad\quad\quad\leq C_{T}\big{(}1+\|u(t)\|_{H^2}\big{)}\|(f_{x},f_{v})(t)\|_{\mathcal{L}^2}^2+C_{T}.
\end{split}
\end{equation}
Similarly, one has
\begin{equation}\nonumber
\begin{split}
&\frac{1}{2}\frac{d}{dt}\|f_{v}(t)\|_{\mathcal{L}^2}^2\leq C_{T}\|(f_{x},f_{v})(t)\|_{\mathcal{L}^2}^2+C_{T},
\end{split}
\end{equation}
which together with (\ref{H1R}), (\ref{fxddt}) and the Gr${\rm{\ddot{o}}}$nwall's inequality leads to
\begin{equation}\label{fxfvH1}
\begin{split}
\sup_{t\in[0,T]}\|(f_{x},f_{v})(t)\|_{\mathcal{L}^2}\leq C_{T}e^{C_{T}\|u\|_{L^1(0,T;H^2)}}\big{(}\|[(f_{0})_{x},(f_{0})_{v}]\|_{\mathcal{L}^2}+1\big{)}\leq C_{T}.
\end{split}
\end{equation}
By $(\ref{m33})$, $(\ref{upper1})_{1}$, (\ref{H1R}) and (\ref{fxfvH1}), it also holds
\begin{equation}\label{ft}
\begin{split}
\sup_{t\in[0,T]}\|f_{t}(t)\|_{\mathcal{L}^2}=\sup_{t\in[0,T]}\|\big{[}v f_{x}+\rho(u-v)f_{v}-\rho f\big{]}(t)\|_{\mathcal{L}^2}\leq C_{T}.
\end{split}
\end{equation}
Thus, we obtain by $(\ref{nw})$, (\ref{H1R}) and (\ref{fxfvH1})-(\ref{ft}) that
\begin{equation}\label{nwx2}
\left\{
\begin{split}
&\sup_{t\in[0,T]}\|(n_{x},n_{t})(t)\|_{L^{2}}\leq 2\widetilde{R}_{T} \sup_{t\in[0,T]}\|(f_{x},f_{t})(t)\|_{\mathcal{L}^{2}}\leq C_{T},\\
&\sup_{t\in[0,T]}\|[(nw)_{x},(nw)_{t}](t)\|_{L^{2}}\leq 2\widetilde{R}_{T}^2 \sup_{t\in[0,T]}\|(f_{x},f_{t})(t)\|_{\mathcal{L}^{2}}\leq C_{T}.
\end{split}
\right.
\end{equation}

Let $T>0$ be any given time. With the help of Lemmas \ref{lemma28}-\ref{lemma211} and Lemma \ref{lemma42} below, we can obtain a sequence of strong solutions $(\rho^{\varepsilon},u^{\varepsilon},f^{\varepsilon})$ for $\varepsilon\in(0,1)$ on $\mathbb{R}\times\mathbb{R}\times [0,T]$. 

Then, one can show under the assumptions (\ref{a2}) of Theorem \ref{theorem12} that $(\rho^{\varepsilon},u^{\varepsilon},f^{\varepsilon})$ satisfies the estimates established in Lemmas \ref{lemma28}-\ref{lemma210} uniformly with respect to $\varepsilon\in(0,1)$. Since the locally compact embedding $H^2(\mathbb{R}) \hookrightarrow\hookrightarrow L^2_{loc}(\mathbb{R})$  holds, by virtue of the Aubin-Lions's lemma and cantor's diagonal argument, up to a subsequence (still denoted by $(\rho^{\varepsilon},u^{\varepsilon},f^{\varepsilon})$), we have the strong convergence
\begin{equation}\nonumber
\begin{split}
&(\rho^{\varepsilon},u^{\varepsilon})\rightarrow (\rho,u)\quad\text{strongly in}~C([0,T];C^{0}(K))\times C([0,T];C^{0}(K)),\quad\text{as}\quad \varepsilon\rightarrow 0,
\end{split}
\end{equation}
for any compact subset $K$ of $\mathbb{R}$. Similarly to the proof of global existence to the IVP $(\ref{m1})$-$(\ref{kappa})$ in spatial periodic domain (i.e., Theorem \ref{theorem11}), one can prove that the approximate sequence $(\rho^{\varepsilon},u^{\varepsilon},f^{\varepsilon})$ converges to the corresponding weak solution $(\rho,u,f)$ in the sense of distributions.

Define the bi-characteristic curves $(X_{i}(t),V_{i}(t))$, $i=1,2$, for any $(x,v,t)\in \mathbb{T}\times\mathbb{R}\times[0,T]$ as
\begin{equation}\label{XiVi}
\left\{
\begin{split}
&\frac{d}{dt}X_{i}(t)=V_{i}(t),\\
&~~X_{i}(0)=x,\\
&\frac{d}{dt}V_{i}(t)=\rho_{i}(X_{i}(t),t)\big{(}u_{i}(X_{i}(t),t)-V_{i}(t)\big{)},\\
&~~V_{i}(0)=v.
\end{split}
\right .
\end{equation}
Since it holds for $i=1,2$ that
\begin{equation}\label{f1f2}
\begin{split}
&(f_{i})_{t}+\operatorname{div}_{x,v} \bigg{(}f_{i} {\scriptsize{\left(           
  \begin{matrix}   
    v  \\
    \rho_{i}(u_{i}-v)  \\ 
  \end{matrix}
\right)}}\bigg{)}
=(f_{i})_{t}+v(f_{i})_{x}+\rho_{i}(u_{i}-v)(f_{i})_{v}-\rho_{i}f_{i}=0,
\end{split}
\end{equation}
we can express $f_{i}$ along $(X_{i}(t),V_{i}(t))$ for any $(x,v,t)\in \mathbb{T}\times\mathbb{R}\times[0,T]$ as
\begin{equation}
\begin{split}
f_{i}\big{(}X_{i}(t),V_{i}(t),t\big{)}=e^{\int_{0}^{t}\rho_{i}(X_{i}(s),s)ds}f_{0}(x,v),\quad i=1,2.\label{fformula12}
\end{split}
\end{equation}
Due to (\ref{f1f2}), Proposition 1.2 in \cite{majda1} and the fact
\begin{equation}\nonumber
\begin{split}
\operatorname{div}_{x,v}
 {\scriptsize{\left(
  \begin{matrix}
    v  \\
    \rho_{i}\big{(}u_{i}-v\big{)}  \\
  \end{matrix}
\right)}}=-\rho_{i},
\end{split}
\end{equation}
 we have
\begin{equation}\nonumber
\partial_{t}J_{i}=-J_{i} \rho_{i} (X_{i}(t),t),\quad J_{i}=:
\bigg{|}{\rm{det}}
 {\scriptsize{\left(
  \begin{matrix}
    \partial_{x}X (t) & \partial_{x}V (t)  \\
    \partial_{v}X (t) &\partial_{v}V (t)  \\
  \end{matrix}
\right)}}
\bigg{|},
\end{equation}
which implies
\begin{equation}\label{det}
\begin{split}
J_{i}=e^{-\int_{0}^{t}\rho_{i}(s,X_{i}(s))ds},\quad i=1,2.
\end{split}
\end{equation}
We combine (\ref{fformula12})-(\ref{det}) together to show the following property about the coordinates transform $(x,v)\mapsto (X_{i}(t),V_{i}(t))$:
\begin{equation}
\begin{split}
&\int_{\mathbb{T}\times\mathbb{R}} \phi(X_{i}(t),V_{i}(t))f_{0}(x,v)dvdx\\
&\quad=\int_{\mathbb{T}\times\mathbb{R}} \phi(X_{i}(t),V_{i}(t))f_{i}(X_{i}(t),V_{i}(t),t)dX_{i}(t)dV_{i}(t)\\
&\quad=\int_{\mathbb{T}\times\mathbb{R}} \phi(x,v) f_{i}(x,v,t)dvdx,\quad\forall \phi\in C^{0}(\mathbb{T}\times\mathbb{R}),\quad i=1,2.\label{pullback}
\end{split}
\end{equation}




Inspired by \cite{loeper1,han1}, we estimate the quantity
 \begin{equation}\label{Xi}
 \begin{split}
Q(t)=:\frac{1}{2}\int_{\Omega\times\mathbb{R}} f_{0}(x,v)\big{(}|X_{1}(t)-X_{2}(t)|^2+|V_{1}(t)-V_{2}(t)|^2\big{)}dvdx.
 \end{split}
 \end{equation}
 For $\Omega=\mathbb{T}$, making use of (\ref{XiVi}), we can obtain after a complicated computation that
\begin{equation}\label{unf}
\begin{split}
&\frac{d}{dt}Q(t)+\int_{\mathbb{T}\times\mathbb{R}} \rho_{1}(X_{1}(t),t)f_{0}(x,v)|V_{1}(t)-V_{2}(t)|^2dvdx\\
&=\int_{\mathbb{T}\times\mathbb{R}} f_{0}(x,v)\big{(}X_{1}(t)-X_{2}(t)\big{)}\big{(}V_{1}(t)-V_{2}(t)\big{)}dvdx\\
&\quad+\int_{\mathbb{T}\times\mathbb{R}} f_{0}(x,v)\big{(}V_{1}(t)-V_{2}(t)\big{)}(\rho_{1}u_{1}-\rho_{2}u_{2})(X_{1}(t),t)dvdx\\
&\quad+\int_{\mathbb{T}\times\mathbb{R}} f_{0}(x,v)\big{(}V_{1}(t)-V_{2}(t)\big{)}\big{[}(\rho_{2}u_{2})(X_{1}(t),t)-(\rho_{2}u_{2})(X_{2}(t),t)\big{]}dvdx\\
&\quad+\int_{\mathbb{T}\times\mathbb{R}} f_{0}(x,v)\big{(}V_{1}(t)-V_{2}(t)\big{)}\big{(}\rho_{2}(X_{2}(t),t)-\rho_{2}(X_{1}(t),t)\big{)}V_{2}(t)dvdx\\
&\quad+\int_{\mathbb{T}\times\mathbb{R}} f_{0}(x,v)\big{(}V_{1}(t)-V_{2}(t)\big{)}(\rho_{2}-\rho_{1})(X_{1}(t),t)V_{2}(t)dvdx\\
&\quad=:\sum_{i=1}^{5}I_{i}^{1}.
\end{split}
\end{equation}
The right-hand side terms of (\ref{unf}) can be estimated as follows. First, one has
\begin{equation}\nonumber
\begin{split}
I_{1}^{1}\leq Q(t).
\end{split}
\end{equation}
By (\ref{pullback}), it holds
\begin{equation}\nonumber
\begin{split}
&I_{2}^{1}=\int_{\mathbb{T}\times\mathbb{R}} f_{0}(x,v)\big{(}V_{1}(t)-V_{2}(t)\big{)}\big{[}\rho_{1}(u_{1}-u_{2})+(\rho_{1}-\rho_{2})u_{2}\big{]}(X_{1}(t),t)dvdx\\
&\quad \leq \frac{1}{2}\int_{\mathbb{T}\times\mathbb{R}} f_{0}(x,v)|V_{1}(t)-V_{2}(t)|^2dvdx\\
&\quad\quad+\frac{1}{2}\int_{\mathbb{T}\times\mathbb{R}} \big{(}\rho_{1}^2|u_{1}-u_{2}|^2+|\rho_{1}-\rho_{2}|^2|u_{2}|^2\big{)}(X_{1}(t),t)f_{0}(x,v)dvdx\\
&\quad\leq  Q(t)+\frac{1}{2}\int_{\mathbb{T}} \big{(}\rho_{1}^2|u_{1}-u_{2}|^2+|\rho_{1}-\rho_{2}|^2|u_{2}|^2\big{)}(x,t)\big{(}\int_{\mathbb{R}} f_{1}(x,v,t)dv\big{)}dx\\
&\quad\leq Q(t)+\frac{1}{2}\|\int_{\mathbb{R}} f_{1}(\cdot,v,t)dv\|_{L^{\infty}} {\footnotesize{ \Big{(}\|\rho_{1}(t)\|_{L^{\infty}}\|\big{(}\sqrt{\rho_{1}}(u_{1}-u_{2})\big{)}(t)\|_{L^2}^2}}\\
&\quad\quad {\footnotesize{ +\|u_{2}(t)\|_{L^{\infty}}^2\|(\rho_{1}-\rho_{2})(t)\|_{L^2}^2\Big{)}}}.
\end{split}
\end{equation}
For the term $I_{3}^1$, we have
\begin{equation}\nonumber
\begin{split}
&I_{3}^1\leq \|(\rho_{2}u_{2})_{x}(t)\|_{L^{\infty}}\int_{\mathbb{T}\times\mathbb{R}} f_{0}(x,v)|V_{1}(t)-V_{2}(t)||X_{1}(t)-X_{2}(t)|dvdx\\
&\quad\leq  {\footnotesize{ \Big{(}\|\rho_{2}(t)\|_{L^{\infty}}\|(u_{2})_{x}(t)\|_{L^{\infty}}+\|(\rho_{2})_{x}(t)\|_{L^{\infty}}\|u_{2}(t)\|_{L^{\infty}}\Big{)}}}Q(t).
\end{split}
\end{equation}
We estimate the term $I_{4}^1$ as
\begin{equation}\nonumber
\begin{split}
&I_{4}^{1}\leq \|(\rho_{2})_{x}(t)\|_{L^{\infty}}\int_{\mathbb{T}\times\mathbb{R}} f_{0}(x,v)|V_{1}(t)-V_{2}(t)||X_{1}(t)-X_{2}(t)||V_{2}(t)|dvdx\\
&\quad\leq R_{1}\|(\rho_{2})_{x}(t)\|_{L^{\infty}}Q(t),
\end{split}
\end{equation}
where in the last inequality we have used the following fact for $i=1,2$:
\begin{equation}\label{V1V2v}
\begin{split}
&f_{0}(x,v)|V_{i}(t)|\leq  {\footnotesize{ \Big{(}e^{-\rho_{-}t}|v|+\rho_{+}\int_{0}^{t}e^{-\rho_{-}s}|u_{i}(x,t)|ds\Big{)}}}f_{0}(x,v)\leq R_{1}f_{0}(x,v),
\end{split}
\end{equation}
derived from $(\ref{a1})_{2}$, (\ref{r11}), (\ref{uinfty1}), (\ref{Rt}) and (\ref{XiVi}). By (\ref{pullback}) and (\ref{V1V2v}), it also holds
\begin{equation}\nonumber
\begin{split}
&I_{5}^1\leq \frac{1}{2}\int_{\mathbb{T}\times\mathbb{R}} f_{0}(x,v)|V_{1}(t)-V_{2}(t)|^2|V_{2}(t)|dvdx\\
&\quad\quad+\frac{1}{2}\int_{\mathbb{T}\times\mathbb{R}}|(\rho_{1}-\rho_{2})(X_{1}(t),t)|^2|V_{2}(t)|f_{0}(x,v)dvdx\\
&\quad\leq R_{1} Q(t)+\frac{R_{1}}{2}\|\int_{\mathbb{R}} f_{1}(\cdot,v,t)dv\|_{L^{\infty}}\|(\rho_{1}-\rho_{2})(t)\|_{L^2}^2.
\end{split}
\end{equation}
Substituting the above estimates of $I^{1}_{i}$, $1,...,5$, into (\ref{unf}), and employing (\ref{r1})-(\ref{r11}), we have
\begin{equation}
\begin{split}
&\frac{d}{dt}Q(t)\leq C_{T}\big{(}1+\|(u_{2})_{x}(t)\|_{L^{\infty}}\big{)}Q(t)\\
&\quad\quad\quad\quad+C_{T} {\footnotesize{ \Big{(}\|\big{(}\sqrt{\rho_{1}}(u_{1}-u_{2})\big{)}(t)\|_{L^2}^2+\|(\rho_{1}-\rho_{2})(t)\|_{L^2}^2\Big{)}}}.\label{widetildef1}
\end{split}
\end{equation}


Next, we turn to estimate $(\rho_{1}-\rho_{2},u_{1}-u_{2})$. With loss of generalization, we prove the case $\beta=0$. It is easy to verify
\begin{align}
&(\rho_{1}-\rho_{2})_{t}+(\rho_{1})_{x}(u_{1}-u_{2})+\rho_{1}(u_{1}-u_{2})_{x}+(u_{2}(\rho_{1}-\rho_{2}))_{x}=0,\label{widetilderho}\\
&\rho_{1}(u_{1}-u_{2})_{t}+\rho_{1}u_{1}(u_{1}-u_{2})_{x}-2(u_{1}-u_{2})_{xx}+\rho_{1}(u_{1}-u_{2})\int_{\mathbb{R}} f_{1}dv\nonumber\\
&\quad=-(\rho_{1}^{\gamma}-\rho_{2}^{\gamma})_{x}-\rho_{1}(u_{1}-u_{2})(u_{2})_{x}-(\rho_{1}-\rho_{2})((u_{2})_{t}+u_{2}(u_{2})_{x})\nonumber\\
&\quad\quad+\int_{\mathbb{R}}(\rho_{1}-\rho_{2})(v-u_{2})f_{1}dv+\int_{\mathbb{R}}\rho_{2}(v-u_{2})(f_{1}-f_{2})dv.\label{widetildeu}
\end{align}
Multiplying (\ref{widetilderho}) by $(\rho_{1}-\rho_{2})$, integrating the resulted equation by parts over $\mathbb{T}$, and using (\ref{r1})-(\ref{r11}), we have
\begin{equation}
\begin{split}
&\frac{1}{2}\frac{d}{dt}\|(\rho_{1}-\rho_{2})(t)\|_{L^2}^2\\
&~~\leq C_{T}\big{(}1+\|(u_{2})_{x}(t)\|_{L^{\infty}}\big{)}  {\footnotesize{ \Big{(}\|(\rho_{1}-\rho_{2})(t)\|_{L^2}^2+\|\big{(}\sqrt{\rho_{1}}(u_{1}-u_{2})\big{)}(t)\|_{L^{2}}\Big{)}}}\\
&~~\quad+\frac{1}{100}\|(u_{1}-u_{2})_{x}(t)\|_{L^2}^2.\label{widetilderho1}
\end{split}
\end{equation}
In addition, we multiply (\ref{widetildeu}) by $(u_{1}-u_{2})$ and integrate the resulted equation by parts over $\mathbb{T}$ to obtain
\begin{equation}\label{widetildeu1}
\begin{split}
&\frac{1}{2}\frac{d}{dt}\|\big{(}\sqrt{\rho_{1}}(u_{1}-u_{2})\big{)}(t)\|_{L^2}^2+2\|(u_{1}-u_{2})_{x}(t)\|_{L^2}^2+\|\big{(}\sqrt{\rho_{1}f_{1}}(u_{1}-u_{2})\big{)}(t)\|_{L^2}^2\\
&~~\leq\|(u_{2})_{x}(t)\|_{L^{\infty}}\|\sqrt{\rho_{1}}(u_{1}-u_{2})(t)\|_{L^2}^2+\|(\rho_{1}^{\gamma}-\rho_{2}^{\gamma})(t)\|_{L^2}\|(u_{1}-u_{2})_{x}(t)\|_{L^2}\\
&\quad~~+\|((u_{2})_{t}+u_{2}(u_{2})_{x})(t)\|_{L^2}\|(\rho_{1}-\rho_{2})(t)\|_{L^2}\|(u_{1}-u_{2})(t)\|_{L^{\infty}}\\
&\quad~~+\|(\rho_{1}-\rho_{2})(t)\|_{L^2}\|(u_{1}-u_{2})(t)\|_{L^{\infty}}\|\int_{\mathbb{R}} (v-u_{2}(\cdot,t))f_{1}(\cdot,v,t)dv\|_{L^2}\\
&\quad~~+ {\footnotesize{ \int_{\mathbb{T}\times\mathbb{R}}\rho_{2}(x,t)\big{(}v-u_{2}(x,t)\big{)}(u_{1}-u_{2})(x,t)(f_{1}-f_{2})(x,v,t)dvdx}}\\
&~~=:\|(u_{2})_{x}(t)\|_{L^{\infty}}\|\sqrt{\rho_{1}}(u_{1}-u_{2})(t)\|_{L^2}^2+\sum_{i=1}^{4}I_{i}^{2}.
\end{split}
\end{equation}
One can show
\begin{equation}\nonumber
\begin{split}
&I_{1}^{2}\leq C\|(\rho_{1}-\rho_{2})(t)\|_{L^2}^2+\frac{1}{100}\|(u_{1}-u_{2})_{x}(t)\|_{L^2}^2.
\end{split}
\end{equation}
For $I_{2}^2$, we have
\begin{equation}\nonumber
\begin{split}
&I_{2}^{2}\leq C\big{(}1+\|(u_{2})_{t}(t)\|_{L^2}^2\big{)} {\footnotesize{  \Big{(}\|\big{(}\sqrt{\rho_{1}}(u_{1}-u_{2})\big{)}(t)\|_{L^2}^2+\|(\rho_{1}-\rho_{2})(t)\|_{L^2}^2\Big{)}}}\\
&\quad\quad+\frac{1}{100}\|(u_{1}-u_{2})_{x}(t)\|_{L^2}^2,
\end{split}
\end{equation}
where we have used (\ref{r1})-(\ref{r11}), the Young's inequality and the fact
\begin{equation}\label{widetildeuinfty}
\begin{split}
\|(u_{1}-u_{2})(t)\|_{L^{\infty}}\leq C\rho_{-}^{-\frac{1}{4}}\|\big{(}\sqrt{\rho_{1}}(u_{1}-u_{2})\big{)}(t)\|_{L^2}^{\frac{1}{2}}\|(u_{1}-u_{2})_{x}(t)\|_{L^2}^{\frac{1}{2}}.
\end{split}
\end{equation}
 Similarly, by (\ref{r1}) and (\ref{widetildeuinfty}), one has
\begin{equation}\nonumber
\begin{split}
&I_{3}^{2}\leq C {\footnotesize{ \Big{(}\|\big{(}\sqrt{\rho_{1}}(u_{1}-u_{2})\big{)}(t)\|_{L^2}^2+\|(\rho_{1}-\rho_{2})(t)\|_{L^2}^2\Big{)}}}+\frac{1}{100}\|(u_{1}-u_{2})_{x}(t)\|_{L^2}^2.
\end{split}
\end{equation}
With the help of (\ref{pullback}), we obtain
 \begin{equation}\label{change1}
 \begin{split}
 &\int_{\mathbb{T}\times\mathbb{R}}\rho_{2}(x,t)\big{(} v-u_{2}(x,t)\big{)}(u_{1}-u_{2})(x,t)f_{1}(x,v,t)dvdx\\
 &\quad=\int_{\mathbb{T}\times\mathbb{R}}\rho_{2}(X_{1}(t),t)\big{(}V_{1}(t)-u_{2}(X_{1}(t),t)\big{)}(u_{1}-u_{2})(X_{1}(t),t)f_{0}(x,v)dvdx,
 \end{split}
 \end{equation}
and similarly,
  \begin{equation}\label{change2}
 \begin{split}
 &\int_{\mathbb{T}\times\mathbb{R}}\rho_{2}(x,t)\big{(} v-u_{2}(x,t)\big{)}(u_{1}-u_{2})(x,t)f_{2}(x,v,t)dvdx\\
 &\quad=\int_{\mathbb{T}\times\mathbb{R}}\rho_{2}(X_{2}(t),t)\big{(}V_{2}(t)-u_{2}(X_{2}(t),t)\big{)}(u_{1}-u_{2})(X_{2}(t),t)f_{0}(x,v)dvdx.
 \end{split}
 \end{equation}
By (\ref{change1})-(\ref{change2}), the last term $I_{4}^2$ on the right-hand side of (\ref{widetildeu1}) can be estimated as follows:
  \begin{equation}\label{widetildeu2}
 \begin{split}
&I_{4}^2=\int_{\mathbb{T}\times\mathbb{R}} \big{[}(\rho_{2}u_{2})(X_{2}(t),t)-(\rho_{2}u_{2})(X_{1}(t),t)\big{]}(u_{1}-u_{2})(X_{1}(t),t)f_{0}(x,v)dvdx\\
&\quad\quad+\int_{\mathbb{T}\times\mathbb{R}} \big{(}\rho_{2}(X_{1}(t),t)-\rho_{2}(X_{2}(t),t)\big{)}V_{2}(t)(u_{1}-u_{2})(X_{1}(t),t)f_{0}(x,v)dvdx\\
&\quad\quad+\int_{\mathbb{T}\times\mathbb{R}} \rho_{2}(X_{1}(t),t)\big{(}V_{1}(t)-V_{2}(t)\big{)}(u_{1}-u_{2})(X_{1}(t),t)f_{0}(x,v)dvdx\\
&\quad\quad+\int_{\mathbb{T}\times\mathbb{R}}\rho_{2}(X_{2}(t),t)\big{(}V_{2}(t)-u_{2}(X_{2}(t),t)\big{)}\big{[}(u_{1}-u_{2})(X_{1}(t),t)\\
&\quad\quad\quad-(u_{1}-u_{2})(X_{2}(t),t)\big{]}f_{0}(x,v)dvdx\\
&\quad=:\sum_{i=1}^{4}I^3_{i}.
 \end{split}
 \end{equation}
To estimate $I_{1}^3$, we obtain by (\ref{r1})-(\ref{r11}) and (\ref{widetildeuinfty}) that
$$
\begin{aligned}
&I_{1}^3\leq  \|(\rho_{2}u_{2})_{x}(t)\|_{L^{\infty}}\|(u_{1}-u_{2})(t)\|_{L^{\infty}}\int_{\mathbb{T}\times\mathbb{R}} |X_{1}(t)-X_{2}(t)|f_{0}(x,v)dvdx\\
&\quad\leq  C_{T}\big{(}1+\|(u_{2})_{x}(t)\|_{L^{\infty}}^2\big{)} {\footnotesize{ \Big{(}Q(t)+\|\big{(}\sqrt{\rho_{1}}(u_{1}-u_{2})\big{)}(t)\|_{L^2}^2\Big{)}}}+\frac{1}{100}\|(u_{1}-u_{2})_{x}(t)\|_{L^2}^2.
\end{aligned}
$$
Similarly, one can derive by (\ref{r1})-(\ref{r11}), (\ref{V1V2v}) and (\ref{widetildeuinfty}) that
$$
\begin{aligned}
&I_{2}^3\leq  \|(\rho_{2})_{x}(t)\|_{L^{\infty}}\|(u_{1}-u_{2})(t)\|_{L^{\infty}}\int_{\mathbb{T}\times\mathbb{R}} |X_{1}(t)-X_{2}(t)||V_{2}(t)|f_{0}(x,v)dvdx\\
&\quad\leq Q(t)+C_{T}\|\big{(}\sqrt{\rho_{1}}(u_{1}-u_{2})\big{)}(t)\|_{L^2}^2+\frac{1}{100}\|(u_{1}-u_{2})_{x}(t)\|_{L^2}^2,
\end{aligned}
$$
and
$$
\begin{aligned}
&I_{3}^3\leq \|\rho_{2}(t)\|_{L^{\infty}}\|(u_{1}-u_{2})(t)\|_{L^{\infty}}\int_{\mathbb{T}\times\mathbb{R}}|V_{1}(t)-V_{2}(t)| f_{0}(x,v)dvdx\\
 &\quad\leq Q(t)+C_{T}\|\big{(}\sqrt{\rho_{1}}(u_{1}-u_{2})\big{)}(t)\|_{L^2}^2+\frac{1}{100}\|(u_{1}-u_{2})_{x}(t)\|_{L^2}^2.
\end{aligned}
$$
It follows from (\ref{r1})-(\ref{r11}), (\ref{V1V2v}) and (\ref{2102}) in Lemma \ref{lemma32} below that
\begin{equation}
\begin{split}
&I_{4}^{3}\leq C \int_{\mathbb{T}\times\mathbb{R}}  {\footnotesize{ \sup_{r\in(0,1)}\frac{1}{2r}\Big{(}\int^{X_{1}(t)+r}_{X_{1}(t)-r}+\int^{X_{2}(t)+r}_{X_{2}(t)-r}\Big{)}|(u_{1}-u_{2})_{z}(z,t)|}}dz \\
&\quad\quad \quad {\footnotesize{ \times\big{(}|V_{2}(t)+|u_{2}(X_{2}(t),t)|\big{)} |X_{1}(t)-X_{2}(t)|}}f_{0}(x,v)dvdx\\
&\quad\leq C_{T}Q^{\frac{1}{2}}(t)\Big{(}\int_{\mathbb{T}\times\mathbb{R}}  {\footnotesize{ \Big{(}\sup_{r\in(0,1)}\frac{1}{2r}\int^{X_{1}(t)+r}_{X_{1}(t)-r}|(u_{1}-u_{2})_{z}(z,t)|dz\Big{)}^2}}f_{0}(x,v)dvdx\Big{)}^{\frac{1}{2}}\\
&\quad\quad+ C_{T}Q^{\frac{1}{2}}(t)\Big{(}\int_{\mathbb{T}\times\mathbb{R}}  {\footnotesize{ \Big{(}\sup_{r\in(0,1)}\frac{1}{2r}\int^{X_{2}(t)+r}_{X_{2}(t)-r}|(u_{1}-u_{2})_{z}(z,t)|dz\Big{)}^2}}f_{0}(x,v)dvdx\Big{)}^{\frac{1}{2}}.\label{asdd}
\end{split}
\end{equation}
Making use of $(\ref{r1})$, (\ref{pullback}) and (\ref{2101}) in Lemma \ref{lemma31} below, we can obtain
\begin{equation}\label{asdd1}
\begin{split}
&\int_{\mathbb{T}\times\mathbb{R}} {\footnotesize{ \Big{(}\sup_{r\in(0,1)}\frac{1}{2r}\int^{X_{1}(t)+r}_{X_{1}(t)-r}|(u_{1}-u_{2})_{z}(z,t)|dz\Big{)}^2}}f_{0}(x,v)dvdx\\
&\quad=\int_{\mathbb{T}\times\mathbb{R}}  {\footnotesize{ \Big{(}\sup_{r\in(0,1)}\frac{1}{2r}\int^{x+r}_{x-r}|(u_{1}-u_{2})_{z}(z,t)|dz\Big{)}^2}} f_{1}(x,v,t)dvdx\\
&\quad\leq C\|\int_{\mathbb{R}} f_{1}(\cdot,v,t)dv\|_{L^{\infty}}\Big{\|} {\footnotesize{ \sup_{r\in(0,1)}\frac{1}{2r}\int^{x+r}_{x-r}|(u_{1}-u_{2})_{z}(z,t)|dz}}\Big{\|}_{L^2}^2\\
&\quad\leq C_{T}\|(u_{1}-u_{2})_{x}(t)\|_{L^2}^2,
\end{split}
\end{equation}
and similarly,
\begin{equation}\label{asdd2}
\begin{split}
&\int_{\mathbb{T}\times\mathbb{R}} {\footnotesize{\Big{(}\sup_{r\in(0,1)}\frac{1}{2r}\int^{X_{2}(t)+r}_{X_{2}(t)-r}|(u_{1}-u_{2})_{z}(z,t)|dz\Big{)}^2}}f_{0}(x,v)dvdx\\
&\quad\leq C_{T}\|(u_{1}-u_{2})_{x}(t)\|_{L^2}^2.
\end{split}
\end{equation}
The combination of (\ref{asdd})-(\ref{asdd2}) leads to
\begin{equation}\nonumber
\begin{split}
&I_{4}^{3}\leq C_{T}Q^{\frac{1}{2}}(t)\|(u_{1}-u_{2})_{x}(t)\|_{L^2}\leq C_{T}Q(t)+\frac{1}{100}\|(u_{1}-u_{2})_{x}(t)\|_{L^2}^2.
\end{split}
\end{equation}
Substituting the estimates of $I_{i}^3$, $i=1,...,4$, into (\ref{widetildeu2}), we obtain
\begin{equation}\nonumber
\begin{split}
&I_{4}^2\leq C_{T}\big{(}1+\|(u_{2})_{x}(t)\|_{L^{\infty}}^2\big{)} {\footnotesize{ \Big{(}Q(t)+\|\big{(}\sqrt{\rho_{1}}(u_{1}-u_{2})\big{)}(t)\|_{L^2}^2\Big{)}}}+\frac{1}{100}\|(u_{1}-u_{2})_{x}(t)\|_{L^2}^2.
\end{split}
\end{equation}
Substituting the estimates of $I_{i}^2$, $i=1,...,4$, into (\ref{widetildeu1}), and adding the resulted inequality, (\ref{widetildef1}) and (\ref{widetilderho1}) together, we have
\begin{equation}\nonumber
\begin{split}
&\frac{d}{dt} {\footnotesize{ \Big{(}Q(t)+\|\big{(}\sqrt{\rho_{1}}(u_{1}-u_{2})\big{)}(t)\|_{L^2}^2+\|(\rho_{1}-\rho_{2})(t)\|_{L^2}^2\Big{)}}}+\|(u_{1}-u_{2})_{x}(t)\|_{L^2}^2\\
&\leq C_{T}\big{(}1+\|(u_{2})_{x}(t)\|_{L^{\infty}}^2+\|(u_{2})_{t}(t)\|_{L^2}^2\big{)} {\footnotesize{ \Big{(}Q(t)+\|\big{(}\sqrt{\rho_{1}}(u_{1}-u_{2})\big{)}(t)\|_{L^2}^2+\|(\rho_{1}-\rho_{2})(t)\|_{L^2}^2\Big{)}}}.
\end{split}
\end{equation}
Thus, one deduces by the Gr$\rm{\ddot{o}}$nwall's inequality, (\ref{r1}), the fact $Q(0)=0$ and Lemma \ref{lemma32} below that
$$
(\rho_{1},u_{1},f_{1})=(\rho_{2},u_{2},f_{2}),\quad\text{a.e. in}~ \mathbb{T} \times\mathbb{R}\times (0,T).
$$
The proof of Proposition \ref{prop31} is completed.

\label{lemma31} Let $\Omega =\mathbb{T} $ or $\mathbb{R}$. For any $g\in L^2(\Omega)$, it holds
\begin{equation}\label{2101}
\begin{split}
\Big{\|} {\footnotesize{ \sup_{r\in(0,1)}\frac{1}{2r}\int^{x+r}_{x-r}|g(z)|dz}}\Big{\|}_{L^2}\leq C\|g\|_{L^2},
\end{split}
\end{equation}
If assume further $g_{x}\in L^2(\Omega),$ then for a.e. $x,y\in \Omega$, we have
\begin{equation}\label{2102}
\begin{split}
|g(x)-g(y)|\leq C|x-y|  \Big{(} {\footnotesize{ \sup_{r\in(0,1)}\frac{1}{2r}\int^{x+r}_{x-r}|g_{z}(z)|dz+\sup_{r\in(0,1)}\frac{1}{2r}\int^{y+r}_{y-r}|g_{z}(z)|dz }}\Big{)}.
\end{split}
\end{equation}

\label{lemma41}
Let $\Omega=\mathbb{T}$. Suppose that the initial data $(\rho_{0},u_{0},f_{0})$ satisfies
\begin{equation}\label{alocal}
\left\{
\begin{split}
&\inf_{x\in\mathbb{T}}\rho_{0}(x)>0,\quad \rho_{0}\in H^2(\mathbb{T} ),\quad u_{0}\in H^2(\mathbb{T} ),\\
&0\leq f_{0}\in C^{1}(\mathbb{T}\times\mathbb{R}),\quad \text{{\rm{Supp}}}_{v}f_{0}(x,\cdot)\subset \{v\in\mathbb{R}~\big{|}~|v|\leq  R_{0}\},\quad x\in\mathbb{T},
\end{split}
\right.
\end{equation}
where $R_{0}>0$ is a constant. Then there is a time $T_{*}>0$ such that the IVP $(\ref{m1})$-$(\ref{kappa})$ admits a unique strong solution satisfying
\begin{equation}\label{rlocal}
\left\{
\begin{split}
&\inf_{(x,t)\in \mathbb{T}\times[0,T_{*}]}\rho(x,t)>0,\quad \rho\in C([0,T_{*}];H^2(\mathbb{T} )),\\
&~~u\in C([0,T_{*}];H^2(\mathbb{T} ))\cap L^2(0,T_{*};H^3(\mathbb{T})),\\
&~~0\leq f\in C([0,T_{*}];C^{1}(\mathbb{T} \times\mathbb{R} )),\\
&~~\text{{\rm{Supp}}}_{v}f(x,\cdot,t)\subset \{v\in\mathbb{R}~\big{|}~|v|\leq  R_{0}+1\},\quad (x,t)\in\mathbb{T}\times[0,T_{*}].
\end{split}
\right .
\end{equation}

\emph{Step 1: Construction of approximate sequence.} The iteration scheme for the approximate solutions $(\rho^{n+1},u^{n+1},f^{n+1})$, $n\geq 0$, is defined by solving the following equations:
 \begin{equation}\label{m1n}
\left\{
 \begin{split}
 &(\rho^{n+1})_{t}+(u^{n}\rho^{n+1})_{x}=0,\\
 & (u^{n+1})_{t}-\frac{1}{\rho^{n}}(\mu(\rho^{n})(u^{n+1})_{x})_{x}=-u^{n}(u^{n})_{x}-\gamma(\rho^{n})^{\gamma-2}(\rho^{n})_{x}-\int_{\mathbb{R}}(u^{n}-v)f^{n}dv,\\
& (f^{n+1})_{t}+v(f^{n+1})_{x}+(\rho^{n}(u^{n}-v)f^{n+1})_{v}=0,\quad (x,v)\in \mathbb{T}\times\mathbb{R},~t>0,
\end{split}
\right .
\end{equation}
with the initial data
\begin{align}
&(\rho^{n+1}(x,0),u^{n+1}(x,0),f^{n+1}(x,v,0))=(\rho_{0}(x),u_{0}(x),f_{0}(x,v)), \quad (x,v)\in\mathbb{T}\times\mathbb{R}.\label{dn}
\end{align}
Define the work space
\begin{equation}\nonumber
\begin{split}
&\mathcal{W}(T)=:\Big{\{}(\rho,u,f)~\big{|}~(\rho,u) \in C([0,T];H^2(\mathbb{T} )),\quad  0\leq f\in C([0,T];C^{1}(\mathbb{T} \times\mathbb{R} )),\\
 &\quad \quad\quad \quad \quad \quad\quad \quad\quad~\frac{1}{2}\rho_{0-}\leq \rho(x,t)\leq 2\rho_{0+},\quad (x,t)\in\mathbb{T}\times[0,T],\\
 &\quad \quad\quad \quad \quad \quad\quad \quad\quad~\text{{\rm{Supp}}}_{v}f^{n}(x,\cdot,t)\subset \{v\in\mathbb{R}~\big{|}~|v|\leq  R_{0}+1\},\quad (x,t)\in\mathbb{T}\times[0,T],\\
 &\quad \quad\quad \quad \quad \quad\quad \quad \quad\sup_{t\in[0,T]}\big{(}\|(\rho,u)(t)\|_{H^2}^2+\|f(t)\|_{\mathcal{C}^1}\big{)}+\frac{1}{2\rho_{0+}}\|u_{x}\|_{L^2(0,T;H^2)}^2\leq 2E_{0}+1.\Big{\}},
\end{split}
\end{equation}
where $\rho_{0+}>0, \rho_{0-}>0$ and $E_{0}>0$ are constants given by
 \begin{equation}\nonumber
 \begin{split}
 &\rho_{0-}=:\inf_{x\in\mathbb{T}}\rho_{0}(x),\quad \rho_{0+}=:\sup_{x\in\mathbb{T}}\rho_{0}(x),\quad E_{0}=:\|(\rho_{0},u_{0})\|_{H^2}^2+\|f_{0}\|_{\mathcal{C}^1}.
 \end{split}
 \end{equation}
Set $(\rho^{0},u^{0},f^{0})=: (\rho_{0},u_{0},f_{0})$. Suppose
\begin{align}
(\rho^{n},u^{n},f^{n})\in\mathcal{W}(T_{0}),\label{n}
\end{align}
for some time $T_{0}>0$. By the standard theory of linear O.D.E. systems \cite{hsi1}, for given $u^{n}\in C([0,T_{0}];H^2(\mathbb{T}))\hookrightarrow C([0,T_{0}];C^{1}(\mathbb{T}))$, there is a unique particle path $\mathcal{X}_{n}^{x,t}(s)$ for any $(x,t)\in \mathbb{T}\times[0,T_{0}]$ defined by
 \begin{equation}\nonumber
 \left\{
 \begin{split}
 &\frac{d}{ds}\mathcal{X}_{n}^{x,t}(s)=u^{n}(\mathcal{X}_{n}^{x,t}(s),s),\quad s\in[0,t],\\
 &~\mathcal{X}_{n}^{x,t}(t)=x.
 \end{split}
 \right.
 \end{equation}
Thus, the linear transport equation $(\ref{m1n})_{1}$ can be solved by
 \begin{equation}\label{rhon1}
 \begin{split}
 \rho^{n+1}(x,t)=e^{-\int_{0}^{t} (u^{n})_{x}(\mathcal{X}_{n}^{x,t}(s),s)ds}\rho_{0}(\mathcal{X}_{n}^{x,t}(0)).
 \end{split}
 \end{equation}
Similarly, for given $(\rho^{n},u^{n})\in C([0,T_{0}];H^2(\mathbb{T}))\hookrightarrow C([0,T_{0}];C^{1}(\mathbb{T}))$, we can define uniquely the bi-characteristic curves
\begin{equation}\label{XVn}
\left\{
\begin{split}
&\frac{d}{ds}X_{n}^{x,v,t}(s)=V_{n}^{x,v,t}(s),\quad s\in [0,t],\\
&\quad X_{n}^{x,v,t}(t)=x,\\
&\frac{d}{ds}V_{n}^{x,v,t}(s)=\rho^{n}(X_{n}^{x,v,t}(s),s) \big{(}u^{n}(X_{n}^{x,v,t}(s),s)-V_{n}^{x,v,t}(s)\big{)},\quad s\in [0,t],\\
&\quad V_{n}^{x,v,t}(t)=v,
\end{split}
\right .
\end{equation}
for any $(x,v,t)\in \mathbb{T}\times\mathbb{R}\times[0,T_{0}]$, so that the solution $f^{n+1}$ for the linear transport equation $(\ref{m1n})_{3}$ can be represented by
\begin{align}
f^{n+1}(x,v,t)=e^{\int_{0}^{t}\rho^{n}(X_{n}^{x,v,t}(s),s)ds}f_{0}(X_{n}^{x,v,t}(0),V_{n}^{x,v,t}(0))\geq 0.\label{fn1}
\end{align}
Finally, by the standard theorem of linear parabolic equations \cite{jllions1,valli1}, $(\ref{m1n})_{2}$ admits a unique solution $u^{n+1}\in C([0,T_{0}];H^2(\mathbb{T}))\cap L^2(0,T_{0};H^3(\mathbb{T}))$. 


 \emph{Step~2: Uniform estimates.} We claim that there is a time $T_{0}>0$ such that for each $n\geq 0$, if $(\rho^{n},u^{n},f^{n})$ satisfies (\ref{n}), then it is also true for $(\rho^{n+1},u^{n+1},f^{n+1})$. Indeed, by (\ref{n})-(\ref{rhon1}), one has
  \begin{equation}\label{upperrhon}
 \begin{split}
& 0<e^{-NE_{0}^{\frac{1}{2}}T_{0}}\rho_{0-}\leq \rho^{n+1}(x,t)\leq e^{NE_{0}^{\frac{1}{2}}T_{0}}\rho_{0+},\quad (x,t)\in \mathbb{T}\times[0,T_{0}],
 \end{split}
 \end{equation}
where $N>0$ denotes a a suitably large constant depending only on $\rho_{0+},\rho_{0-}$ and $R_{0}$. In addition, the equation $(\ref{m1n})_{1}$ implies
    \begin{equation}\label{nablarhon}
 \begin{split}
 &\partial_{t}\sum_{i=0}^{2}\partial_{x}^{i}\rho^{n+1}+u^{n}\sum_{i=0}^{2}\partial_{x}^{i+1}\rho^{n+1}\\
 &\quad=-\sum_{i=0}^{2}\partial_{x}^{i}(\rho^{n+1} (u^{n})_{x})-(u^{n})_{x}(\rho^{n+1})_{x}-2(u^{n})_{x}(\rho^{n+1})_{xx}-(u^{n})_{xx}(\rho^{n+1})_{x}.
  \end{split}
 \end{equation}
 We multiply (\ref{nablarhon}) by $\sum_{i=0}^{2}\partial_{x}^{i}\rho^{n+1}$ and integrate the resulted equation by parts over $\mathbb{T}$ to get
  \begin{equation}\label{nablarhon1}
 \begin{split}
 &\frac{1}{2}\frac{d}{dt}\|\rho^{n+1}(t)\|_{H^2}^2\\
 &~~\leq \frac{1}{2}\|(u^{n})_{x}(t)\|_{L^{\infty}}\|\rho^{n+1}(t)\|_{H^2}^2+N\|(\rho^{n+1} (u^{n})_{x})(t)\|_{H^2}\|\rho^{n+1}(t)\|_{H^2}\\
 &~~\leq N\|(u^{n})_{x}(t)\|_{H^2}\|\rho^{n+1}(t)\|_{H^2}^2.
   \end{split}
 \end{equation}
Thus, it follows from (\ref{n}), (\ref{nablarhon1}) and the Gr${\rm{\ddot{o}}}$nwall's inequality that
   \begin{equation}\label{rhonH2}
 \begin{split}
 &\sup_{t\in[0,T_{0}]}\|\rho^{n+1}(t)\|_{H^2}^2\leq e^{N\|(u^{n})_{x}\|_{L^1(0,T;H^2)}}\|\rho_{0}\|_{H^2}^2\leq e^{N E_{0}^{\frac{1}{2}}T_{0}^{\frac{1}{2}}}\|\rho_{0}\|_{H^2}^2.
  \end{split}
 \end{equation}

We are ready to estimate $u^{n+1}$. By $(\ref{m1n})_{2}$ and (\ref{n}), it is easy to obtain
       \begin{equation}\label{uL2}
 \begin{split}
 &\frac{1}{2}\frac{d}{dt}\|u^{n+1}(t)\|_{H^1}^2+\frac{1}{2\rho_{0+}}\|(u^{n+1})_{x}(t)\|_{H^1}^2\\
 &~~\leq N\big{(}E_{0}^{\frac{1}{2}}\|(u^{n+1})_{x}(t)\|_{L^2}\|u^{n+1}(t)\|_{L^2}+(E_{0}^{\frac{1}{2}}+1)E_{0}^{\frac{1}{2}}\|u^{n+1}(t)\|_{L^2}\big{)}.
     \end{split}
 \end{equation}
Then we differentiate $(\ref{m1})_{2}$ with respect to $x$ to have
        \begin{equation}\label{unxxx}
 \begin{split}
 & (u^{n+1})_{xt}-\frac{\mu(\rho^{n})}{\rho^{n}}(u^{n+1})_{xxx}=(\frac{\mu'(\rho^{n})}{\rho^{n}}(\rho^{n})_{x}(u^{n+1})_{x})_{x}+(\frac{\mu(\rho^{n})}{\rho^{n}})_{x}(u^{n+1})_{xx}\\
 &\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad+\big{(}-u^{n}(u^{n})_{x}-\gamma(\rho^{n})^{\gamma-2}(\rho^{n})_{x}-\int_{\mathbb{R}}(u^{n}-v)f^{n}dv\big{)}_{x}.
     \end{split}
 \end{equation}
Multiplying $(\ref{unxxx})$ by $-(u^{n+1})_{xxx}$, integrating the resulted equation by parts over $\mathbb{T}$, and making use of (\ref{n}), we derive
  \begin{equation}\nonumber
 \begin{split}
  &\frac{1}{2}\frac{d}{dt}\|(u^{n+1})_{xx}(t)\|_{L^2}^2+\frac{1}{2\rho_{0+}}\|(u^{n+1})_{xxx}(t)\|_{L^2}^2\\
  &~~\leq N\Big{(}\|(\rho^{n})_{x}(t)\|_{L^{\infty}}\|(u^{n+1})_{xx}(t)\|_{L^2}+\|(\rho^{n})_{xx}(t)\|_{L^{2}}\|(u^{n+1})_{x}(t)\|_{L^{\infty}}+\|u^{n}(t)\|_{H^1}\|(u^{n})_{x}(t)\|_{H^1}\\
    &\quad~~+\|(\rho^{n})_{x}(t)\|_{H^1}+\big{(}1+\|u^{n}(t)\|_{H^1}\big{)}\|\int_{\mathbb{R}}(1+|v|)f^{n}(x,\cdot,t)dv\|_{H^1}\Big{)}\|(u^{n+1})_{xxx}(t)\|_{L^2}\\
 &~~\leq \frac{1}{4\rho_{0+}}\|(u^{n+1})_{xxx}(t)\|_{L^2}^2+ N E_{0}\|u^{n+1}(t)\|_{H^2}^2+N(1+E_{0})E_{0},
     \end{split}
 \end{equation}
which together with (\ref{uL2}) gives rise to
   \begin{equation}\label{un1H2}
 \begin{split}
 &\sup_{t\in[0,T_{0}]}\|u^{n+1}(t)\|_{H^2}^2+\frac{1}{2\rho_{0+}}\|(u^{n+1})_{x}\|_{L^2(0,T_{0};H^2)}^2\\
 &\quad\leq e^{NE_{0}T_{0} }\big{(}\|u_{0}\|_{H^2}^2+N(1+E_{0})E_{0}T_{0}\big{)}.
     \end{split}
 \end{equation}



To estimate $f^{n+1}$, we obtain by (\ref{XVn}) that
 \begin{equation}\label{xv123}
\begin{split}
&v=e^{-\int_{0}^{t}\rho^{n}(X_{n}^{x,v,t}(\tau),\tau)d\tau}V_{n}^{x,v,t}(0)+\int_{0}^{t}e^{-\int_{\tau}^{t}\rho^{n}(X_{n}^{x,v,t}(\omega),\omega)d\omega}\rho^{n} u^{n}(X_{n}^{x,v,t}(\tau),\tau)d\tau.
\end{split}
\end{equation}
It follows from $(\ref{alocal})_{2}$, (\ref{n}), (\ref{fn1}) and (\ref{xv123}) for any $(x,t)\in\mathbb{T}\times [0,T_{0}]$ that
\begin{align}
&\sup_{\{v\in\mathbb{R}~|~f^{n+1}(x,v,t)\neq 0\}}|v|\leq R_{0}+2\rho_{0+}\|u^{n}\|_{L^{\infty}(0,T_{0};L^{\infty})}T_{0}\leq R_{0}+N E_{0}^{\frac{1}{2}}T_{0},
\end{align}
from which we get
   \begin{align}
  &\text{{\rm{Supp}}}_{v}f^{n+1}(x,\cdot,t)\subset \{v\in\mathbb{R}~\big{|}~|v|\leq  R_{0}+N E_{0}T_{0}\},\quad (x,t)\in\mathbb{T}\times[0,T_{0}].\label{fn1compact}
     \end{align}
Similarly to (\ref{fxfv})-(\ref{fw1inftycnsv}), one has by a direct computation that
\begin{equation}\label{fw1inftycnsvppp}
\begin{split}
\sup_{t\in[0,T_{0}]}\|f^{n+1}(t)\|_{\mathcal{C}^{1}}\leq e^{N E_{0}^{\frac{1}{2}}T_{0}}\big{(}\|f_{0}\|_{\mathcal{C}^{1}}+N(1+E_{0}^{\frac{1}{2}})E^{\frac{1}{2}}_{0}T_{0}\big{)}.
\end{split}
\end{equation}
Choose
     \begin{equation}\label{T0}
     \left\{
 \begin{split}
 &M_{0}=: N \max\big{\{} (1+E_{0})E_{0},(1+E_{0}^{\frac{1}{2}})E^{\frac{1}{2}}_{0}\big{\}} ,\\
 &T_{0}=:\min\big{\{}\frac{\log{2}}{NM_{0}},\frac{(\log{2})^2}{N^2M_{0}^2},\frac{1}{2NM_{0}}\big{\}}.
     \end{split}
     \right.
 \end{equation}
Then by the previous estimates (\ref{fn1})-(\ref{upperrhon}), (\ref{rhonH2}), (\ref{un1H2}) and (\ref{fn1compact})-(\ref{fw1inftycnsvppp}), we conclude that  for each $n\geq 0$, the strong solution $(\rho^{n+1},u^{n+1},f^{n+1})$ to the IVP (\ref{m1n})-(\ref{dn}) belongs to $\mathcal{W}(T_{0})$ as long as $(\rho^{n},u^{n},f^{n})$ satisfies (\ref{n}). By repeating the procedure used above, we can obtain an approximate sequence $(\rho^{n},u^{n},f^{n})$ satisfying the uniform estimates in $\mathcal{W}(T_{0})$.




  \emph{Step 3: Compactness and convergence.} Let $M_{0}>0$ and $T_{0}>0$ be given by (\ref{T0}).  We aim to prove the convergence of the approximate sequence $(\rho^{n},u^{n},f^{n})$ to the corresponding strong solution of the original IVP (\ref{m1})-(\ref{kappa}). Since $(\rho^{n},u^{n},f^{n})$ is uniformly bounded in $\mathcal{W}(T_{0})$, one can show after a tedious computation that
 \begin{equation}\nonumber
 \begin{split}
 &\sup_{\tau\in [0,t]}\Big{(}\|(\rho^{n+1}-\rho^{n}, u^{n+1}-u^{n})(\tau)\|_{H^1}^2+\|(f^{n+1}-f^{n})(\tau)\|_{\mathcal{C}^{0}}\Big{)}+\|(u^{n+1}-u^{n})_{x}\|_{L^2(0,t;H^1)}^2\\
 &\quad\leq N_{*} M_{0}t\sup_{\tau\in [0,t]}\Big{(}\|(\rho^{n}-\rho^{n-1}, u^{n}-u^{n-1})(\tau)\|_{H^1}^2+\|(f^{n}-f^{n-1})(\tau)\|_{\mathcal{C}^{0}}\Big{)},\quad t\in[0,T_{0}],
 \end{split}
 \end{equation}
 where $N_{*}>0$ is a constant depending only on $\rho_{0+},\rho_{0-}$ and $R_{0}$. Choosing
$$
 T_{*}=\min\big{\{}\frac{1}{2N_{*}M_{0}},T_{0}\big{\}},
$$
 we have
 \begin{equation}\nonumber
 \begin{split}
&\sum_{n=0}^{\infty} \sup_{\tau\in [0,T_{*}]}\Big{(}\|(\rho^{n+1}-\rho^{n}, u^{n+1}-u^{n})(\tau)\|_{H^1}^2+\|(f^{n+1}-f^{n})(\tau)\|_{\mathcal{C}^{0}}\Big{)}\\
&\quad\leq \sum_{n=0}^{\infty} \frac{1}{2^{n}} \sup_{\tau\in [0,T_{*}]}\Big{(}\|(\rho^{1}-\rho^{0}, u^{1}-u^{0})(\tau)\|_{H^1}^2+\|(f^{1}-f^{0})(\tau)\|_{\mathcal{C}^{0}}\Big{)}<\infty,
 \end{split}
 \end{equation}
 which implies that there is a limit $(\rho,u,f)$ so that as $n\rightarrow\infty$, it holds
 \begin{equation}\label{strongn}
 \left\{
 \begin{split}
 &(\rho^{n},u^{n})\rightarrow(\rho,u)\quad \text{in}\quad L^{\infty}(0,T_{*};H^1(\mathbb{T}))\times L^{\infty}(0,T_{*};H^1(\mathbb{T})),\\
 &f^{n}\rightarrow f\quad \text{in}\quad L^{\infty}(0,T_{*};C^{0}(\mathbb{T}\times\mathbb{R})).
 \end{split}
 \right.
 \end{equation}
 Due to the estimates of $(\rho^{n},u^{n},f^{n})$ uniformly in $n\geq0$, as $n\rightarrow \infty$, it holds up to a subsequence (still denoted by $(\rho^{n},u^{n},f^{n})$) that
 \begin{equation}\label{weakn}
 \left\{
 \begin{split}
 &(\rho^{n},f^{n}) \overset{\ast}{\rightharpoonup} (\rho,f) \quad\text{in}\quad L^{\infty}(0,T_{*};H^2(\mathbb{T}))\times L^{\infty}(0,T_{*};W^{1,\infty}(\mathbb{T}\times\mathbb{R})),\\
 &u^{n} \rightharpoonup u\quad\text{in}\quad L^2(0,T_{*};H^3(\mathbb{T})).
 \end{split}
 \right.
 \end{equation}
Thus, we can pass to the limit $n\rightarrow\infty$ for the equations $(\ref{m1n})$ in the sense of distributions and prove that $(\rho,u,f)$ is indeed a strong solution to the IVP $(\ref{m1})$-$(\ref{dn})$ on $\mathbb{T}\times\mathbb{R}\times[0,T_{*}]$. 

In addition, applying the theory of renormalized solutions in \cite{diperna1}, we have $\rho\in C([0,T_{*}];H^1(\mathbb{T}))$. By $(\ref{m1})_{2}$, (\ref{strongn})-(\ref{weakn}) and the uniform estimate of $(\rho^{n},u^{n},f^{n})$, one can show $u_{t}\in L^2(0,T_{*}; H^1(\mathbb{T}))$, and therefore $u\in C([0,T_{*}];H^2(\mathbb{T}))$ follows from $u\in L^2(0,T_{*};H^3(\mathbb{T}))\cap H^1(0,T_{*};H^1(\mathbb{T}))$. Moreover, with the help of $(\rho,u) \in C([0,T_{*}];H^2(\mathbb{T}))\hookrightarrow C([0,T_{*}];C^{1}(\mathbb{T}))$, it is easy to verify the $C^1$-regularity of the bi-characteristic curves $(X^{x,v,t}(s),V^{x,v,t}(s))$ defined by (\ref{XV}) with respect to  $(x,v)\in\mathbb{T}\times\mathbb{R}$, which together with (\ref{fformula}) implies $f\in C([0,T_{*}];C^{1}(\mathbb{T}\times\mathbb{R}))$. According to Proposition \ref{prop31}, the strong solution $(\rho,u,f)$ is unique. The proof of Lemma \ref{lemma41} is completed.

\label{lemma42}
Let $\Omega=\mathbb{R}$. Suppose that the initial data $(\rho_{0},u_{0},f_{0})$ satisfies
\begin{equation}\nonumber
\left\{
\begin{split}
&\inf_{x\in\mathbb{R}}\rho_{0}(x)>0,\quad \rho_{0}-\widetilde{\rho}\in H^2(\mathbb{R} ),\quad u_{0}\in H^2(\mathbb{R} ),\\
&0\leq f_{0}\in L^1\cap L^{\infty}\cap H^1\cap C^{1}(\mathbb{R} \times\mathbb{R}),\quad \text{{\rm{Supp}}}_{v}f_{0}(x,\cdot)\subset \{v\in\mathbb{R}~\big{|}~|v|\leq  \widetilde{R}_{0}\},\quad x\in\mathbb{R},
\end{split}
\right.
\end{equation}
where $\widetilde{\rho}>0$ and $\widetilde{R}_{0}>0$ are two constants. Then there is a time $T_{**}>0$ such that the IVP $(\ref{m1})$-$(\ref{kappa})$ admits a unique strong solution satisfying
\begin{equation}\nonumber
\left\{
\begin{split}
&\inf_{(x,t)\in \mathbb{R}\times[0,T_{**}]}\rho(x,t)>0,\quad \rho-\widetilde{\rho}\in C([0,T_{**}];H^2(\mathbb{R} )),\\
&~~u\in C([0,T_{**}];H^2(\mathbb{R} ))\cap L^2(0,T_{**};H^3(\mathbb{R})),\\
&~~0\leq f\in C([0,T_{**}];L^1\cap H^1\cap C^{1}(\mathbb{R} \times\mathbb{R} ))\cap L^{\infty}(0,T_{**},L^{\infty}(\mathbb{R} \times\mathbb{R} )),\\
& ~~\text{{\rm{Supp}}}_{v}f(x,\cdot,t)\subset \{v\in\mathbb{R}~\big{|}~|v|\leq  \widetilde{R}_{0}+1\},~(x,t)\in\mathbb{R}\times [0,T_{**}].
\end{split}
\right .
\end{equation}

\label{defn11}{\textit{
 Let $f_{1},f_{2}$ be two Borel probability measures on $X=\mathbb{T}\times\mathbb{R}$. For $p\geq 1$, the Wasserstein distance of order $p$ between $f_{1}$ and $f_{2}$ is defined by the formula
\begin{equation}\nonumber
