\label{lemma51}
Let $(\rho,u,f)$ be the global solution to the IVP $(\ref{m1})$-$(\ref{kappa})$ given by Theorem \ref{theorem11}. Then, under the assumptions of Theorem 1.1, it holds
\begin{equation}\label{entropydissipation}
\begin{split}
\frac{d}{dt}\mathcal{E}(t)+\mathcal{D}(t)=0.
\end{split}
\end{equation}

Multiplying (\ref{m21111}) by $(u-m_{1})$ and integrating the resulted equation by parts over $\mathbb{T}$, we obtain
\begin{equation}\label{um12}
\begin{split}
&\frac{1}{2}\frac{d}{dt}\int_{\mathbb{T}}\big{(}\rho|u-m_{1}|^2\big{)}(x,t)dx+\int_{\mathbb{T}}(\mu(\rho)|u_{x}|^2)(x,t)dx\\
&\quad=-\int_{\mathbb{T}}[(\rho^{\gamma}-\overline{\rho_{0}}^{\gamma})_{x}(u-m_{1})](x,t)dx-\int_{\mathbb{T}}[\rho n(u-w)(u-m_{1})](x,t)dx\\
&\quad\quad+\frac{1}{\overline{\rho_{0}}}\int_{\mathbb{T}} [\rho n (u-w)](x,t)dx\int_{\mathbb{T}}[\rho (u-m_{1})](x,t)dx\\
&\quad=\int_{\mathbb{T}}(\rho^{\gamma}u_{x})(x,t)dx-\int_{\mathbb{T}}[\rho n(u-w)(u-m_{1})](x,t)dx,
\end{split}
\end{equation}
where we have used the fact
$$
\int_{\mathbb{T}}[\rho (u-m_{1})](x,t)dx=0.
$$
We get after a direct computation that
\begin{equation}\label{rho12}
\begin{split}
&\frac{d}{dt}\int_{\mathbb{T}}\Pi_{\gamma}(\rho|\overline{\rho_{0}})(x,t)dx=\frac{d}{dt}\int_{\mathbb{T}}\frac{\rho^{\gamma}(x,t)}{\gamma-1}dx=-\int_{\mathbb{T}}(\rho^{\gamma}u_{x})(x,t)dx.
\end{split}
\end{equation}
Since it holds
\begin{equation}\label{m2t}
\begin{split}
\frac{d}{dt}m_{2}(t)=\frac{1}{\overline{n_{0}}}\frac{d}{dt}\int_{\mathbb{T}\times\mathbb{R}} vf(x,v,t)dvdx=\frac{1}{\overline{n_{0}}}\int_{\mathbb{T}\times\mathbb{R}}[\rho n(u-w)](x,t)dx,
\end{split}
\end{equation}
and
\begin{equation}\label{m20}
\begin{split}
\int_{\mathbb{T}\times\mathbb{R}}(v-m_{2}(t))f(x,v,t)dvdx=0,
\end{split}
\end{equation}
 multiplying the Vlasov equation $(\ref{m1})_{3}$ by $\frac{1}{2}|v-m_{2}|^2$ and integrating the resulted equation by parts over $\mathbb{T}\times\mathbb{R}$, we have
\begin{equation}\label{fm12}
\begin{split}
&\frac{d}{dt}\int_{\mathbb{T}\times\mathbb{R}}\frac{1}{2}|v-m_{2}(t)|^2f(x,v,t)dvdx\\
&\quad=\int_{\mathbb{T}\times\mathbb{R}}\frac{1}{2}|v-m_{2}(t)|^2f_{t}(x,v,t)dvdx+\int_{\mathbb{T}\times\mathbb{R}}(v-m_{2}(t))(m_{2}(t))_{t}f(x,v,t)dvdx\\
&\quad=\int_{\mathbb{T}\times\mathbb{R}}\frac{1}{2}|v-m_{2}(t)|^2\big{[}-vf_{x}-(\rho(u-v)f)_{v}\big{]}(x,v,t)dvdx\\
&\quad\quad+\frac{1}{\overline{n_{0}}}\int_{\mathbb{T}}[\rho n(u-w)](x,t)dx\int_{\mathbb{T}\times\mathbb{R}}(v-m_{2}(t))f(x,v,t)dvdx\\
&\quad=\int_{\mathbb{T}\times\mathbb{R}}\rho(x,t)(u(x,t)-v)(v-m_{2}(t))f(x,v,t)dvdx\\
&\quad=-\int_{\mathbb{T}\times\mathbb{R}}\rho(x,t)|u(x,t)-v|^2f(x,v,t)dvdx+\int_{\mathbb{T}}[\rho n(u-w)(u-m_{2})](x,t)dx.
\end{split}
\end{equation}
By virtue of $(\ref{basiccnsv})_{2}$, (\ref{momentumfluid}) and (\ref{m2t}), one can show
\begin{equation}
\begin{split}
&\frac{d}{dt}\big{(}\frac{\overline{\rho_{0}}~\overline{n_{0}}}{2(\overline{n_{0}}+\overline{\rho_{0}})}|(m_{2}-m_{1})(t)|^2\big{)}=(m_{2}-m_{1})(t)\int_{\mathbb{T}}[\rho n(u-w)](x,t)dx.\label{m1m212}
\end{split}
\end{equation}
Adding (\ref{um12}), (\ref{rho12}), (\ref{fm12}) and (\ref{m1m212}) together, we can obtain (\ref{entropydissipation}).

Let $T>0$, and $(\rho,u,f)$ be one regular solution to the IVP (\ref{m1})-(\ref{kappa}) for $t\in[0,T]$. Then, under the assumptions of Theorem 1.1, it holds
\begin{align}
&|\int_{\mathbb{T}}[\rho(u-m_{1})\mathcal{J}(\rho-\overline{\rho_{0}})](x,t)dx|\leq c_{1}(\|\big{(}\sqrt{\rho}(u-m_{1})\big{)}(t)\|_{L^2}^2+\|\Pi_{\gamma}(\rho|\overline{\rho_{0}})(t)\|_{L^1}),\label{perturb}\\
&\frac{d}{dt}\int_{\mathbb{T}}[\rho(u-m_{1})\mathcal{J}(\rho-\overline{\rho_{0}})](x,t)dx\geq c_{0}\|\Pi_{\gamma}(\rho|\overline{\rho_{0}})(t)\|_{L^1}- c_{1}(\|u_{x}(t)\|_{L^2}^2+\|\big{(}\sqrt{\rho f}(u-v)\big{)}(t)\|_{\mathcal{L}^2}^2),\label{perturb-}
\end{align}
where $c_{i}>0$, $i=1,2$, are two positive constants only depending on $\overline{\rho_{0}}$ and $\rho_{+}$, and the operator $\mathcal{J}$ is defined by (\ref{j}).

One deduce from the Young's inequality, (\ref{basiccnsv}) and (\ref{J}) that
\begin{equation}\label{ppp}
\begin{split}
&|\int_{\mathbb{T}}[\rho (u-m_{1})\mathcal{J}(\rho-\overline{\rho_{0}})](x,t)dx|\leq \frac{1}{2}(\|\big{(}\sqrt{\rho}(u-m_{1})\big{)}(t)\|_{L^2}^2+\|\rho(t)\|_{L^1}\|\mathcal{J}(\rho-\overline{\rho_{0}})(t)\|_{L^{\infty}}^2)\\
&\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad~\leq \frac{1}{2}(\|\big{(}\sqrt{\rho}(u-m_{1})\big{)}(t)\|_{L^2}^2+\overline{\rho_{0}}\|(\rho-\overline{\rho_{0}})(t)\|_{L^{2}}^2).
\end{split}
\end{equation}
 Due to (\ref{rho2}) and (\ref{rhocnsv}), it holds
\begin{equation}\label{Pi2}
\left\{
\begin{split}
&\|\Pi_{\gamma}(\rho|\overline{\rho_{0}})(t)\|_{L^1}\geq \min{\{\frac{\gamma}{2}(\rho_{+}+\overline{\rho_{0}})^{\gamma-2},\overline{\rho_{0}}^{\gamma-2}\}}\|(\rho-\overline{\rho_{0}})(t)\|_{L^2}^2,\\
&\|\Pi_{\gamma}(\rho|\overline{\rho_{0}})(t)\|_{L^1}\leq \max{\{\frac{\gamma}{2}(\rho_{+}+\overline{\rho_{0}})^{\gamma-2},\overline{\rho_{0}}^{\gamma-2}\}}\|(\rho-\overline{\rho_{0}})(t)\|_{L^2}^2,
\end{split}
\right.
\end{equation}
which together with (\ref{ppp}) implies (\ref{perturb}) directly.


We are going to estimate (\ref{perturb-}). It follows from $(\ref{m1})_{1}$, (\ref{J1}) and (\ref{m1m2}) that
\begin{align}
&(\mathcal{J}(\rho-\overline{\rho_{0}}))_{t}=-\mathcal{J}((\rho u)_{x})=\overline{\rho u}-\rho u=-\rho(u-m_{1})-(\rho-\overline{\rho_{0}})m_{1}. \label{m2111}
\end{align}
Since it holds $\mathcal{J}(\rho-\overline{\rho_{0}})(1)=\mathcal{J}(\rho-\overline{\rho_{0}})(0)$, we deduce by the equations (\ref{m21111}) and (\ref{m2111}) and integration by parts that
\begin{equation}\label{perturb1}
\begin{split}
&\frac{d}{dt}\int_{\mathbb{T}}[\rho (u-m_{1})\mathcal{J}(\rho-\overline{\rho_{0}})](x,t)dx\\
&\quad=\int_{\mathbb{T}}[(\rho^{\gamma}-\overline{\rho_{0}}^{\gamma})(\rho-\overline{\rho_{0}})](x,t)dx-\int_{\mathbb{T}}[\overline{\rho_{0}}\rho|u-m_{1}|^2+\mu(\rho)u_{x}(\rho-\overline{\rho_{0}})](x,t)dx\\
&\quad\quad+\int_{\mathbb{T}}\mathcal{J}(\rho-\overline{\rho_{0}})(x,t)\Big{(}-[\rho n(u-w)](x,t)+\frac{\rho(x,t)}{\overline{\rho_{0}}}\int_{\mathbb{T}} [\rho n (u-w)](y,t)dy\Big{)}dx.
\end{split}
\end{equation}
To estimate the first term on the right-hand side of (\ref{perturb1}), by $(\ref{basiccnsv})_{1}$, we infer
\begin{equation}\label{perturb11}
\begin{split}
\int_{\mathbb{T}}[(\rho^{\gamma}-\overline{\rho_{0}}^{\gamma})(\rho-\overline{\rho_{0}})](x,t)dx=\int_{\mathbb{T}}\big{(}|\rho-\overline{\rho_{0}}|^2\frac{\rho^{\gamma}-\overline{\rho_{0}}^{\gamma}}{\rho-\overline{\rho_{0}}}\big{)}(x,t)dx\geq \gamma(\overline{\rho_{0}})^{\gamma-1}\|(\rho-\overline{\rho_{0}})(t)\|_{L^2}^2.
\end{split}
\end{equation}
One can show
\begin{equation}\label{perturb12}
\begin{split}
&|\int_{\mathbb{T}}[\overline{\rho_{0}}\rho|u-m_{1}|^2+\mu(\rho)u_{x}(\rho-\overline{\rho_{0}})](x,t)dx|\\
&\quad\leq \overline{\rho_{0}}^2\|(u-m_{1})(t)\|_{L^{\infty}}^2+\mu(\rho_{+})\|u_{x}(t)\|_{L^2}\|(\rho-\overline{\rho_{0}})(t)\|_{L^2}\\
&\quad\leq \frac{\gamma(\overline{\rho_{0}})^{\gamma-1}}{4}\|(\rho-\overline{\rho_{0}})(t)\|_{L^2}^2+(\frac{\mu^{2}(\rho_{+})}{\gamma(\overline{\rho_{0}})^{\gamma-1}}+\overline{\rho_{0}}^2)\|u_{x}(t)\|_{L^2}^2,
\end{split}
\end{equation}
where we have used $(\ref{rhocnsv})_{2}$ and (\ref{um1infty}). It also follows from $(\ref{basiccnsv})$, (\ref{rhocnsv}) and (\ref{J}) that
\begin{equation}\label{perturb13}
\begin{split}
&\Big|\int_{\mathbb{T}}\mathcal{J}(\rho-\overline{\rho_{0}})(x,t)\Big{(}-[\rho n(u-w)](x,t)+\frac{\rho(x,t)}{\overline{\rho_{0}}}\int_{\mathbb{T}} [\rho n (u-w)](y,t)dy\Big{)}dx \Big|\\
&\quad\leq \|\mathcal{J}(\rho-\overline{\rho_{0}})(t)\|_{L^{\infty}}\|\big{(}\rho f(u-v)\big{)}(t)\|_{\mathcal{L}^1}\\
&\quad\leq 2\rho_{+}^{\frac{1}{2}}\|(\rho-\overline{\rho_{0}})(t)\|_{L^1}\|f(t)\|_{\mathcal{L}^1}^{\frac{1}{2}}\|\big{(}\sqrt{\rho f}(u-v)\big{)}(t)\|_{\mathcal{L}^2}\\
&\quad\leq \frac{\gamma(\overline{\rho_{0}})^{\gamma-1}}{4}\|(\rho-\overline{\rho_{0}})(t)\|_{L^2}^2+\frac{4\rho_{+}\overline{n_{0}}}{\gamma(\overline{\rho_{0}})^{\gamma-1}}\|\big{(}\sqrt{\rho f}(u-v)\big{)}(t)\|_{\mathcal{L}^2}^2.
\end{split}
\end{equation}
Substituting (\ref{perturb11})-(\ref{perturb12}), (\ref{perturb13}) into (\ref{perturb1}) and making use of (\ref{Pi2}), we gain (\ref{perturb-}).

Let $\mathcal{E}(t)$ and $\mathcal{D}(t)$ be given by (\ref{ED}). For any $\alpha>0$, define
\begin{equation}
\left\{
\begin{split}
&\mathcal{E}^{\alpha}(t)=:\mathcal{E}(t)-\alpha\int_{\mathbb{T}}[\rho(u-m_{1})\mathcal{J}(\rho-\overline{\rho_{0}})](x,t)dx,\\
&\mathcal{D}^{\alpha}(t)=:\mathcal{D}(t)+\alpha\frac{d}{dt}\int_{\mathbb{T}}[\rho(u-m_{1})\mathcal{J}(\rho-\overline{\rho_{0}})](x,t)dx.
\end{split}
\right.
\end{equation}
Thus, it follows from (\ref{entropydissipation}) that
\begin{equation}\label{entropydissipation11}
\begin{split}
\frac{d}{dt}\mathcal{E}^{\alpha}(t)+\mathcal{D}^{\alpha}(t)= 0.
\end{split}
\end{equation}
Making use of (\ref{perturb}), one has
\begin{equation}\label{dissipating1}
\begin{split}
&(1-c_{1}\alpha)\mathcal{E}(t)\leq \mathcal{E}^{\alpha}(t)\leq(1+c_{1}\alpha)\mathcal{E}(t).
\end{split}
\end{equation}
We also deduce from (\ref{m20}) and (\ref{lowerboundrho}) that
\begin{equation}\nonumber
\begin{split}
&\int_{\mathbb{T}\times\mathbb{R}}\rho(x,t)|u(x,t)-v|^2f(x,v,t)dvdx\\
&\quad\geq \rho_{-}\int_{\mathbb{T}\times\mathbb{R}}|u(x,t)-m_{1}(t)+m_{1}(t)-m_{2}(t)+m_{2}(t)-v|^2f(x,v,t)dvdx\\
&\quad=\rho_{-}\int_{\mathbb{T}\times\mathbb{R}} |u(x,t)-m_{1}(t)|^2f(x,v,t)dvdx+\rho_{-}|(m_{1}-m_{2})(t)|^2\int_{\mathbb{T}\times\mathbb{R}} f(x,v,t)dvdx\\
&\quad\quad+\rho_{-}\int_{\mathbb{T}\times\mathbb{R}} |v-m_{2}(t)|^2f(x,v,t)dvdx+2\rho_{-}(m_{1}-m_{2})(t)\int_{\mathbb{T}\times\mathbb{R}}  (u(x,t)-m_{1}(t))f(x,v,t)dvdx\\
&\quad\quad+2\rho_{-}\int_{\mathbb{T}\times\mathbb{R}}  (u(x,t)-m_{1}(t))(m_{2}(t)-v)f(x,v,t)dvdx,
\end{split}
\end{equation}
which together with $(\ref{basiccnsv})_{2}$, (\ref{um1infty}) and the Young's inequality leads to
\begin{equation}\label{this}
\begin{split}
&\|\big{(}\sqrt{\rho f}(u-v)\big{)}(t)\|_{\mathcal{L}^2}^2\\
&\quad\geq \rho_{-}\overline{n_{0}}\|(u-m_{1})(t)\|_{L^{\infty}}^2+\rho_{-}\overline{n_{0}}|(m_{1}-m_{2})(t)|^2+\rho_{-}\|\big{(}(v-m_{2})f\big{)}(t)\|_{\mathcal{L}^2}^2\\
&\quad\quad-2\rho_{-}\overline{n_{0}}|(m_{1}-m_{2})(t)|\|(u-m_{1})(t)\|_{L^{\infty}}-2\rho_{-}\overline{n_{0}}^{\frac{1}{2}}\|\big{(}(v-m_{2})f\big{)}(t)\|_{\mathcal{L}^2}\|(u-m_{1})(t)\|_{L^{\infty}}\\
&\quad\geq -3\rho_{-}\overline{n_{0}}\|u_{x}(t)\|_{L^2}^2+\frac{\rho_{-}\overline{n_{0}}}{2}|(m_{1}-m_{2})(t)|^2+\frac{\rho_{-}}{2}\|\big{(}(v-m_{2})f\big{)}(t)\|_{\mathcal{L}^2}^2.
\end{split}
\end{equation}
In accordance to (\ref{ENSsim}),  (\ref{perturb-}), and (\ref{this}), there is a constant $c_{3}>0$ independent of time $T$ such that it holds
 \begin{equation}\label{dissipating2}
 \begin{split}
 &\mathcal{D}^{\alpha}(t) \geq \alpha c_{0}\|\Pi_{\gamma}(\rho|\overline{\rho_{0}})(t)\|_{L^1}\\
 &\quad\quad~\quad+c_{3}(1-c_{1}\alpha)\big{(}\|\big{(}\sqrt{\rho}(u-m_{1})\big{)}(t)\|_{L^2}^2+\|\big{(}(v-m_{2})f\big{)}(t)\|_{\mathcal{L}^2}^2+|(m_{1}-m_{2})(t)|^2\big{)}.
 \end{split}
 \end{equation}
 Therefore, choosing $\alpha=\frac{1}{2c_{1}}$ in (\ref{entropydissipation11}), one can show by (\ref{entropydissipation11})-(\ref{dissipating1}) and (\ref{dissipating2}) that
\begin{equation}\nonumber
\begin{split}
&\mathcal{D}^{\alpha}(t)\geq \lambda_{1}\mathcal{E}^{\alpha}(t),\quad \frac{d}{dt}\mathcal{E}^{\alpha}(t)+\lambda_{1}\mathcal{E}^{\alpha}(t)\leq 0,\quad \lambda_{1}=: \frac{1}{2}\min\{\frac{c_{0}}{c_{1}},c_{3}\}.
\end{split}
\end{equation}
Applying the Gr$\rm{\ddot{o}}$nwall's inequality and making use of (\ref{Pi2}), (\ref{lowerboundrho}) and $(\ref{dissipating1})$, one obtains
\begin{equation}
\begin{split}
\|(\rho-\overline{\rho_{0}})(t)\|_{L^2}+\|(u-m_{1})(t)\|_{L^2}+\|\big{(}\sqrt{f}(v-m_{2})\big{)}(t)\|_{\mathcal{L}^2}+|(m_{1}-m_{2})(t)|\leq Ce^{-\frac{\lambda_{1}}{2} t}.\label{b111}
\end{split}
\end{equation}

Moreover, by (\ref{rhoh1uniform}) and (\ref{b111}), it holds for any $t\in[0,T]$,
\begin{equation}
\begin{split}
\|(\rho-\overline{\rho_{0}})(t)\|_{C^{0}}\leq C\|(\rho-\overline{\rho_{0}})(t)\|_{L^{2}}^{\frac{1}{2}}\|\rho_{x}(t)\|_{L^2}^{\frac{1}{2}}\leq Ce^{-\frac{\lambda_{1}}{4} t}.\label{brho1}
\end{split}
\end{equation}
Since the conservation laws of mass and momentum implies
$$
 m_{1}=\frac{1}{\overline{\rho_{0}}}(\overline{\rho_{0}u_{0}}+\overline{n_{0}w_{0}}-\overline{n_{0}} m_{2}),
$$
we can get
\begin{equation}\label{m1andm2}
\begin{split}
&|(m_{1}-m_{2})(t)|=|(\frac{1}{\overline{\rho_{0}} }(\overline{\rho_{0}u_{0}}+\overline{n_{0}w_{0}}-\overline{n_{0}} m_{2})-m_{2})(t)|=\frac{\overline{\rho_{0}}+\overline{n_{0}}}{\overline{\rho_{0}}}|(m_{2}-u_{s})(t)|,
\end{split}
\end{equation}
where the constant $u_{s}$ is given by (\ref{rhoinfty}). The combination of (\ref{b111}) and (\ref{m1andm2}) leads to
\begin{equation}
\begin{split}
|(m_{1}-u_{s})(t)|+|(m_{2}-u_{s})(t)|\leq C|(m_{1}-m_{2})(t)|\leq Ce^{-\frac{\lambda_{1}}{2} t}.\label{m1m2b1}
\end{split}
\end{equation}
For the fluid velocity $u$, we also apply (\ref{lowerboundrho}) and (\ref{b111}) to have
\begin{equation}
\begin{split}
&\|(u-u_{s})(t)\|_{L^2}\leq\|(u-m_{1})(t)\|_{L^{2}}+|(m_{1}-u_{s})(t)|\\
&\quad\quad\quad\quad\quad\quad~~\leq \rho_{-}^{-\frac{1}{2}}\|\sqrt{\rho}(u-m_{1})(t)\|_{L^2}+|(m_{1}-u_{s})(t)|\leq Ce^{-\frac{\lambda_{1}}{2} t}.\label{ub1}
\end{split}
\end{equation}
To estimate $f$, one deduces from (\ref{b111}) and (\ref{ub1}) that
\begin{equation}
\begin{split}
&\|\big{(}\sqrt{f}(v-u_{s})\big{)}(t)\|_{\mathcal{L}^2}\leq \|\big{(}\sqrt{f}(v-m_{2})\big{)}(t)\|_{\mathcal{L}^2}+\|f(t)\|_{\mathcal{L}^1}^{\frac{1}{2}}|(m_{2}-u_{s})(t)|\leq C e^{-\frac{\lambda_{1}}{2} t}.\label{fb1}
\end{split}
\end{equation}
And thanks to (\ref{nw}), (\ref{fb1}) and the H$\rm{\ddot{o}}$lder's inequality, it holds
\begin{equation}
\begin{split}
&\int_{\mathbb{T}} (n|w-u_{s}|^2)(x,t)dx=\int_{\{n(x,t)\neq 0\}} \frac{|\int(v-u_{s})f(x,v,t)dv|^2}{ n(x,t)} dx\\
&\quad\quad\quad\quad\quad\quad\quad\quad\quad~~\leq \int_{\mathbb{T}\times\mathbb{R}} |v-u_{s}|^2f(x,v,t)dvdx\leq C e^{-\lambda_{1} t}.\label{bnwb1}
\end{split}
\end{equation}
Then according to the Definition \ref{defn11} and (\ref{fb1}), we have
\begin{equation}\label{fb11}
\begin{split}
 &{\rm{W_{1}}}\big{(}f(t),(n\delta(v-u_{s}))(t)\big{)}\\
 &\quad=\sup_{\|\nabla_{x,v}\psi\|_{\mathcal{L}^{\infty}}\leq 1}\Big{\{}\int_{\mathbb{T}\times\mathbb{R}}\big{(}f(x,v,t)\psi(x,v)dvdx-\int_{\mathbb{T}\times\mathbb{R}} \psi(x,v)  \delta(v-u_{s})\big{)} \int_{\mathbb{R}}f(x,\widetilde{v},t)d\widetilde{v}  dvdx\Big{\}}\\
&\quad=\sup_{\|\nabla_{x,v}\psi\|_{\mathcal{L}^{\infty}}\leq 1}\Big{\{}\int_{\mathbb{T}\times\mathbb{R}} f(x,v,t)(\psi(x,v)-\psi(x,u_{s}))dvdx\Big{\}}\\
&\quad\leq \int_{\mathbb{T}\times\mathbb{R}} |v-u_{s}|f(x,v,t)dvdx\\
&\quad\leq\|\big{(}\sqrt{f}(v-u_{s})\big{)}(t)\|_{\mathcal{L}^2}\|f(t)\|_{\mathcal{L}^1}^{\frac{1}{2}}\leq Ce^{-\frac{\lambda_{1}}{2}t}.
\end{split}
\end{equation}

We show that the compact support of $f$ in velocity concentrates at $u_{s}$ exponentially in time. It is easy to verify
\begin{equation}\nonumber
\begin{split}
u_{s}=e^{-\int_{0}^{t}\rho(X^{x,v,t}(\omega),\omega)d\omega} u_{s}+\int_{0}^{t}e^{-\int_{\tau}^{t}\rho(X^{x,v,t}(\omega),\omega)d\omega}\rho(X^{x,v,t}(\tau),\tau)u_{s}d\tau,
\end{split}
\end{equation}
which together with (\ref{xv1}) leads to
\begin{equation}\label{vus}
\begin{split}
&v-u_{s}=e^{-\int_{0}^{t}\rho(X^{x,v,t}(\tau),\tau)d\tau}(V^{x,v,t}(0)-u_{s})\\
&\quad\quad\quad\quad+\int_{0}^{t}e^{-\int_{\tau}^{t}\rho(X^{x,v,t}(\omega),\omega)d\omega}\big{(}\rho (u-u_{s})\big{)}(X^{x,v,t}(\tau),\tau)d\tau,
\end{split}
\end{equation}
where the bi-characteristic curves $(X^{x,v,t}(s),V^{x,v,t}(s))$ are given by (\ref{XV}). By (\ref{m1m2b1})-(\ref{ub1}) and the Gagliardo-Nirenberg's inequality, one can show
\begin{equation}\label{pppppp}
\begin{split}
&\|(u-u_{s})(t)\|_{L^{\infty}}\leq \|(u-\overline{u})(t)\|_{L^{\infty}}+|(\overline{u}-u_{s})(t)|\\
&\quad\quad\quad\quad\quad\quad\quad\leq C\|(u-\overline{u})(t)\|_{L^2}^{\frac{1}{2}}\|u_{x}(t)\|_{L^2}^{\frac{1}{2}}+|\int_{\mathbb{T}} (u-u_{s})(x,t)dx|\\
&\quad\quad\quad\quad\quad\quad\quad\leq C(\|(u-m_{1})(t)\|_{L^2}+|(m_{1}-\overline{u})(t)|)^{\frac{1}{2}}\|u_{x}(t)\|_{L^2}^{\frac{1}{2}}+\|(u-u_{s})(t)\|_{L^2}\\
&\quad\quad\quad\quad\quad\quad\quad\leq Ce^{-\frac{\lambda_{1}}{4}t}\|u_{x}(t)\|_{L^2}^{\frac{1}{2}}+Ce^{-\frac{\lambda_{1}}{2}t}.
\end{split}
\end{equation}
It derives from $(\ref{basiccnsv})_{4}$, (\ref{fformula}), (\ref{ub1}), (\ref{vus}), (\ref{pppppp}) and the H${\rm{\ddot{o}}}$lder inequality for any $(x,t)\in\mathbb{T}\times[0,\infty)$ that
\begin{equation}\label{vb1}
\begin{split}
&\underset{v\in \Sigma(x,t)}{\rm{sup}}|v-u_{s}|\\
&\quad\leq e^{-\rho_{-}t}(|u_{s}|+R_{0})+C\int_{0}^{t}e^{-\rho_{-}(t-\tau)}\|(u-u_{s})(\tau)\|_{L^{\infty}}d\tau\\
&\quad\leq e^{-\rho_{-}t}(|u_{s}|+R_{0})+C\int_{0}^{t}e^{-\rho_{-}(t-\tau)}\big{(}e^{-\frac{\lambda_{1}}{4}\tau}\|u_{x}(\tau)\|_{L^2}^{\frac{1}{2}}+e^{-\frac{\lambda_{1}}{2}\tau}\big{)}d\tau\\
&\quad\leq Ce^{-\rho_{-}t}+C\|u_{x}\|_{L^2(0,t;L^2)}^{\frac{1}{2}}\big{(}\int_{0}^{t}e^{-\frac{4\rho_{-}}{3}(t-\tau)}e^{-\frac{\lambda_{1}}{3}t}d\tau\big{)}^{\frac{3}{4}}+C\int_{0}^{t}e^{-\rho_{-}(t-\tau)}e^{-\frac{\lambda_{1}}{2}\tau}d\tau\\
&\quad\leq C(e^{-\frac{\rho_{-}}{2}t}+e^{-\frac{\lambda_{1}}{8}t}),
\end{split}
\end{equation}
where $\Sigma(x,t)$ is given by (\ref{Sigma}) and one has used the fact for some constants $a_{1}>0$ and $a_{2}>0$ that
\begin{equation}\nonumber
\begin{split}
&\int_{0}^{t}e^{-a_{1}(t-\tau)}e^{-a_{2}\tau}d\tau\leq \int_{0}^{\frac{t}{2}}e^{-a_{1}(t-\tau)}e^{-a_{2}\tau}d\tau+\int_{\frac{t}{2}}^{t}e^{-a_{1}(t-\tau)}e^{-a_{2}\tau}d\tau\\
&\quad\quad\quad\quad\quad\quad\quad\quad\quad\leq \frac{1}{a_{2}}e^{-\frac{a_{1}}{2}t}+\frac{1}{a_{1}}e^{-\frac{a_{2}}{2}t}.
\end{split}
\end{equation}
The combination of (\ref{brho1}), (\ref{ub1}), (\ref{fb1})-(\ref{fb11}) and(\ref{vb1}) leads to $(\ref{decay11})_{3}$. The proof of Theorem \ref{decay} is completed.




